local config = {
  ui_story_5071_50710101_1_dialog_content = "<size=45>Uraaagh—</size>",
  ui_story_5071_50710101_2_dialog_content = "<color=#e8d9bb>Pimba!</color>",
  ui_story_5071_50710101_3_dialog_content = "...",
  ui_story_5071_50710101_4_dialog_content = "Urgh... *tosse*",
  ui_story_5071_50710101_5_dialog_content = "Não...",
  ui_story_5071_50710101_6_dialog_content = "Ouvi dizer que ele matou todo mundo!",
  ui_story_5071_50710101_7_dialog_content = "Ele é o único que saiu vivo do <color=#FFB400>Poço</color>. Deve ser verdade.",
  ui_story_5071_50710101_8_dialog_content = "Não consigo acreditar no que estou ouvindo. Ele até matou seu irmão mais próximo para ganhar poder...",
  ui_story_5071_50710101_9_dialog_content = "Nós... Podemos realmente deixar o futuro de Umbraton nas mãos de uma pessoa assim?",
  ui_story_5071_50710101_10_dialog_content = "...",
  ui_story_5071_50710101_11_dialog_content = "E agora...",
  ui_story_5071_50710101_12_dialog_content = "Você está...",
  ui_story_5071_50710101_13_dialog_content = "<size=50>... feliz?</size>",
  ui_story_5071_50710101_14_dialog_content = "<color=#e8d9bb>Toc, toc!</color>",
  ui_story_5071_50710101_15_dialog_content = "!",
  ui_story_5071_50710101_16_dialog_content = "Todos que assumiram a forma de sombra correm o risco de serem devorados pela sombra.",
  ui_story_5071_50710101_17_dialog_content = "O passado não é a única coisa varrida para debaixo do tapete pela sombra, certo, meu irmão?",
  ui_story_5071_50710101_18_dialog_content = "<color=#e8d9bb>Toc, toc!</color>",
  ui_story_5071_50710101_19_dialog_content = "Pai, sou eu, Bethel.",
  ui_story_5071_50710101_20_dialog_content = "Pode entrar.",
  ui_story_5071_50710101_21_dialog_content = "Pai, eu já—",
  ui_story_5071_50710101_22_dialog_content = "...",
  ui_story_5071_50710101_23_dialog_content = "Você está bem, pai? Nunca te vi tão exausto...",
  ui_story_5071_50710101_24_dialog_content = "Haha, a moderação é a chave, não importa o quanto você goste de um bom vinho. Acho que estou na idade em que tenho que ter cuidado com essas coisas.",
  ui_story_5071_50710101_25_dialog_content = "Por favor, não menospreze isso assim.",
  ui_story_5071_50710101_26_dialog_content = "Desconsidere isso como uma brincadeira então. Vamos falar sobre você.",
  ui_story_5071_50710101_27_dialog_content = "Claro. Estou preparado para a viagem.",
  ui_story_5071_50710101_28_dialog_content = "A estrada para a Baía dos Pavilhões Gêmeos foi consertada e protegida o suficiente para que avistamentos de Eclipsites sejam raros.",
  ui_story_5071_50710101_29_dialog_content = "Mas fique de olho no que nossa Sombra não consegue ver.",
  ui_story_5071_50710101_30_dialog_content = "Naturalmente, minha querida, acredito que você lidará perfeitamente com a reunião com os \"clientes\" lá.",
  ui_story_5071_50710101_31_dialog_content = "Não vou decepcioná-lo, pai.",
  ui_story_5071_50710101_32_dialog_content = "Bethel, como chefe da guilda, seu único dever é para com Umbraton, não para alguém.",
  ui_story_5071_50710101_33_dialog_content = "Pai…",
  ui_story_5071_50710101_34_dialog_content = "Tudo bem, eu também deveria ir. Deixe-me acompanhar você até a saída.",
  ui_story_5071_50710101_35_dialog_content = "...",
  ui_story_5071_50710101_36_dialog_content = "Uma guilda que surgiu das sombras para voar livremente pelos céus...",
  ui_story_5071_50710101_37_dialog_content = "<color=#FFB400>Seu sonho</color>... Já se tornou realidade?",
  ui_story_5071_50710101_38_dialog_content = "<color=#e8d9bb>Clique!</color>",
  ui_story_5071_50710101_39_dialog_content = "Não se engane, eu sinto cheiro de fofoca no ar!",
  ui_story_5071_50710101_40_dialog_content = "Hum?",
  ui_story_5071_50710101_41_dialog_content = "Olá, eu sou Brandy, repórter do The Daily Scoop!",
  ui_story_5071_50710101_42_dialog_content = "May Eu peço sua opinião sobre o gigantesco <color=#FFB400>Dirigível Cloudrover</color> construído pela Guilda Cloudrover?",
  ui_story_5071_50710101_43_dialog_content = "Sem comentários.",
  ui_story_5071_50710101_44_dialog_content = "Foi uma eliminação rápida. Esses magnatas são tão difíceis de abrir quanto mariscos.",
  ui_story_5071_50710101_45_dialog_content = "Mas olha quem está aqui—",
  ui_story_5071_50710101_46_dialog_content = "PlayerName! Por aqui, por aqui!",
  ui_story_5071_50710101_47_dialog_content = "<color=#e8d9bb>Clique!</color>",
  ui_story_5071_50710101_48_dialog_content = "Você foi convidado para o <color=#FFB400>lançamento inaugural</color> de hoje, PlayerName? Que tal uma palavra no dirigível?",
  ui_story_5071_50710101_49_dialog_content = "Parece familiar.",
  ui_story_5071_50710101_50_dialog_content = "Mesmo que a tecnologia usada neste dirigível seja diferente da dos Colossus, ainda é uma enorme embarcação capaz de voar.",
  ui_story_5071_50710101_51_dialog_content = "Isso parece impressionante.",
  ui_story_5071_50710101_52_dialog_content = "Eu só tinha visto dirigíveis menores antes. Eu não fazia ideia de que a Senhora Sheol tinha feito um dirigível grande o suficiente para carregar toda a sua guilda...",
  ui_story_5071_50710101_53_dialog_content = "Esta Aeronave Cloudrover é o auge dos dirigíveis, mas não tão grande quanto o seu Soroz, certo, PlayerName?",
  ui_story_5071_50710101_54_dialog_content = "Não, mas... Em termos de tamanho, provavelmente ainda é tão grande quanto o Eulogoz, onde realizaram aquele concerto antes.",
  ui_story_5071_50710101_55_dialog_content = "Ah, já vejo a manchete de amanhã agora!",
  ui_story_5071_50710101_56_dialog_content = "\"Celestita proclama: A Nave Aérea Cloudrover não é páreo para Soroz!\"",
  ui_story_5071_50710101_57_dialog_content = "E-Espera, por que você está distorcendo minhas palavras assim?",
  ui_story_5071_50710101_58_dialog_content = "<color=#e8d9bb>Bzz—Bzz—</color>",
  ui_story_5071_50710101_59_dialog_content = "Não tema dano ou fracasso. A persistência se transformará em sorte!",
  ui_story_5071_50710101_60_dialog_content = "Já faz muito tempo, meus queridos amigos! Como estão todos vocês?",
  ui_story_5071_50710101_61_dialog_content = "Não é... Goldie, aquele ídolo que está realmente popular em Umbraton no momento? A Guilda Cloudrover é tão impressionante como sempre se conseguiram que ela comparecesse!",
  ui_story_5071_50710101_62_dialog_content = "Você não sabe? A Senhora Sheol, líder da Guilda Cloudrover, é quem a tornou famosa!",
  ui_story_5071_50710101_63_dialog_content = "A Guilda Cloudrover até se envolveu na indústria do entretenimento? Em quantas indústrias a Senhora Sheol está envolvida?",
  ui_story_5071_50710101_64_dialog_content = "Quem se importa com ídolos ou aeronaves? São todos apenas truques... A única razão pela qual estou aqui é porque o Shadowlord está presente.",
  ui_story_5071_50710101_65_dialog_content = "Por favor, fiquem calmos, pessoal. A cerimônia começará em breve!",
  ui_story_5071_50710101_66_dialog_content = "Até então, gostaria de apresentar um single novinho em folha para vocês—",
  ui_story_5071_50710101_67_dialog_content = "<size=45>Sonhos ao Alcance!</size>",
  ui_story_5071_50710101_68_dialog_content = "Por favor, aspire a cavalgar o vento e tocar o céu em breve comigo!",
  ui_story_5071_50710101_69_dialog_content = "♪ No céu sem limites, as nuvens manifestam esperança, enquanto os sonhos surgem no horizonte como o sol da manhã ♪",
  ui_story_5071_50710101_70_dialog_content = "♪ Abra suas asas, suba ao céu e toque a luz brilhante ♪",
  ui_story_5071_50710101_71_dialog_content = "(É isso aí Goldie para você, hein? Tudo o que ela precisou fazer foi cantar para acalmar todos aqueles passageiros irritados. Eles até estão balançando a cabeça no ritmo da música dela agora.)",
  ui_story_5071_50710101_72_dialog_content = "(Ainda assim... Se a Goldie está aqui, então seu clube de fãs histéricos também deveria estar aqui para estourar meus tímpanos, certo?)",
  ui_story_5071_50710101_73_dialog_content = "(Não reconheço nenhuma das pessoas que a Senhora Sheol convidou para o dirigível...)",
  ui_story_5071_50710101_74_dialog_content = "Ele está aqui! Ele está aqui! O Shadowlord está aqui! Vamos lá—",
  ui_story_5071_50710101_75_dialog_content = "(O Senhor Sombrio também tá aqui? Isso deve ser um evento especial afinal...)",
  ui_story_5071_50710101_76_dialog_content = "Pontual como sempre, Senhor Sombrio. Mais um minuto e você perderia o corte da fita.",
  ui_story_5071_50710101_77_dialog_content = "Fazer uma entrada no momento adequado ao participar de eventos como este é um segredo que aprendi com você, Senhora Sheol.",
  ui_story_5071_50710101_78_dialog_content = "Senhor das Sombras! Estou tão feliz em vê-lo em uma ocasião tão alegre!",
  ui_story_5071_50710101_79_dialog_content = "Meu querido Senhor das Sombras, você ainda se lembra de mim?",
  ui_story_5071_50710101_80_dialog_content = "Senhor Sombrio, solicitei uma reunião privada com você há algum tempo. Já teve tempo de ler o meu convite?",
  ui_story_5071_50710101_81_dialog_content = "Senhor das Sombras! Não se esqueça de mim! Senhor das Sombras—",
  ui_story_5071_50710101_82_dialog_content = "Senhoras e senhores, o Senhor das Sombras se encarregou de encontrar cada um de vocês a bordo da aeronave hoje.",
  ui_story_5071_50710101_83_dialog_content = "Claro, apenas aqueles que solicitaram uma audiência com ele com bastante antecedência recebem tal honra.",
  ui_story_5071_50710101_84_dialog_content = "Mas por agora, vamos todos voltar nossa atenção para nossa maravilhosa cantora e sua performance animada.",
  ui_story_5071_50710101_85_dialog_content = "Sinceramente, eu nunca soube que encontrar com o Senhor das Sombras exigia tantas regras.",
  ui_story_5071_50710101_86_dialog_content = "...",
  ui_story_5071_50710101_87_dialog_content = "Perdoe-me, não tive a chance de me apresentar adequadamente. Eu sou Hanstie, líder da Guilda Continental. Esta é a minha primeira vez aqui e não estou acostumado com as formalidades de Umbraton. Por favor, me desculpe se interrompi o prazer de alguém nas festividades.",
  ui_story_5071_50710101_88_dialog_content = "Olhe... Não é a Sra. Hanstie da Guilda Continental? Ouvi dizer que ela nunca aparece em lugar nenhum! A Senhora Sheol certamente é carismática... ou seria este o carisma do Shadowlord?",
  ui_story_5071_50710101_89_dialog_content = "A Guilda Continental? Existe tal guilda em Umbraton?",
  ui_story_5071_50710101_90_dialog_content = "A Guilda Continental começou a fazer negócios em pequenas cidades fora de Umbraton nos últimos anos. Embora tenha acabado de estabelecer uma posição em Umbraton, seu ímpeto de desenvolvimento não deve ser subestimado!",
  ui_story_5071_50710101_91_dialog_content = "Que honra tê-la presente, Sra. Hanstie.",
  ui_story_5071_50710101_92_dialog_content = "A Guilda Cloudrover convidou todos os líderes de guilda respeitáveis em Umbraton para este evento. Como eu poderia perder uma oportunidade como essa?",
  ui_story_5071_50710101_93_dialog_content = "Além disso, quando ouvi que o famoso Senhor Sombrio iria aparecer, eu sabia que tinha que estar aqui.",
  ui_story_5071_50710101_94_dialog_content = "Ah, você deve ser a Senhora Sheol, líder da <color=#FFB400>Guilda Cloudrover</color> e uma figura que só posso admirar.",
  ui_story_5071_50710101_95_dialog_content = "Você brinca, Sra. Hanstie.",
  ui_story_5071_50710101_96_dialog_content = "A rede da <color=#FFB400>Guilda Continental</color> permeia todo o Astra. O céu e a terra podem e coexistem.",
  ui_story_5071_50710101_97_dialog_content = "Seu dirigível é bastante impressionante, devo dizer.",
  ui_story_5071_50710101_98_dialog_content = "É uma honra para a Guilda Cloudrover ter o favor da Sra. Hanstie.",
  ui_story_5071_50710101_99_dialog_content = "Agora então, Senhor das Sombras, posso ter uma palavra com você em particular?",
  ui_story_5071_50710101_100_dialog_content = "Perdoe-me, Sra. Hanstie—",
  ui_story_5071_50710101_101_dialog_content = "Eu estava falando com o Senhor das Sombras, meu adorável pequeno polvo.",
  ui_story_5071_50710101_102_dialog_content = "...",
  ui_story_5071_50710101_103_dialog_content = "Vou considerar seu pedido cuidadosamente, Sra. Hanstie.",
  ui_story_5071_50710101_104_dialog_content = "Muito bem então. Aguardo ansiosamente sua resposta.",
  ui_story_5071_50710101_105_dialog_content = "Marque um horário de reunião entre eu e a senhora, Kleken.",
  ui_story_5071_50710101_106_dialog_content = "... Como quiser, meu senhor.",
  ui_story_5071_50710101_107_dialog_content = "(Espera, o Senhor Sombrio está quebrando suas próprias regras por aquela mulher extravagante?)",
  ui_story_5071_50710101_108_dialog_content = "Por quanto tempo mais você vai ficar aí no canto, PlayerName?",
  ui_story_5071_50710101_109_dialog_content = "C-Cumprimentos, Senhor das Sombras! Todos estavam tão ocupados até agora que eu não tive a chance de dizer oi antes.",
  ui_story_5071_50710101_110_dialog_content = "Vamos, é a nossa vez de estar no palco.",
  ui_story_5071_50710101_111_dialog_content = "Hã?",
  ui_story_5071_50710101_112_dialog_content = "Espero que todos tenham amado essa música! Em seguida, damos as boas-vindas a—",
  ui_story_5071_50710101_113_dialog_content = "Senhor Sombrio Istvan, líder da Guilda Cloudrover, Senhora Sheol, e PlayerName, convidado de honra de Astra, que cortarão a fita juntos!",
  ui_story_5071_50710101_114_dialog_content = "Eu não sabia que eles teriam cerimônias assim...",
  ui_story_5071_50710101_115_dialog_content = "Está tudo bem, querido, não fique nervoso. Apenas corte a fita com a tesoura na mão.",
  ui_story_5071_50710101_116_dialog_content = "<color=#e8d9bb>Snip!</color>",
  ui_story_5071_50710101_117_dialog_content = "A Aeronave Cloudrover é financiada e construída pela Senhora Sheol da Guilda Cloudrover, um super navio que combina turismo, compras, lazer e resorts, tudo em um só.",
  ui_story_5071_50710101_118_dialog_content = "A partir de agora, aurorianos comuns como eu podem brincar, fazer compras e viver no céu como os Celestitas!",
  ui_story_5071_50710101_119_dialog_content = "Após o lançamento de hoje, a aeronave vai circular Umbraton e realizar um show de fogos de artifício acima da cidade à noite. Fica mais legal quanto mais eu penso nisso!",
  ui_story_5071_50710101_120_dialog_content = "Mas não se fixe apenas nas vistas e esqueça todos os eventos a bordo!",
  ui_story_5071_50710101_121_dialog_content = "Além do meet-n-greet comigo e da exibição especial de Alleywood de Umbraton, a aeronave também sediará o leilão aéreo mais transparente e conveniente de todos os tempos!",
  ui_story_5071_50710101_122_dialog_content = "Então, vamos todos começar a contagem regressiva agora!",
  ui_story_5071_50710101_123_dialog_content = "Três-",
  ui_story_5071_50710101_124_dialog_content = "Dois-",
  ui_story_5071_50710101_125_dialog_content = "Um!",
  ui_story_5071_50710101_126_dialog_content = "O Dirigível Cloudrover...",
  ui_story_5071_50710101_127_dialog_content = "<size=50>Decola!</size>",
  ui_story_5071_50710101_128_dialog_content = "Oh! Está voando agora. Está realmente voando!",
  ui_story_5071_50710101_129_dialog_content = "Você se impressiona tão facilmente. Não é como se você nunca tivesse estado em um dirigível antes. Quando eu estava em Lumópolis, eu via isso acontecer todos os dias.",
  ui_story_5071_50710101_130_dialog_content = "Embora Lumopolis seja agradável, aquela ilha não pode se mover de jeito nenhum. De qualquer forma, eu realmente admiro o olhar aguçado para investimentos da Senhora Sheol.",
  ui_story_5071_50710101_131_dialog_content = "De fato, um olho aguçado.",
  ui_story_5071_50710101_132_dialog_content = "Mas qualquer coisa que vá para os céus...",
  ui_story_5071_50710101_X132_dialog_content = "Deve descer eventualmente.",
  ui_story_5071_50710201_1_dialog_content = "<color=#e8d9bb>Na suíte de luxo do Dirigível Cloudrover</color>",
  ui_story_5071_50710201_2_dialog_content = "Honrado Senhor das Sombras, estou tão agradecido que finalmente temos a chance de nos encontrar hoje...",
  ui_story_5071_50710201_3_dialog_content = "Graças à sua generosa assistência, meu filho finalmente realizou seu desejo de frequentar a escola em Lumópolis!",
  ui_story_5071_50710201_4_dialog_content = "Haha, essas são notícias emocionantes.",
  ui_story_5071_50710201_5_dialog_content = "Seu filho é muito inteligente e tem suas próprias ideias. O trabalho duro dele levou a isso.",
  ui_story_5071_50710201_6_dialog_content = "No entanto, você parece preocupado?",
  ui_story_5071_50710201_7_dialog_content = "E-Eu simplesmente me preocupo que os nobres e seus filhos irão importuná-lo por causa de seu status...",
  ui_story_5071_50710201_8_dialog_content = "Minha nossa, o que estou dizendo... Senhor das Sombras, por favor, me perdoe por falar tais bobagens.",
  ui_story_5071_50710201_9_dialog_content = "É natural se preocupar com isso. Seu filho é muito talentoso...",
  ui_story_5071_50710201_10_dialog_content = "Estou ansioso pelo seu retorno seguro e pela fundação de uma escola em Umbraton mais do que qualquer outra pessoa.",
  ui_story_5071_50710201_11_dialog_content = "Prometo que todas as suas preocupações nunca se concretizarão.",
  ui_story_5071_50710201_12_dialog_content = "Ouvir você dizer isso faz meu coração se sentir leve como uma pena, meu senhor!",
  ui_story_5071_50710201_13_dialog_content = "Trouxe algumas garrafas de vinho do nosso vinhedo familiar. Por favor, aceite-as como um sinal de nossa gratidão, bem como nosso pedido de desculpas por tomar tanto do seu tempo...",
  ui_story_5071_50710201_14_dialog_content = "Sem problemas. Adeus.",
  ui_story_5071_50710201_15_dialog_content = "<color=#e8d9bb>A bordo do Dirigível Cloudrover, no evento de aperto de mão de Goldie</color>",
  ui_story_5071_50710201_16_dialog_content = "Obrigado pelo seu apoio constante, PlayerName!",
  ui_story_5071_50710201_17_dialog_content = "Não vou te decepcionar e vou continuar fazendo boa música!",
  ui_story_5071_50710201_18_dialog_content = "Não mencione isso! Você realmente tem uma conexão especial com o céu, não é? A música de hoje também foi—",
  ui_story_5071_50710201_19_dialog_content = "Ei! Não deveríamos ter apenas um minuto com Goldie? Você está ultrapassando muito o seu tempo!",
  ui_story_5071_50710201_20_dialog_content = "Desculpe, PlayerName. Não se esqueça de me visitar no escritório quando tiver tempo!",
  ui_story_5071_50710201_21_dialog_content = "Goldie! Goldie! Nós também queremos conversar um pouco mais com você!",
  ui_story_5071_50710201_22_dialog_content = "Em pouco tempo, Goldie transformou tantas pessoas em seus fãs...",
  ui_story_5071_50710201_23_dialog_content = "Parece que todos os meus velhos amigos estão bastante ocupados agora... Acho que terei que andar por aí sozinho.",
  ui_story_5071_50710201_24_dialog_content = "Senhor, você ainda se lembra de mim? Eu costumava ser seu vizinho!",
  ui_story_5071_50710201_25_dialog_content = "Você não estava em casa quando seus pais faleceram... Eu também contribuí para cobrir as despesas do funeral...",
  ui_story_5071_50710201_26_dialog_content = "Obrigado pela generosa ajuda em proporcionar a eles um lugar de descanso pacífico.",
  ui_story_5071_50710201_27_dialog_content = "S-Sim, mas... mas eu preciso da sua ajuda agora mais do que nunca!",
  ui_story_5071_50710201_28_dialog_content = "Graças a você, consegui abrir várias lojas de conveniência. Meu negócio não se compara à Guilda Cloudrover, mas se sai bem por aqui.",
  ui_story_5071_50710201_29_dialog_content = "Infelizmente, as lojas próximas têm trabalhado juntas para me tirar do negócio ultimamente. Já estou à beira da falência...",
  ui_story_5071_50710201_30_dialog_content = "Não sei o que mais fazer, meu senhor. Por favor, me ajude...",
  ui_story_5071_50710201_31_dialog_content = "Você quer que eu te ajude a se livrar deles?",
  ui_story_5071_50710201_32_dialog_content = "I-Isto seria aceitável?",
  ui_story_5071_50710201_33_dialog_content = "Por que não entrar na guilda? Contanto que você opere de acordo com as regulamentações, eles lhe oferecerão uma proteção substancial.",
  ui_story_5071_50710201_34_dialog_content = "Eu... Eu fui informado que para entrar na guilda é necessário uma taxa de adesão pesada...",
  ui_story_5071_50710201_35_dialog_content = "Como você saberia se nunca passou pela porta deles para descobrir a verdade?",
  ui_story_5071_50710201_36_dialog_content = "Eu sabia! Aqueles canalhas estavam mentindo para mim o tempo todo!",
  ui_story_5071_50710201_37_dialog_content = "Então... Eu poderia possivelmente entrar para a sua guilda?",
  ui_story_5071_50710201_38_dialog_content = "Eu não sou o líder da guilda, mas posso te dizer que a porta está sempre aberta para todos.",
  ui_story_5071_50710201_39_dialog_content = "Confie em mim. Você só vai se arrepender de não ter feito isso antes.",
  ui_story_5071_50710201_40_dialog_content = "Ah, obrigado! Muito obrigado, Senhor das Sombras! De agora em diante, sempre prometerei meu apoio a você... e também às decisões da guilda!",
  ui_story_5071_50710201_41_dialog_content = "As pessoas que enterraram seus pais deveriam ter deixado este mundo há muito tempo. Parece que aquele homem e eu compartilhamos um \"hobby\" semelhante.",
  ui_story_5071_50710201_42_dialog_content = "Essa não é a questão, Kleken. Diga a ele o que ele deve fazer a seguir.",
  ui_story_5071_50710201_43_dialog_content = "Muito bem, Senhor das Sombras.",
  ui_story_5071_50710201_44_dialog_content = "<color=#e8d9bb>Fora do cinema do Dirigível Cloudrover</color>",
  ui_story_5071_50710201_45_dialog_content = "Hmm, \"Uma história juvenil baseada em uma história real, 'Chasing Alleywood' está em cartaz com apenas um bilhete restante.\"",
  ui_story_5071_50710201_46_dialog_content = "É este o último trabalho de Lilica? Isso explicaria porque eu não tenho notícias dela há tanto tempo...",
  ui_story_5071_50710201_47_dialog_content = "Bem, não tenho nada melhor para fazer, então eu poderia muito bem mostrar algum apoio!",
  ui_story_5071_50710201_48_dialog_content = "Com licença, eu gostaria de comprar o último ingresso para \"Chasing Alleywood\", por favor!",
  ui_story_5071_50710201_49_dialog_content = "H-Hã? Brandy pegou o último bilhete para si mesma!",
  ui_story_5071_50710201_50_dialog_content = "Qual é o problema com essa criança? Por que ele não fala?",
  ui_story_5071_50710201_51_dialog_content = "Ele está perdido? Por que os pais dele não estão procurando por ele?",
  ui_story_5071_50710201_52_dialog_content = "De quem é essa criança?",
  ui_story_5071_50710201_53_dialog_content = "O que há com todas aquelas pessoas ali? Outro evento?",
  ui_story_5071_50710201_54_dialog_content = "*fungando*",
  ui_story_5071_50710201_55_dialog_content = "Hein? Uma criança pequena?",
  ui_story_5071_50710201_56_dialog_content = "Uaaau—",
  ui_story_5071_50710201_57_dialog_content = "E-Ei! Por que ele de repente se agarra em mim assim?",
  ui_story_5071_50710201_58_dialog_content = "Eles devem ser família... Aquele pobre menino não hesitou em correr até ele.",
  ui_story_5071_50710201_59_dialog_content = "Você é o irmão mais velho deste menino? Como pôde deixá-lo sozinho assim? Olhe só para o rosto dele, pobre e chorando!",
  ui_story_5071_50710201_60_dialog_content = "Você deve ser mais cuidadoso de agora em diante!",
  ui_story_5071_50710201_61_dialog_content = "...",
  ui_story_5071_50710201_62_dialog_content = "...",
  ui_story_5071_50710201_63_dialog_content = "Hum... May Eu posso perguntar quem é você?",
  ui_story_5071_50710201_64_dialog_content = "<color=#e8d9bb>*estômago roncando*</color>",
  ui_story_5071_50710201_65_dialog_content = "Eu... estou com tanta fome...",
  ui_story_5071_50710201_66_dialog_content = "Espero que você esteja bem, Senhor das Sombras?",
  ui_story_5071_50710201_67_dialog_content = "Marquês? Eu pensei que você tem passado todo o seu tempo lendo com sua neta em sua propriedade em Lumópolis recentemente.",
  ui_story_5071_50710201_68_dialog_content = "Haha, se eu não tivesse vindo, temo que um certo grupo e suas chamadas \"reformas\" teriam me roubado tudo o que possuo aqui em Umbraton.",
  ui_story_5071_50710201_69_dialog_content = "Diga-me, com as taxas de associação exorbitantes cobradas pela guilda, como eles poderiam ter sido incapazes de se alimentar adequadamente recentemente?",
  ui_story_5071_50710201_70_dialog_content = "Haha, isso é uma outra história, senhor.",
  ui_story_5071_50710201_71_dialog_content = "Essa sua pequena guilda foi fechada devido a uma violação das regulamentações da guilda.",
  ui_story_5071_50710201_72_dialog_content = "Desde que as correções sejam feitas e as... práticas duvidosas sejam abandonadas, é permitido reabrir.",
  ui_story_5071_50710201_73_dialog_content = "Além disso, a maior parte das taxas de associação pagas são repassadas para Lumópolis como \"imposto sobre a propriedade\", conforme acordado.",
  ui_story_5071_50710201_74_dialog_content = "O restante é gasto na manutenção regular da guilda—",
  ui_story_5071_50710201_75_dialog_content = "Suas palavras enganosas me lembram muito de sua filha adotiva. Se eu não soubesse melhor, diria que ela poderia passar por uma de suas próprias.",
  ui_story_5071_50710201_76_dialog_content = "Por que você se incomodaria em me ver quando já ouviu a proposta do líder da guilda então?",
  ui_story_5071_50710201_77_dialog_content = "Acabe com essa farsa já, Istvan...",
  ui_story_5071_50710201_78_dialog_content = "Você sabe o que Umbraton precisa para manter sua prosperidade atual, não sabe?",
  ui_story_5071_50710201_79_dialog_content = "É a mesma coisa que a Gangue Istvan precisava em sua fundação, lembra?",
  ui_story_5071_50710201_80_dialog_content = "Suas mãos estão muito mais sujas do que as de qualquer outra pessoa a bordo deste dirigível. Você realmente acha que pode lavar seus pecados?",
  ui_story_5071_50710201_81_dialog_content = "Essas \"reformas\" só serão a sua ruína!",
  ui_story_5071_50710201_82_dialog_content = "Haha, é mesmo?",
  ui_story_5071_50710201_83_dialog_content = "Bem, estou meio ansioso para descobrir...",
  ui_story_5071_50710201_84_dialog_content = "Como uma reforma para colocar Umbraton no caminho certo poderia ser prejudicial para mim.",
  ui_story_5071_50710201_85_dialog_content = "Mastigar, mastigar, glub...",
  ui_story_5071_50710201_86_dialog_content = "Ei, vá devagar ou vai acabar se engasgando!",
  ui_story_5071_50710201_87_dialog_content = "Duas galinhas assadas, quatro pizzas e cinco fatias de bolo... Quando foi a sua última refeição?",
  ui_story_5071_50710201_88_dialog_content = "Mastigar, mastigar... F-Faz três horas desde a minha última refeição... Eu estava morrendo de fome agora mesmo...",
  ui_story_5071_50710201_89_dialog_content = "Você estava morrendo de fome depois de apenas três horas?",
  ui_story_5071_50710201_90_dialog_content = "Eu... Eu fico nervoso quando estou perto de estranhos... tão nervoso que gasto toda a minha energia, então...",
  ui_story_5071_50710201_91_dialog_content = "Hum... Com certeza vou te pagar de volta pela refeição!",
  ui_story_5071_50710201_92_dialog_content = "M-Mas você poderia por favor... me ajudar a encontrar a Senhora Sheol?",
  ui_story_5071_50710201_93_dialog_content = "Senhora... Sheol?",
  ui_story_5071_50710201_94_dialog_content = "M-Meu nome é Vergil. Sou um dos funcionários da Senhora Sheol...",
  ui_story_5071_50710201_95_dialog_content = "Eu... Eu não percebi que a Senhora Sheol contratou crianças para trabalhar para ela.",
  ui_story_5071_50710201_96_dialog_content = "P-P-P-Por favor, não entenda mal! Fui eu quem pediu para ela me contratar!",
  ui_story_5071_50710201_97_dialog_content = "Não sei exatamente o que está acontecendo, mas posso sentir a presença da Senhora Sheol por perto—",
  ui_story_5071_50710201_98_dialog_content = "Para!",
  ui_story_5071_50710201_99_dialog_content = "Alvo avistado!",
  ui_story_5071_50710201_100_dialog_content = "Os cães de guarda estão aqui!",
  ui_story_5071_50710201_101_dialog_content = "Atacar!",
  ui_story_5071_50710201_102_dialog_content = "Não é... onde o Senhor Sombrio está se encontrando com as pessoas?",
  ui_story_5071_50710302_1_dialog_content = "Você está bem, madame?",
  ui_story_5071_50710302_2_dialog_content = "Eu... Eu estou bem. Obrigado pela sua ajuda.",
  ui_story_5071_50710302_3_dialog_content = "Patty, Patsy, podem me dizer o que está acontecendo?",
  ui_story_5071_50710302_4_dialog_content = "Nós cães somos os melhores guardas!",
  ui_story_5071_50710302_5_dialog_content = "Ninguém passa por nós a menos que tenha uma reserva!",
  ui_story_5071_50710302_6_dialog_content = "Vocês certamente são cachorrinhos leais, mas vamos evitar causar tanto alvoroço da próxima vez.",
  ui_story_5071_50710302_7_dialog_content = "Você pode cair causando um alvoroço desse jeito.",
  ui_story_5071_50710302_8_dialog_content = "Os cães nunca mostram medo!",
  ui_story_5071_50710302_9_dialog_content = "Mas não seria uma boa ideia perturbar a reunião do Senhor das Sombras lá dentro.",
  ui_story_5071_50710302_10_dialog_content = "Não perturbe o Senhor das Sombras... Até nós sabemos disso!",
  ui_story_5071_50710302_11_dialog_content = "Então, senhora, com qual líder de guilda você está? Por favor, me perdoe, mas não me lembro de ter enviado um convite para alguém como você.",
  ui_story_5071_50710302_12_dialog_content = "A semelhança é impressionante... Quando olho mais de perto, vocês são quase exatamente iguais...",
  ui_story_5071_50710302_13_dialog_content = "...?",
  ui_story_5071_50710302_14_dialog_content = "L... Senhora Sheol!",
  ui_story_5071_50710302_15_dialog_content = "Vergil? O que você está fazendo aqui? Não te pedi para me esperar no leilão aéreo?",
  ui_story_5071_50710302_16_dialog_content = "Eu-Eu estava morrendo de fome agora, então saí para procurar comida... Mas havia tantas pessoas lá fora que acabei me perdendo.",
  ui_story_5071_50710302_17_dialog_content = "Mas essa pessoa gentil me salvou, e até pagou por uma refeição grande e saborosa para eu comer!",
  ui_story_5071_50710302_18_dialog_content = "Haha... Não foi nada.",
  ui_story_5071_50710302_19_dialog_content = "Você já fez amizade com PlayerName? Eu pensei que o pequeno Vergil não falasse com estranhos.",
  ui_story_5071_50710302_20_dialog_content = "É-É porque... PlayerName exala o cheiro de antiguidades por algum motivo, e isso realmente me tranquiliza...",
  ui_story_5071_50710302_21_dialog_content = "Bem, isso é verdade. Você poderia chamar PlayerName de um antiquário recém-criado.",
  ui_story_5071_50710302_22_dialog_content = "PlayerName... Espere, não me diga que você é o lendário Celestita?!",
  ui_story_5071_50710302_23_dialog_content = "Você ainda não respondeu à minha pergunta, madame. Quem é você e o que está fazendo aqui?",
  ui_story_5071_50710302_24_dialog_content = "Um lembrete amigável, a segurança deste navio não é mais gentil do que os filhotes do Shadowlord.",
  ui_story_5071_50710302_25_dialog_content = "Eu... Eu sou Yvonne, uma escritora. A Editora Cross Street me convidou aqui como uma convidada especial.",
  ui_story_5071_50710302_26_dialog_content = "Por favor, me perdoe por causar uma cena agora há pouco. Eu não percebi que precisava de uma reserva para ver o Shadowlord a bordo da aeronave hoje.",
  ui_story_5071_50710302_27_dialog_content = "Yvonne... Espere, você quer dizer A Srta. Yvonne, a escritora mundialmente famosa?!",
  ui_story_5071_50710302_28_dialog_content = "... Estou surpreso que alguém tão jovem quanto você esteja familiarizado com meus trabalhos, considerando que não escrevo nada novo há anos.",
  ui_story_5071_50710302_29_dialog_content = "A escrita da Sra. Yvonne é um testemunho do passado de Umbraton. Toda pessoa letrada na cidade leu seu trabalho.",
  ui_story_5071_50710302_30_dialog_content = "Mas você raramente se mostra em público, então por que hoje...",
  ui_story_5071_50710302_31_dialog_content = "Eu era muito mais jovem naquela época e estava sempre preocupado ou ocupado com uma coisa ou outra. Agora que estou mais velho, fiquei um pouco mais corajoso do que antes.",
  ui_story_5071_50710302_32_dialog_content = "Se não fosse por isso, eu nunca teria embarcado sozinho neste dirigível para o meu manuscrito inacabado.",
  ui_story_5071_50710302_33_dialog_content = "Manuscrito?",
  ui_story_5071_50710302_34_dialog_content = "Depois que meu último livro recebeu críticas tão terríveis, eu tinha certeza de que nunca mais escreveria novamente.",
  ui_story_5071_50710302_35_dialog_content = "Mas não demorou muito, conheci e fiz amizade com um certo <color=#FFB400>artista</color> que compartilhou comigo uma série de histórias fascinantes.",
  ui_story_5071_50710302_36_dialog_content = "Essas histórias, que foram baseadas em eventos reais, eram muito mais emocionantes do que até mesmo a obra de ficção mais cuidadosamente redigida. Mal conseguia dormir depois de ouvi-las!",
  ui_story_5071_50710302_37_dialog_content = "Achei que essas histórias mereciam mais do que apenas acumular poeira no passado esquecido de Umbraton. A pedido do meu amigo, peguei minha caneta mais uma vez...",
  ui_story_5071_50710302_38_dialog_content = "A história em que estou trabalhando é maravilhosa como está, mas temo que certos detalhes ainda estejam faltando. Por isso, procurei entrevistar o Senhor Sombrio hoje.",
  ui_story_5071_50710302_39_dialog_content = "... Mesmo apesar do perigo, e minha incerteza quanto a se ele compartilhará seu conhecimento com um escritor fracassado como eu.",
  ui_story_5071_50710302_40_dialog_content = "Perigo...? O que há de tão perigoso em escrever histórias?",
  ui_story_5071_50710302_41_dialog_content = "Se este livro fosse publicado, todos saberiam o motivo por trás disso.",
  ui_story_5071_50710302_42_dialog_content = "Vejo que você está mantendo seus leitores em suspense, como um bom escritor faria.",
  ui_story_5071_50710302_43_dialog_content = "Senhora Sheol, talvez eu esteja ultrapassando meus limites ao perguntar, mas você poderia me apresentar ao Senhor das Sombras? Prometo que não vou tomar muito do seu precioso tempo!",
  ui_story_5071_50710302_44_dialog_content = "Bem, se eu me recusasse a ajudar, os círculos literários em Umbraton nos acusariam novamente de sermos empresários incultos e gananciosos.",
  ui_story_5071_50710302_45_dialog_content = "Não que eu nunca tenha me importado com tais críticas... No entanto, sou um grande fã dos seus livros!",
  ui_story_5071_50710302_46_dialog_content = "E não é a primeira vez que o Senhor das Sombras faz uma exceção hoje de qualquer maneira. Por favor, me dê um minuto.",
  ui_story_5071_50710302_47_dialog_content = "Ahem, Sra. Yvonne? Seria possível o Vergil conseguir um autógrafo seu? Ele está muito envergonhado para pedir ele mesmo...",
  ui_story_5071_50710302_48_dialog_content = "Um autógrafo? Não há nada para se envergonhar, garotinho! Estou apenas grato por você apreciar tanto o meu trabalho. Só tenho alguns papéis em branco à mão, isso será um problema?",
  ui_story_5071_50710302_49_dialog_content = "N... De jeito nenhum!!",
  ui_story_5071_50710302_50_dialog_content = "Aí está, só para você. Não é muito, mas se tivermos a chance de nos encontrar novamente, adoraria te presentear com uma cópia de...",
  ui_story_5071_50710302_51_dialog_content = "Isso me lembra! Qual dos meus livros você gosta mais?",
  ui_story_5071_50710302_52_dialog_content = "E-e-e-e-eu... Eu realmente gostei da \"Sra. Red Mercury\"!",
  ui_story_5071_50710302_53_dialog_content = "Esse título...",
  ui_story_5071_50710302_54_option_content = "Soa familiar...",
  ui_story_5071_50710302_55_dialog_content = "Acho que tenho uma cópia dessa história no Colossus!",
  ui_story_5071_50710302_56_option_content = "Com certeza, eu nunca ouvi falar disso...",
  ui_story_5071_50710302_57_dialog_content = "A história... É sobre uma bela, porém fria e misteriosa líder de guilda chamada Sra. Red Mercury.",
  ui_story_5071_50710302_58_dialog_content = "Em nome do amor, ela abandona seu status nobre sem hesitação e viaja para Umbraton.",
  ui_story_5071_50710302_59_dialog_content = "Mas após a morte de seu marido, ela assume o controle de várias pequenas guildas e silenciosamente vinga seu amor caído.",
  ui_story_5071_50710302_60_dialog_content = "Você está falando sobre \"Sra. Red Mercury\"? Eu também adoro esse livro.",
  ui_story_5071_50710302_61_dialog_content = "E-É mesmo? Estou tão feliz que você gostou...",
  ui_story_5071_50710302_62_dialog_content = "Enviei as palavras, Sra. Yvonne. Devemos ter uma resposta em breve.",
  ui_story_5071_50710302_63_dialog_content = "Essa é uma notícia maravilhosa... Muito obrigado, Senhora Sheol!",
  ui_story_5071_50710302_64_dialog_content = "O destino pode ser uma coisa tão estranha, e eu não queria dizer nada antes... Mas você se parece muito com a Senhora <color=#FFB400>Melissa</color>.",
  ui_story_5071_50710302_65_dialog_content = "Você conhece Melissa? Então o livro realmente era...",
  ui_story_5071_50710302_66_dialog_content = "Sim. O personagem da Sra. Red Mercury é baseado na Senhora Melissa, uma pessoa real.",
  ui_story_5071_50710302_67_dialog_content = "Senhora Melissa? Quem é essa?",
  ui_story_5071_50710302_68_dialog_content = "Você também não sabe, né? Se eu tivesse que adivinhar... Essa Senhora Melissa é alguém realmente importante para a Senhora Sheol.",
  ui_story_5071_50710302_69_dialog_content = "...",
  ui_story_5071_50710302_70_dialog_content = "Sra. Yvonne, sou verdadeiramente grato pela sua descrição fiel dela no livro, me dando a chance de sentir seu carisma.",
  ui_story_5071_50710302_71_dialog_content = "Fui informado que o filho de Melissa foi sequestrado e envenenado por seus inimigos... Mas agora vejo que ela herdou a tenacidade de sua mãe.",
  ui_story_5071_50710302_72_dialog_content = "Não costumo me arrepender de algo, mas agora estou tendo dúvidas sobre nunca ter investido no negócio de publicação. Talvez eu pudesse ter te conhecido mais cedo então.",
  ui_story_5071_50710302_73_dialog_content = "Tenho certeza de que teremos muitas oportunidades de nos encontrar no futuro, contanto que você não se importe com minha curiosidade sobre o passado.",
  ui_story_5071_50710302_74_dialog_content = "Eu amo histórias, especialmente quando são sobre ela...",
  ui_story_5071_50710302_75_dialog_content = "Além disso, estou muito interessado em publicar o livro que você está escrevendo agora.",
  ui_story_5071_50710302_76_dialog_content = "Isso seria...",
  ui_story_5071_50710302_77_dialog_content = "Não consigo nem começar a imaginar o olhar de alegria radiante no rosto da Senhora Melissa se ela pudesse ver o quão bem-sucedida sua filha se tornou.",
  ui_story_5071_50710302_78_dialog_content = "Sua generosidade com seus clientes é admirável, Senhora Sheol. Eu só gostaria que você soubesse o quanto isso cria problemas para seus associados.",
  ui_story_5071_50710302_79_dialog_content = "Já temos uma resposta?",
  ui_story_5071_50710302_80_dialog_content = "Então esta é a ilustre Srta. Yvonne?",
  ui_story_5071_50710302_81_dialog_content = "O Senhor das Sombras concordou em receber uma audiência. Por aqui, por favor.",
  ui_story_5071_50710302_82_dialog_content = "(!!!)",
  ui_story_5071_50710302_83_dialog_content = "Estou eternamente grato pela sua ajuda, Senhora Sheol!",
  ui_story_5071_50710302_84_dialog_content = "Você mesmo disse que é destino. Estou ansioso para conversar sobre seu trabalho passado com você após sua reunião com o Senhor das Sombras.",
  ui_story_5071_50710302_85_dialog_content = "Seria uma honra para mim.",
  ui_story_5071_50710302_86_dialog_content = "...",
  ui_story_5071_50710302_87_dialog_content = "Por que você está apenas parado aí, querido PlayerName?",
  ui_story_5071_50710302_88_dialog_content = "Ou...",
  ui_story_5071_50710302_89_dialog_content = "Você passou a ter um interesse súbito no meu passado?",
  ui_story_5071_50710401_1_dialog_content = "<color=#e8d9bb>Cerca de dez anos atrás</color>",
  ui_story_5071_50710401_2_dialog_content = "Olhe! São aquelas pessoas da coalizão que encerraram a Crise Darkover?",
  ui_story_5071_50710401_3_dialog_content = "Eles estão se movendo em direção a Lumópolis... Poderiam ser cavaleiros de Lumópolis?!",
  ui_story_5071_50710401_4_dialog_content = "Todos os Cavaleiros de Lumopolis usam uniformes brilhantes, enquanto essas pessoas parecem escuras e cinzentas. É muito provável que eles sejam de Umbraton.",
  ui_story_5071_50710401_5_dialog_content = "Os Eclipsitas não arrasaram Umbraton há muito tempo? Ainda há pessoas vivendo lá?",
  ui_story_5071_50710401_6_dialog_content = "Ouvi dizer que muitos deles sobreviveram graças à ajuda que receberam de Lumopolis.",
  ui_story_5071_50710401_7_dialog_content = "É tão bom ter uma força tão poderosa cuidando deles. Não importa o quão ruins as coisas fiquem, seu mestre os ajudará assim que começarem a abanar o rabo.",
  ui_story_5071_50710401_8_dialog_content = "Shhh! Fique quieto! Essas pessoas podem matar um Eclipsita com um tapa, então é melhor você ter cuidado.",
  ui_story_5071_50710401_9_dialog_content = "Espere! Não é aquele Sheol? Ei, o que você está fazendo?!",
  ui_story_5071_50710401_10_dialog_content = "Em vez de ser sarcástico, por que você não vai simplesmente falar com eles? Afinal, eles são heróis que derrotaram os Eclipsitas.",
  ui_story_5071_50710401_11_dialog_content = "Sheol... Embora você tenha nos ajudado a afastar os Eclipsitas várias vezes, essas pessoas podem ser mais perigosas do que os Eclipsitas. Tenha cuidado e tente não se matar!",
  ui_story_5071_50710401_12_dialog_content = "Relaxe. Eu não acho que alguém tenha problema com dinheiro e em tirar vantagem, certo?",
  ui_story_5071_50710401_13_dialog_content = "Pare aí mesmo! Quem é você?",
  ui_story_5071_50710401_14_dialog_content = "Não fique tão nervoso. Veja, eu não sou um Eclipsite.",
  ui_story_5071_50710401_15_dialog_content = "Só quero lembrar a todos que está quente e seco aqui, então se estiverem com sede, tem água gelada gratuita na minha loja!",
  ui_story_5071_50710401_16_dialog_content = "Infelizmente, não existe almoço grátis neste mundo.",
  ui_story_5071_50710401_17_dialog_content = "Não tem almoço grátis, mas a água é de graça. Claro, se o que você quer é almoço, eu vendo isso também!",
  ui_story_5071_50710401_18_dialog_content = "Caixas combinadas de escorpião do deserto assado autêntico, algo que você não conseguirá em Umbraton.",
  ui_story_5071_50710401_19_dialog_content = "Não se preocupe. Devemos ir.",
  ui_story_5071_50710401_20_dialog_content = "Você não deveria fazer uma pausa depois de vir todo esse caminho? Você pode não estar cansado, mas e os soldados?",
  ui_story_5071_50710401_21_dialog_content = "Heheh, dizem que as pessoas daqui são conhecidas por seus temperamentos explosivos, mas você parece ser uma exceção.",
  ui_story_5071_50710401_22_dialog_content = "Todos que querem água e uma boa refeição, sigam-me!",
  ui_story_5071_50710401_23_dialog_content = "<color=#e8d9bb>Sheol tira uma luva e começa a acenar, fazendo o seu melhor para chamar a atenção de todos ao seu redor.</color>",
  ui_story_5071_50710401_24_dialog_content = "<color=#e8d9bb>Sob a luz do sol brilhante, uma cicatriz fina no antebraço de Sheol emite um brilho avermelhado, parecendo exatamente como a língua cintilante de um lanche.</color>",
  ui_story_5071_50710401_25_dialog_content = "<color=#e8d9bb>Istvan os olhos procuraram a origem do som que ouviu e começaram a observar cuidadosamente a aparência desta garota.</color>",
  ui_story_5071_50710401_26_dialog_content = "Espere! É-É você, Melissa? Não... Você é...",
  ui_story_5071_50710401_27_dialog_content = "Sheol?!",
  ui_story_5071_50710401_28_dialog_content = "Não me lembro de ter te dito meu nome.",
  ui_story_5071_50710401_29_dialog_content = "Mesmo sendo meio conhecido por aqui. Então, o que está acontecendo...",
  ui_story_5071_50710401_30_dialog_content = "Eu finalmente encontrei você!",
  ui_story_5071_50710401_31_dialog_content = "Haha, achei que nunca teria a chance de cumprir essa promessa novamente...",
  ui_story_5071_50710401_32_dialog_content = "Vamos! Vamos voltar para Umbraton, seu verdadeiro lar!",
  ui_story_5071_50710401_33_dialog_content = "(Parece que os aldeões estavam certos sobre como as pessoas de Umbraton são caprichosas e irracionais.)",
  ui_story_5071_50710401_34_dialog_content = "Bem, eu realmente quero visitar Umbraton, mas ainda tenho uma loja para cuidar...",
  ui_story_5071_50710401_35_dialog_content = "E olha a hora... Eu preciso voltar lá agora!",
  ui_story_5071_50710401_36_dialog_content = "Por favor, não entenda mal—",
  ui_story_5071_50710401_37_dialog_content = "Nem um centímetro mais perto!",
  ui_story_5071_50710402_1_dialog_content = "Hahah, como esperado da filha da Melissa! Mesmo sem treinamento adequado, suas habilidades de combate não devem ser ignoradas.",
  ui_story_5071_50710402_2_dialog_content = "O que você quer? Sou apenas um pequeno comerciante, que valor eu tenho para você?",
  ui_story_5071_50710402_3_dialog_content = "Perdoe-me por não explicar as coisas mais claramente. A verdade é que estou ajudando uma velha amiga a encontrar sua filha perdida há muito tempo.",
  ui_story_5071_50710402_4_dialog_content = "Cresci no deserto. Que laços eu tenho com Umbraton?",
  ui_story_5071_50710402_5_dialog_content = "Se eu não estou enganado, você tem uma pequena marca em forma de cobra no seu braço. Estou certo?",
  ui_story_5071_50710402_6_dialog_content = "Você percebeu isso apenas um segundo atrás.",
  ui_story_5071_50710402_7_dialog_content = "Sim... Mas o seu nome estava inscrito nas roupas que você estava usando quando desapareceu: \"Sheol\".",
  ui_story_5071_50710402_8_dialog_content = "A julgar pela sua reação, parece que os outros também te chamam assim.",
  ui_story_5071_50710402_9_dialog_content = "Diga-me, de quem eu sou filha?",
  ui_story_5071_50710402_10_dialog_content = "Um velho amigo meu chamado Senhora Melissa.",
  ui_story_5071_50710402_11_dialog_content = "Se ela fosse realmente minha mãe, por que ela mesma não veio me buscar?",
  ui_story_5071_50710402_12_dialog_content = "Porque ela... Morreu de doença há muito tempo.",
  ui_story_5071_50710402_13_dialog_content = "Quão conveniente.",
  ui_story_5071_50710402_14_dialog_content = "...",
  ui_story_5071_50710402_15_dialog_content = "Estive carregando isso todo esse tempo, esperando para te dar um dia.",
  ui_story_5071_50710402_16_dialog_content = "É... ouro puro?",
  ui_story_5071_50710402_17_dialog_content = "Foi deixado para você por sua falecida mãe. Se você pode usar Luminatics, então você deve saber como manejá-lo.",
  ui_story_5071_50710402_18_dialog_content = "E você vai simplesmente me dar isso?",
  ui_story_5071_50710402_19_dialog_content = "Quando você tiver tempo suficiente para considerar as coisas, venha me encontrar em Umbraton.",
  ui_story_5071_50710402_20_dialog_content = "Você pode contar comigo para fazer isso, mas não necessariamente para te ver.",
  ui_story_5071_50710402_21_dialog_content = "Tenho certeza que você vai.",
  ui_story_5071_50710402_22_dialog_content = "Que sujeito estranho.",
  ui_story_5071_50710402_23_dialog_content = "Mas existe realmente algo como um almoço grátis?",
  ui_story_5071_50710402_24_dialog_content = "<color=#e8d9bb>Toc, toc, toc..</color>",
  ui_story_5071_50710402_25_dialog_content = "Digitar.",
  ui_story_5071_50710402_26_dialog_content = "<color=#e8d9bb>*Passos*</color>",
  ui_story_5071_50710402_27_dialog_content = "Sheol?",
  ui_story_5071_50710402_28_dialog_content = "Hahaha, não disse que você viria me ver algum dia? Embora pelo que ouvi, você está em Umbraton há bastante tempo. Você já se adaptou à vida nesta cidade?",
  ui_story_5071_50710402_29_dialog_content = "<color=#e8d9bb>Tapa...</color>",
  ui_story_5071_50710402_30_dialog_content = "Por favor, dê uma olhada.",
  ui_story_5071_50710402_31_dialog_content = "Hum?",
  ui_story_5071_50710402_32_dialog_content = "Vejo que a grande Gangue Istvan está se aventurando em commodities agora.",
  ui_story_5071_50710402_33_dialog_content = "O problema é que você não tem ideia da qualidade do que está comprando.",
  ui_story_5071_50710402_34_dialog_content = "A Guilda Firefox que lhe fornece teve a audácia de fraudar os nobres em Lumopolis... Quanto aos detalhes, eles estão resumidos neste arquivo.",
  ui_story_5071_50710402_35_dialog_content = "Mesmo eu consegui rastreá-lo facilmente, então imagino que os Guardas Lumo já sabiam disso.",
  ui_story_5071_50710402_36_dialog_content = "É apenas uma questão de dias até que esse seu fornecedor \"confiável\" seja jogado para apodrecer na prisão.",
  ui_story_5071_50710402_37_dialog_content = "Quando o Firefox não existir mais, você não apenas perderá seu fornecedor, mas também terá que lidar com clientes irritados.",
  ui_story_5071_50710402_38_dialog_content = "É por isso que você veio aqui hoje?",
  ui_story_5071_50710402_39_dialog_content = "Vamos não ficar tensos, Senhor Sombrio.",
  ui_story_5071_50710402_40_dialog_content = "Não estou aqui para te derrubar quando você está mal, mas para oferecer uma situação em que todos saem ganhando.",
  ui_story_5071_50710402_41_dialog_content = "Se não se importa que eu diga, vocês gangsters precisam de ajuda profissional nos negócios.",
  ui_story_5071_50710402_42_dialog_content = "Claro, tenho uma oferta especial exclusiva com o seu nome nela.",
  ui_story_5071_50710402_43_dialog_content = "(Entendi. Ela não tinha intenção de vir até mim para pedir ajuda, e até começou uma pequena guilda com suas próprias mãos aqui em Umbraton...)",
  ui_story_5071_50710402_44_dialog_content = "(Ela não quer que eu subestime suas habilidades, então ela veio até mim com uma proposta de negócio que nos colocaria em pé de igualdade. É isso?)",
  ui_story_5071_50710402_45_dialog_content = "Hahahaha! Muito bem então, deixarei esta remessa em suas mãos capazes, Senhora Sheol.",
  ui_story_5071_50710402_46_dialog_content = "Mas agora eu te devo um favor. Diga-me o que você deseja, e eu prometo torná-lo seu.",
  ui_story_5071_50710402_47_dialog_content = "Eu sempre acredito que o único que pode realizar meu próprio desejo sou eu mesmo.",
  ui_story_5071_50710402_48_dialog_content = "Entendo, então continuarei segurando este desejo por você. Se você mudar de ideia, tudo o que precisa fazer é dizer.",
  ui_story_5071_50710402_49_dialog_content = "Agradeço a oferta, mas espero nunca ter que usá-la.",
  ui_story_5071_50710402_50_dialog_content = "Até eu estou surpreso com a sua semelhança com sua mãe, e não apenas em termos de aparência...",
  ui_story_5071_50710402_51_dialog_content = "Como... ela era?",
  ui_story_5071_50710402_52_dialog_content = "Assim como você, ela era uma líder de guilda decisiva e prudente. Tenho nada além do mais profundo respeito por ela.",
  ui_story_5071_50710402_53_dialog_content = "Infelizmente, nenhum elogio poderia se transformar em uma imagem clara. Ainda não consigo compreendê-la...",
  ui_story_5071_50710402_54_dialog_content = "Perdoe a intromissão, Senhor das Sombras!",
  ui_story_5071_50710402_55_dialog_content = "Como você previu, a Guilda Firefox não estava disposta a pagar pelas nossas mercadorias desde o início! A culpa é toda nossa por não investigá-los mais a fundo!",
  ui_story_5071_50710402_56_dialog_content = "O presidente deles foi recentemente preso pelas autoridades de Lumópolis... O que significa que provavelmente perderemos nosso investimento neste negócio.",
  ui_story_5071_50710402_57_dialog_content = "Nossas pessoas começaram a entrar em contato com outras guildas com pedidos urgentes. Devemos preparar contratos para eles?",
  ui_story_5071_50710402_58_dialog_content = "Não. Já encontrei um parceiro de negócios perfeitamente adequado para o trabalho. Diga-lhes para esperar por mais instruções.",
  ui_story_5071_50710402_59_dialog_content = "Sim, meu senhor!",
  ui_story_5071_50710402_60_dialog_content = "Espere, o plano idiota foi culpa de vocês? Pensando bem, isso significa que vocês sabiam o que o Firefox estava fazendo o tempo todo...",
  ui_story_5071_50710402_61_dialog_content = "Não há mais necessidade de nos apegarmos ao passado. Devemos celebrar nossa nova colaboração de negócios, você não concorda?",
  ui_story_5071_50710402_62_dialog_content = "Mas se eles encontraram outra guilda para você, por que você me escolheu? É por causa da minha mãe...",
  ui_story_5071_50710402_63_dialog_content = "Porque você, Senhora Sheol, é muito mais prudente e cooperativa do que outros líderes de guilda que afirmam ser capazes de liderar a Guilda Umbraton.",
  ui_story_5071_50710402_64_dialog_content = "A perspectiva de trabalhar com alguém como você me traz muita alegria.",
  ui_story_5071_50710402_65_dialog_content = "Então, por uma parceria feliz.",
  ui_story_5071_50710402_66_dialog_content = "Agora então, como devo me referir à sua guilda?",
  ui_story_5071_50710402_67_dialog_content = "A Guilda Cloudrover.",
  ui_story_5071_50710402_68_dialog_content = "... Parece que você também anseia por aquela ilha flutuante no céu.",
  ui_story_5071_50710402_69_dialog_content = "Lumópolis? Realmente é uma ilha atraente, mas eu prefiro uma versão mais livre.",
  ui_story_5071_50710402_70_dialog_content = "Vagueie por qualquer lugar, negocie livremente... O quê, você não acha que isso é realista?",
  ui_story_5071_50710402_71_dialog_content = "Nem um pouco. Tudo o que eu desejo dizer—",
  ui_story_5071_50710402_72_dialog_content = "É que estou ansioso para trabalhar com você.",
  ui_story_5071_50710402_73_dialog_content = "(Eu acidentalmente dei uma espiada nas memórias da Senhora Sheol. Nunca a vi tão emocionada antes...)",
  ui_story_5071_50710402_74_dialog_content = "Por que você está apenas parado aí, querido PlayerName?",
  ui_story_5071_50710402_75_dialog_content = "Ou...",
  ui_story_5071_50710402_76_dialog_content = "Você passou a ter um interesse súbito no meu passado?",
  ui_story_5071_50710402_77_dialog_content = "Eu...",
  ui_story_5071_50710402_78_dialog_content = "Eu posso ver por que você está tão surpreso. Esta também é a minha primeira vez vendo a Senhora Sheol tão feliz!",
  ui_story_5071_50710402_79_dialog_content = "Já que você gosta tanto da Srta. Yvonne, Vergil...",
  ui_story_5071_50710402_80_dialog_content = "Por que eu não invisto em uma editora e a contrato para um exclusivo?",
  ui_story_5071_50710402_81_dialog_content = "Hã? I-Isso é realmente ok?",
  ui_story_5071_50710402_82_dialog_content = "Com a condição de que você primeiro escreva um livro sobre antiguidades para mim.",
  ui_story_5071_50710402_83_dialog_content = "Eu-Eu... Farei o meu melhor...",
  ui_story_5071_50710402_84_dialog_content = "Hã? Vergílio, você na verdade—",
  ui_story_5071_50710402_85_dialog_content = "Vergil pode ser uma criança, mas ele é um verdadeiro especialista em antiguidades que pode avaliar qualquer coisa!",
  ui_story_5071_50710402_86_dialog_content = "E-Eu... não é realmente tão impressionante...",
  ui_story_5071_50710402_87_dialog_content = "Momento perfeito! Eu peguei uma pilha de papéis de manuscrito mais cedo. Você poderia nos dizer a quem pertence, Vergil?",
  ui_story_5071_50710402_88_dialog_content = "Este é o tipo de papel de escrita que todos usam hoje em dia—",
  ui_story_5071_50710402_89_dialog_content = "Huh? Espere um minuto! Isso é...",
  ui_story_5071_50710501_1_dialog_content = "Tem certeza de que este é o manuscrito da Sra. Yvonne?",
  ui_story_5071_50710501_2_dialog_content = "É! Pelo que eu sei, esta é uma história totalmente nova que nunca foi publicada antes!",
  ui_story_5071_50710501_3_dialog_content = "Mas essas páginas parecem tão antigas. Por que ainda não foram publicadas?",
  ui_story_5071_50710501_4_dialog_content = "Há muitas razões pelas quais os autores não conseguem publicar seu trabalho a tempo. Além disso, dê uma olhada nas últimas páginas deste manuscrito: elas ainda são bastante novas!",
  ui_story_5071_50710501_5_dialog_content = "Isso pode ser um manuscrito perdido para a nova história da Sra. Yvonne! Ahhh, mal posso esperar para lê-lo...",
  ui_story_5071_50710501_6_dialog_content = "Você não acha que deveríamos devolvê-lo ao seu legítimo dono primeiro, Vergil?",
  ui_story_5071_50710501_7_dialog_content = "Ahhh, apenas a primeira linha deste manuscrito já é suficiente para me trazer lágrimas aos olhos! A última vez que li uma das obras da Sra. Yvonne, eu não era mais alta que um banquinho da antiga Longzhou!",
  ui_story_5071_50710501_8_dialog_content = "Isso é bom mesmo? Deixe-me dar uma olhada...",
  ui_story_5071_50710501_9_dialog_content = "Fora dos portões de um posto de Lumópolis, há uma estrada pavimentada com incontáveis tijolos verdes. Em um campo aberto, pode-se ver um monte de pedras brancas.",
  ui_story_5071_50710501_10_dialog_content = "As crianças locais que frequentemente vêm aqui para brincar de esconde-esconde são frequentemente confrontadas por um transeunte intrometido.",
  ui_story_5071_50710501_11_dialog_content = "\"O que vocês pequenos monstros pensam que estão fazendo? Não sabem o que este lugar costumava ser?!\"",
  ui_story_5071_50710501_12_dialog_content = "Com a barriga saliente, uma criança responde sem medo, \"Não era chamado de 'O Poço'?\"",
  ui_story_5071_50710501_13_dialog_content = "\"Sim, e foi muito diferente dos clubes de luta na cidade. Você tem alguma ideia de quantas pessoas já morreram aqui?\"",
  ui_story_5071_50710501_14_dialog_content = "Ao ver as crianças de repente ficarem em silêncio, o intrometido ficou ainda mais animado. \"Cem pessoas entrariam, mas apenas uma sobreviveria!\"",
  ui_story_5071_50710501_15_dialog_content = "Esses intrometidos estão certos. O Poço sempre foi um lugar onde os nobres se divertem com a morte dos outros.",
  ui_story_5071_50710501_16_dialog_content = "Eles amarram todos os tipos de criminosos com correntes de ferro tão grossas quanto uma tigela, como animais, e os jogam no Poço para lutar.",
  ui_story_5071_50710501_17_dialog_content = "Claro, existem aqueles que entram no Poço voluntariamente e sem medo, apenas para ganhar algo para comer ou para serem notados por um nobre.",
  ui_story_5071_50710501_18_dialog_content = "No entanto, também existem aqueles que foram enganados para entrar no Poço...",
  ui_story_5071_50710501_19_dialog_content = "Se eu pudesse deixar o Juiz de Lumopolis saber que o Xerife de Umbraton está em conluio com as gangues...",
  ui_story_5071_50710501_20_dialog_content = "Ele certamente lidaria com a escória que só se importava em ganhar dinheiro à custa da vida dos outros!",
  ui_story_5071_50710501_21_dialog_content = "Mas o juiz realmente está aqui?",
  ui_story_5071_50710501_22_dialog_content = "Não, não—",
  ui_story_5071_50710501_23_dialog_content = "Pare!",
  ui_story_5071_50710501_24_dialog_content = "Por favor, abra caminho para eu passar!",
  ui_story_5071_50710501_25_dialog_content = "Mas os guardas estão atrás de você. Você é um criminoso?",
  ui_story_5071_50710501_26_dialog_content = "Não, eu não sou... Você parece que também é de Umbraton, então por favor me ajude!",
  ui_story_5071_50710501_27_dialog_content = "Vim apresentar uma queixa no Lumo Hall da Justiça sobre os negócios sujos que alguns nobres estão fazendo em Umbraton, apenas para eles me perseguirem em troca.",
  ui_story_5071_50710501_28_dialog_content = "Não me importava de ir para a prisão, mas eles queriam me jogar na Fossa! Eles queriam me matar...",
  ui_story_5071_50710501_29_dialog_content = "Não acredito que você me superou! Então o Tribunal de Justiça também está corrompido? Ou talvez toda a Lumopolis...",
  ui_story_5071_50710501_30_dialog_content = "Onde você pensa que está indo?!",
  ui_story_5071_50710501_31_dialog_content = "Eles estão aqui! Acho que acabou para mim.",
  ui_story_5071_50710501_32_dialog_content = "Não fale tão cedo.",
  ui_story_5071_50710501_33_dialog_content = "Ei! Sim, estou falando com você. Saia do caminho!",
  ui_story_5071_50710501_34_dialog_content = "Esse cara não sabe lutar nada, então o que ele fez de tão errado para mandá-lo para a morte?",
  ui_story_5071_50710501_35_dialog_content = "Ele não precisa lutar. Só precisamos garantir que haja pessoas suficientes. Você vai tomar o lugar dele?",
  ui_story_5071_50710501_36_dialog_content = "Que absurdo! Eles não estão planejando me deixar vivo.",
  ui_story_5071_50710501_37_dialog_content = "Esqueça. Isso é o fim. Meu pai nunca gostou de mim mesmo, nem fora de casa...",
  ui_story_5071_50710501_38_dialog_content = "Eu vou ficar no lugar dele.",
  ui_story_5071_50710501_39_dialog_content = "O quê? Você nem me conhece e morreria por mim?",
  ui_story_5071_50710501_40_dialog_content = "Eu sei o que estou fazendo.",
  ui_story_5071_50710501_41_dialog_content = "Você parece ser muito instruído e sabe melhor do que eu como salvar Umbraton. Se eu não conseguir voltar, prometa-me...",
  ui_story_5071_50710501_42_dialog_content = "Mantenha Umbraton vivo.",
  ui_story_5071_50710501_43_dialog_content = "...",
  ui_story_5071_50710501_44_dialog_content = "Parece que mais um guerreiro se voluntariou para lutar por nós hoje!",
  ui_story_5071_50710501_45_dialog_content = "Hoje é o seu dia de sorte, lutadores! Se algum de vocês conseguir vencê-lo e viver para contar a história, um desses nobres senhores concordou em dobrar a recompensa!",
  ui_story_5071_50710501_46_dialog_content = "Ahahahaha—",
  ui_story_5071_50710501_47_dialog_content = "Pegue aquele monstro chifrudo!",
  ui_story_5071_50710501_48_dialog_content = "...",
  ui_story_5071_50710501_49_dialog_content = "Mate ele—!",
  ui_story_5071_50710501_50_dialog_content = "As pessoas que foram jogadas no Poço já venderam suas almas para os demônios.",
  ui_story_5071_50710501_51_dialog_content = "Peguem eles! Apresse-se, seus inúteis idiotas!",
  ui_story_5071_50710501_52_dialog_content = "Está claro que eles estão apenas sendo usados por aqueles nobres sanguinários...",
  ui_story_5071_50710501_53_dialog_content = "Mate-o! Nós dividiremos o prêmio em dinheiro se você fizer isso!",
  ui_story_5071_50710501_54_dialog_content = "Mas apenas um deles pode viver, certo?",
  ui_story_5071_50710501_55_dialog_content = "Eu não me importo, contanto que não seja aquele demônio chifrudo!",
  ui_story_5071_50710501_56_dialog_content = "Então não vamos perder mais tempo. Venha até mim!",
  ui_story_5071_50710502_1_dialog_content = "Cada golpe selvagem era recebido com rugidos e gritos da multidão. Um após o outro, os guerreiros na The Pit começaram a cair.",
  ui_story_5071_50710502_2_dialog_content = "Alguns espectadores cobriram seus rostos ou recuaram para a última fila das arquibancadas, temendo que o próximo punho azul em chamas pudesse alcançá-los.",
  ui_story_5071_50710502_3_dialog_content = "O jovem que era robusto como uma besta e feroz como um demônio finalmente parou depois de derrubar seus últimos oponentes. Depois disso, os espectadores finalmente soltaram um suspiro de alívio.",
  ui_story_5071_50710502_4_dialog_content = "Ele venceu! Ele realmente venceu, mesmo com todos no Pit atacando-o!",
  ui_story_5071_50710502_5_dialog_content = "Os ferimentos dele são bastante graves. Aquelas pessoas esconderam armas e fizeram muitos cortes em seu corpo...",
  ui_story_5071_50710502_6_dialog_content = "Eu contei - ele deu mais de mil golpes!",
  ui_story_5071_50710502_7_dialog_content = "Mil feridas?!",
  ui_story_5071_50710502_8_dialog_content = "...",
  ui_story_5071_50710502_9_dialog_content = "Podemos ir agora?",
  ui_story_5071_50710502_10_dialog_content = "A pessoa que você protegeu pode sair. Quanto a você...",
  ui_story_5071_50710502_11_dialog_content = "Escute...",
  ui_story_5071_50710502_12_dialog_content = "Você está ouvindo?",
  ui_story_5071_50710502_13_dialog_content = "Ahhh! O-O quê...?!",
  ui_story_5071_50710502_14_dialog_content = "Vocês dois estão tão imersos, que se esqueceram completamente de mim.",
  ui_story_5071_50710502_15_dialog_content = "Por mais que eu adoraria te acompanhar, tenho assuntos urgentes para tratar.",
  ui_story_5071_50710502_16_dialog_content = "Ainda assim, você deve devolvê-lo à Sra. Yvonne o mais rápido possível.",
  ui_story_5071_50710502_17_dialog_content = "Ah, e Vergil, não perca sua tarefa de leilão.",
  ui_story_5071_50710502_18_dialog_content = "Eu não vou!",
  ui_story_5071_50710502_19_dialog_content = "A Sra. Yvonne deve estar se encontrando com o Senhor Sombrio agora. Por que não vamos procurá-la por lá?",
  ui_story_5071_50710502_20_dialog_content = "M-Mas eu estava chegando na parte emocionante...",
  ui_story_5071_50710502_21_dialog_content = "C-Não posso ler um pouco mais?",
  ui_story_5071_50710502_22_dialog_content = "A-Aham, tudo bem... Mas só um pouco mais, tá bom?",
  ui_story_5071_50710502_23_dialog_content = "Tudo bem! Só um pouco mais não vai doer!",
  ui_story_5071_50710601_1_dialog_content = "<color=#e8d9bb>Na suíte de luxo do Dirigível Cloudrover</color>",
  ui_story_5071_50710601_2_dialog_content = "Obrigado por conceder uma audiência comigo, honrado Senhor das Sombras. Eu aqui lhe ofereço o máximo respeito em nome da Guilda Continental.",
  ui_story_5071_50710601_3_dialog_content = "Você é a Sra. Hanstie, a enigmática líder da Guilda Continental? Eu me lembro que esse não era o seu sobrenome.",
  ui_story_5071_50710601_4_dialog_content = "Então somos dois.",
  ui_story_5071_50710601_5_dialog_content = "... Você mudou muito.",
  ui_story_5071_50710601_6_dialog_content = "Você acha? Ah, você está falando da minha perna?",
  ui_story_5071_50710601_7_dialog_content = "Mesmo tendo gasto muito dinheiro para escapar quando o Darkover dominou Umbraton, ainda encontrei Eclipsitas no caminho...",
  ui_story_5071_50710601_8_dialog_content = "Mas isso é bom, pois caso contrário eu não perceberia os benefícios de uma perna cibernética.",
  ui_story_5071_50710601_9_dialog_content = "Haha, você realmente está diferente, mais otimista e resiliente do que antes.",
  ui_story_5071_50710601_10_dialog_content = "Isso vai acontecer, considerando tudo o que eu passei.",
  ui_story_5071_50710601_11_dialog_content = "Sua guilda também é bastante impressionante e não convencional na forma como frequentemente faz investimentos arriscados proibidos pela Guilda de Umbraton.",
  ui_story_5071_50710601_12_dialog_content = "Heheh, vejo que a sombra tem me observado.",
  ui_story_5071_50710601_13_dialog_content = "Mas você certamente não está me tratando como um velho amigo. Aqui estou eu visitando com boas intenções, apenas para você tentar me rebaixar.",
  ui_story_5071_50710601_14_dialog_content = "Somos velhos amigos, é por isso que quero o melhor para você.",
  ui_story_5071_50710601_15_dialog_content = "Eu não entendo muito bem, <color=#FFB400>seu Umbraton</color> não é uma cidade livre e tolerante?",
  ui_story_5071_50710601_16_dialog_content = "Você obviamente pode trazer grandes cassinos para gerar mais lucros para Umbraton e até mesmo pagar facilmente o considerável \"imposto sobre a propriedade\" para Lumopolis, então por que você não faz isso?",
  ui_story_5071_50710601_17_dialog_content = "Você não começou adorando dinheiro. Naquela época, você era apaixonado pelas artes e literatura, sempre com uma caneta ou pincel na mão—",
  ui_story_5071_50710601_18_dialog_content = "Não sou o único que mudou.",
  ui_story_5071_50710601_19_dialog_content = "Não consigo acreditar que aquele sujeito falido que eu conhecia conseguiu pegar o Cajado do Pastor e se transformar em <color=#FFB400>Istvan</color>.",
  ui_story_5071_50710601_20_dialog_content = "...",
  ui_story_5071_50710601_21_dialog_content = "Você está certo. Nada permanece o mesmo para sempre. Umbraton está passando por uma reforma agora.",
  ui_story_5071_50710601_22_dialog_content = "Isso não é nem o seu Umbraton nem o meu.",
  ui_story_5071_50710601_23_dialog_content = "Aqui, você pode negociar livremente, exceto pelo tipo subterrâneo e criminoso - esse também era o sonho de <color=#FFB400>Valon</color>.",
  ui_story_5071_50710601_24_dialog_content = "Mas por que...",
  ui_story_5071_50710601_25_dialog_content = "Que trágico... Por que isso tem que acontecer com o protagonista?",
  ui_story_5071_50710601_26_dialog_content = "Então, mesmo após receber uma audiência com o Senhor da Cidade, ele ainda foi incriminado pelos nobres e jogado na prisão?",
  ui_story_5071_50710601_27_dialog_content = "O Senhor da Cidade de Lumopolis nunca quis ouvir os pensamentos do protagonista sobre Umbraton. Ele só via a cidade como um animal de estimação que poderia lutar... Uma vez que não lhe servia mais, ele perdeu o interesse.",
  ui_story_5071_50710601_28_dialog_content = "A história deste livro é muito mais complicada do que as anteriores... Eu me pergunto o que o protagonista fará quando sair da prisão?",
  ui_story_5071_50710601_29_dialog_content = "Talvez devêssemos... ler um pouco mais?",
  ui_story_5071_50710601_30_dialog_content = "Sim, só um pouco mais!",
  ui_story_5071_50710601_31_dialog_content = "O ar no cemitério parecia ainda mais frio do que na cidade, possivelmente porque ele passou muito tempo ali parado.",
  ui_story_5071_50710601_32_dialog_content = "Quando ele deixou a casa, as únicas palavras que disse aos seus pais foram \"Estou indo embora agora.\" Agora, depois de tantos anos, ele não conseguiu reunir nem a frase mais simples: \"Eu voltei.\"",
  ui_story_5071_50710601_33_dialog_content = "Passos lentamente se aproximaram dele por trás. \"Declare seu propósito\", disse ele friamente ao visitante sem se virar.",
  ui_story_5071_50710601_34_dialog_content = "Logo o visitante respondeu: \"Kade... Você finalmente voltou.\"",
  ui_story_5071_50710601_35_dialog_content = "Kade virou a cabeça em direção à pessoa, um rosto vagamente familiar. \"Eu te conheço?\"",
  ui_story_5071_50710601_36_dialog_content = "Você salvou uma certa pessoa no Poço todos aqueles anos atrás... E essa pessoa era eu.",
  ui_story_5071_50710601_37_dialog_content = "Você sofreu por muitos anos por minha causa. Eu não posso simplesmente virar as costas para você.",
  ui_story_5071_50710601_38_dialog_content = "Se você não tem um lugar para voltar, talvez possa vir para casa comigo? Vou te tratar como se fosse meu próprio irmão!",
  ui_story_5071_50710601_39_dialog_content = "Mas eu nem sei o seu nome...",
  ui_story_5071_50710601_40_dialog_content = "Valon. Apenas me chame de Valon.",
  ui_story_5071_50710601_41_dialog_content = "Em breve, os dois jovens descobriram um interesse em comum...",
  ui_story_5071_50710601_42_dialog_content = "... Tenho praticado desde que voltei do Poço.",
  ui_story_5071_50710601_43_dialog_content = "Praticando como jogar xadrez?",
  ui_story_5071_50710601_44_dialog_content = "Luminatics. Espero ser tão poderoso quanto você um dia, para que eu também possa dominar o campo de batalha.",
  ui_story_5071_50710601_45_dialog_content = "Se for esse o caso, então eu quero ser tão habilidoso quanto você quando se trata de xadrez.",
  ui_story_5071_50710601_46_dialog_content = "Haha, eu nunca soube que você também gostava de xadrez. Quem te ensinou a jogar?",
  ui_story_5071_50710601_47_dialog_content = "Meu pai...",
  ui_story_5071_50710601_48_dialog_content = "Desculpe, eu não deveria ter perguntado... Mas de agora em diante, meu pai pode ser seu pai também!",
  ui_story_5071_50710601_49_dialog_content = "Tenho certeza de que o pai gosta de você o suficiente para adotá-lo! Dessa forma, podemos nos tornar irmãos de verdade!",
  ui_story_5071_50710601_50_dialog_content = "...",
  ui_story_5071_50710601_51_dialog_content = "Então, por favor, não recuse, assim como eu não recusei quando você tomou meu lugar na Arena Mortal.",
  ui_story_5071_50710601_52_dialog_content = "Estou apenas preocupado. Nada sobre Umbraton mudou desde a última vez que estive aqui. Absolutamente nada.",
  ui_story_5071_50710601_53_dialog_content = "... Eu também pensei nisso. Se Umbraton continuar esperando pela ajuda de Lumopolis, nunca vai mudar.",
  ui_story_5071_50710601_54_dialog_content = "Precisamos contar com nossa própria força se quisermos exterminar os insetos sugadores de sangue que estão drenando a vida de nossa cidade.",
  ui_story_5071_50710601_55_dialog_content = "Eu me pergunto quem escolheu o nome \"Umbraton\" para este lugar? Quem eram eles para decidir que deveríamos sempre viver nas sombras? O futuro é nosso para decidir!",
  ui_story_5071_50710601_56_dialog_content = "O futuro... Sim, o futuro desta cidade deve ser livre e unificado - um futuro onde ninguém pode mais nos controlar!",
  ui_story_5071_50710601_57_dialog_content = "Eu desejo a mesma coisa, mas nos libertar da escuridão do nosso passado não é algo que pode ser feito da noite para o dia...",
  ui_story_5071_50710601_58_dialog_content = "Talvez tenhamos que aprender a viver em paz com eles, até mesmo nos tornar parte deles por algum tempo...",
  ui_story_5071_50710601_59_dialog_content = "Não. Precisamos nos livrar de sua influência nefasta, e precisa ser em breve! Sem concessões.",
  ui_story_5071_50710601_60_dialog_content = "Hã?",
  ui_story_5071_50710601_61_dialog_content = "O que foi?",
  ui_story_5071_50710601_62_dialog_content = "Alguém está ouvindo na porta... Devemos fazer algo a respeito?",
  ui_story_5071_50710601_63_dialog_content = "Ah... Essa é apenas a <color=#FFB400>Ava</color>, filha de um dos amigos do meu pai. Não se preocupe, ela também é minha amiga.",
  ui_story_5071_50710601_64_dialog_content = "Não somos apenas amigos, você sabe!",
  ui_story_5071_50710601_65_dialog_content = "Kade sempre se impressionou com a iniciativa de Valon. Um dia, Valon decidiu abordar seu pai, o líder de uma guilda de comerciantes, em busca de apoio...",
  ui_story_5071_50710601_66_dialog_content = "Nunca!",
  ui_story_5071_50710601_67_dialog_content = "Mas por que não? Estamos tentando fazer a coisa certa!",
  ui_story_5071_50710601_68_dialog_content = "Essas gangues sanguinárias e as guildas que não se comportam melhor do que elas... Eles são um câncer para toda Umbraton!",
  ui_story_5071_50710601_69_dialog_content = "Se agirmos rapidamente e de forma decisiva, podemos eliminá-los um por um!",
  ui_story_5071_50710601_70_dialog_content = "Se pudessem ser erradicados tão facilmente, alguém já teria feito isso há muito tempo. Apesar de sua natureza caótica, Umbraton mantém um certo equilíbrio que não deve ser derrubado.",
  ui_story_5071_50710601_71_dialog_content = "Quantas vezes eu te avisei sobre ser tão ingênuo? Você não aprendeu nada com a sua última lição?",
  ui_story_5071_50710601_72_dialog_content = "Você só sobreviveu porque Kade estava lá, mas e da próxima vez?",
  ui_story_5071_50710601_73_dialog_content = "Você e Kade não serão os únicos a sofrer por seus erros. Nossa família inteira estará em risco!",
  ui_story_5071_50710601_74_dialog_content = "Pai!",
  ui_story_5071_50710601_75_dialog_content = "Valon e seu pai sempre estiveram em constante conflito. Felizmente, agora Kade estava lá para apoiá-lo...",
  ui_story_5071_50710601_76_dialog_content = "Pai nem está disposto a ouvir minha estratégia para o futuro de Umbraton.",
  ui_story_5071_50710601_77_dialog_content = "Mas eu estou. Vá em frente, me conte sobre isso.",
  ui_story_5071_50710601_78_dialog_content = "Diga-me, você sabe por que nossas guildas sofrem tanto nas mãos das gangues atualmente? É porque todos estão apenas cuidando de si mesmos.",
  ui_story_5071_50710601_79_dialog_content = "Acho que todas as guildas deveriam se unir e formar um único corpo onde possam desfrutar de benefícios e proteções compartilhados. Podemos chamar isso de—",
  ui_story_5071_50710601_80_dialog_content = "A Guilda de Umbraton?",
  ui_story_5071_50710601_81_dialog_content = "Sim, vamos chamar de Guilda de Umbraton! Só quando os interesses de todos são compartilhados é que podemos nos ajudar a derrotar o inimigo comum!",
  ui_story_5071_50710601_82_dialog_content = "Gangues e guildas amigáveis a gangues, mercenários predatórios... Até mesmo Lumópolis não teria uma chance!",
  ui_story_5071_50710601_83_dialog_content = "Uma vez que removemos essas pragas de Umbraton, ela se tornará um paraíso puro para todos os tipos de negócios.",
  ui_story_5071_50710601_84_dialog_content = "E então... Eu vou liderar minha própria guilda para terras ainda mais distantes!",
  ui_story_5071_50710601_85_dialog_content = "E como você faria isso?",
  ui_story_5071_50710601_86_dialog_content = "Com veículos, eu suponho... Ou espera, ainda melhor! Vou comprar um Colossus de Eraveil e estabelecer minha guilda em cima dele!",
  ui_story_5071_50710601_87_dialog_content = "Juntos, navegaremos pelos céus com o vento em nossos rostos, viajando e negociando livremente pelo continente!",
  ui_story_5071_50710601_88_dialog_content = "Minha guilda não discrimina com base em riqueza ou status. Qualquer um pode entrar e prosperar, desde que esteja disposto a trabalhar duro para isso!",
  ui_story_5071_50710601_89_dialog_content = "...",
  ui_story_5071_50710601_90_dialog_content = "O que foi, Kade? Eu disse algo errado?",
  ui_story_5071_50710601_91_dialog_content = "De maneira alguma, Valon, é um belo sonho. Talvez a única maneira de realmente se libertar das sombras... seja voar para o céu.",
  ui_story_5071_50710601_92_dialog_content = "Farei o que for necessário para tornar esse sonho realidade.",
  ui_story_5071_50710601_93_dialog_content = "Eu vou fazer o mesmo também!",
  ui_story_5071_50710601_94_dialog_content = "Mas eu pensei que você não se importava com negócios?",
  ui_story_5071_50710601_95_dialog_content = "Hmm... Eu desenho bastante bem. Por que eu não desenho um belo Colosso para a sua guilda?",
  ui_story_5071_50710601_96_dialog_content = "Haha, acho que não cabe a nós projetar o Colossus.",
  ui_story_5071_50710601_97_dialog_content = "Infelizmente, essa atmosfera pacífica não foi feita para durar...",
  ui_story_5071_50710601_98_dialog_content = "Por que você parece tão chateado?",
  ui_story_5071_50710601_99_dialog_content = "Pai teve uma reunião com um parceiro de negócios hoje e me levou com ele.",
  ui_story_5071_50710601_100_dialog_content = "Isso é uma coisa boa. Significa que ele finalmente está disposto a ensinar você sobre assuntos da guilda. Isso nos deixará um passo mais perto de realizar nosso sonho.",
  ui_story_5071_50710601_101_dialog_content = "V-Você não entende... A pessoa que ele me apresentou...",
  ui_story_5071_50710601_102_dialog_content = "... era um negociante de veneno. Se o pai está se encontrando com ele, só pode significar—",
  ui_story_5071_50710601_103_dialog_content = "Minha família também não é inocente, o que explica porque o pai continua tentando me impedir.",
  ui_story_5071_50710601_104_dialog_content = "Não sei como vou encarar meu pai agora. O que devo fazer...",
  ui_story_5071_50710601_X104_dialog_content = "Sempre podemos usar os recursos do seu pai para realizar nossos sonhos.",
  ui_story_5071_50710601_105_dialog_content = "Usando esse tipo de recurso...? Não, você deve estar brincando, Kade...",
  ui_story_5071_50710601_106_dialog_content = "... Eu não percebi que você se sentia assim.",
  ui_story_5071_50710601_107_dialog_content = "Você sempre estará ao meu lado não importa o que aconteça, certo?",
  ui_story_5071_50710601_108_dialog_content = "...",
  ui_story_5071_50710601_109_dialog_content = "Vamos continuar jogando. Você pode ser o branco desta vez, e eu serei o preto.",
  ui_story_5071_50710601_110_dialog_content = "O que Valon não sabia era que Kade já havia feito o primeiro movimento.",
  ui_story_5071_50710601_111_dialog_content = "Queime cada gota de veneno!",
  ui_story_5071_50710601_112_dialog_content = "Entendido!",
  ui_story_5071_50710601_113_dialog_content = "Ai—",
  ui_story_5071_50710601_114_dialog_content = "Não se mova!",
  ui_story_5071_50710601_115_dialog_content = "Por que você está fazendo isso comigo? Quando foi que eu te prejudiquei?",
  ui_story_5071_50710601_116_dialog_content = "Se você vendesse todo esse veneno, não há como saber quantas famílias pereceriam por causa disso.",
  ui_story_5071_50710601_117_dialog_content = "Hah! Nem mesmo o Tribunal de Justiça de Lumopolis se importaria com isso!",
  ui_story_5071_50710601_118_dialog_content = "... Quem exatamente é você?",
  ui_story_5071_50710601_119_dialog_content = "Eu? Eu sou apenas... uma sombra errante passando pela cidade, só isso.",
  ui_story_5071_50710601_120_dialog_content = "Não muito tempo depois, para surpresa de todos, o pai de Valon convenceu Kade a se tornar seu filho adotivo. No entanto, Valon não estava presente durante a cerimônia de juramento de Kade.",
  ui_story_5071_50710601_121_dialog_content = "Kade recusou-se a mostrar qualquer sinal de preocupação em seu rosto. Com seus dois chifres negros erguidos orgulhosamente no ar, ele fez seus votos alto o suficiente para todos ouvirem—",
  ui_story_5071_50710601_122_dialog_content = "\"... Eu juro solenemente que não vou prejudicar minha própria família.\"",
  ui_story_5071_50710601_123_dialog_content = "\"Nem vou prejudicar os interesses da minha família...\"",
  ui_story_5071_50710701_1_dialog_content = "Os sonhos de Valon? Você tem a audácia de mencioná-los?",
  ui_story_5071_50710701_2_dialog_content = "Você é quem destruiu tudo—",
  ui_story_5071_50710701_3_dialog_content = "Sinto muito, Sra. Hanstie...",
  ui_story_5071_50710701_4_dialog_content = "Mas ainda vou lhe dar alguns conselhos... sobre escolher o parceiro certo.",
  ui_story_5071_50710701_5_dialog_content = "Admito que sei muito pouco sobre administrar um negócio.",
  ui_story_5071_50710701_6_dialog_content = "Mas se você está interessado em ganhar dinheiro legalmente em Umbraton, procure a Senhora Sheol.",
  ui_story_5071_50710701_7_dialog_content = "Posso prometer que farei tudo o que puder para ajudá-lo.",
  ui_story_5071_50710701_8_dialog_content = "Eu não preciso da sua promessa, então guarde-a, Senhor Sombrio.",
  ui_story_5071_50710701_9_dialog_content = "Acredito que você tenha uma ideia errada sobre mim.",
  ui_story_5071_50710701_10_dialog_content = "Talvez possamos sentar e conversar sobre os velhos tempos mais tarde, quando tivermos uma chance.",
  ui_story_5071_50710701_11_dialog_content = "Senhor das Sombras, é hora da próxima reunião...",
  ui_story_5071_50710701_12_dialog_content = "Entendido.",
  ui_story_5071_50710701_13_dialog_content = "Estou muito feliz em vê-la novamente, Sra. Hanstie.",
  ui_story_5071_50710701_14_dialog_content = "Espero que seja cuidadoso ao lidar com aqueles nas sombras e evite problemas desnecessários.",
  ui_story_5071_50710701_15_dialog_content = "Obrigado pelo lembrete, Senhor Sombrio. Eu sei o que estou fazendo.",
  ui_story_5071_50710701_16_dialog_content = "Ao contrário de algumas pessoas que só falam sobre o sonho de certos outros o tempo todo.",
  ui_story_5071_50710701_17_dialog_content = "Sem realmente medir...",
  ui_story_5071_50710701_18_dialog_content = "Quanto ele fez por isso todos esses anos?",
  ui_story_5071_50710701_19_dialog_content = "...",
  ui_story_5071_50710701_20_dialog_content = "Estranho, onde foi meu manuscrito...",
  ui_story_5071_50710701_21_dialog_content = "Eu poderia ter deixado isso no quarto?",
  ui_story_5071_50710701_22_dialog_content = "É sua vez, Sra. Yvonne!",
  ui_story_5071_50710701_23_dialog_content = "Sra. Hanstie, por favor, siga-me.",
  ui_story_5071_50710701_24_dialog_content = "Sim, já tô indo aí... Hmm?",
  ui_story_5071_50710701_25_dialog_content = "Minha senhora... Embora você seja claramente ainda muito jovem, seus olhos já testemunharam as vicissitudes da vida.",
  ui_story_5071_50710701_26_dialog_content = "Sua perna... Minhas desculpas, um resultado da minha ocupação, receio. Perdoe-me se de alguma forma eu te ofendi.",
  ui_story_5071_50710701_27_dialog_content = "Está bem. Eu não me importo.",
  ui_story_5071_50710701_28_dialog_content = "Você me dá a impressão de alguém com muitas histórias para contar. Me vejo profundamente curioso para saber mais sobre você.",
  ui_story_5071_50710701_29_dialog_content = "Também... Esse rico aroma de lírios—",
  ui_story_5071_50710701_30_dialog_content = "Isso me lembra de uma certa pessoa. Ela costumava usar uma fragrância encantadora como essa.",
  ui_story_5071_50710701_31_dialog_content = "Heheh. Estou muito feliz em ouvir você dizer isso - porque eu idolatro a Sra. Red Mercury.",
  ui_story_5071_50710701_32_dialog_content = "Adoro como você a retrata: misteriosa, forte, desinibida.",
  ui_story_5071_50710701_33_dialog_content = "A minha admiração pelo papel dela como guardiã silenciosa é a razão pela qual eu amo tanto os lírios.",
  ui_story_5071_50710701_34_dialog_content = "Memórias eternas, amor intransponível e bênçãos profundas. Isso é o que os lírios simbolizam, certo?",
  ui_story_5071_50710701_35_dialog_content = "Mas eu não gostei do que aconteceu com a Sra. Red Mercury nas sequências. Ela merecia um final melhor.",
  ui_story_5071_50710701_36_dialog_content = "... Já nos encontramos antes?",
  ui_story_5071_50710701_37_dialog_content = "Acho que não.",
  ui_story_5071_50710701_38_dialog_content = "Sra. Yvonne—",
  ui_story_5071_50710701_39_dialog_content = "Alguém está chamando meu nome?",
  ui_story_5071_50710701_40_dialog_content = "Sra. Yvonne, por favor, não faça o Senhor Sombrio esperar muito tempo.",
  ui_story_5071_50710701_41_dialog_content = "Ah! Me desculpe, estarei aí.",
  ui_story_5071_50710701_42_dialog_content = "Cheguei tarde demais e não pude devolver o manuscrito para ela.",
  ui_story_5071_50710701_43_dialog_content = "Os cães de guarda estão aqui!",
  ui_story_5071_50710701_44_dialog_content = "Sem escutar!",
  ui_story_5071_50710701_45_dialog_content = "Você poderia nos ajudar a entregar essa pilha de papéis para a Sra. Yvonne?",
  ui_story_5071_50710701_46_dialog_content = "Bons cãezinhos não devem perturbar o Senhor das Sombras!",
  ui_story_5071_50710701_47_dialog_content = "Que teimoso...",
  ui_story_5071_50710701_48_dialog_content = "Acho que vou ter que esperar ela sair.",
  ui_story_5071_50710701_49_dialog_content = "Devemos...",
  ui_story_5071_50710701_X49_dialog_content = "Leia só um pouquinho mais?",
  ui_story_5071_50710701_50_dialog_content = "...",
  ui_story_5071_50710701_51_dialog_content = "Embora o tabuleiro de xadrez entre os dois homens esteja impecável, um forte cheiro de sangue e batalha paira pesadamente no ar.",
  ui_story_5071_50710701_52_dialog_content = "Valon faz seu próximo movimento com total confiança, e o jogo é decidido. \"Xeque-mate\", ele diz triunfantemente.",
  ui_story_5071_50710701_53_dialog_content = "\"Você perdeu para mim mais uma vez\", ele acrescenta enquanto Kade recolhe silenciosamente as peças de xadrez.",
  ui_story_5071_50710701_54_dialog_content = "Valon percebe o lírio na mão de seu amigo e aproveita a oportunidade para fazer uma pergunta. \"Ouvi dizer que seu império das sombras acolheu mais algumas pessoas?\"",
  ui_story_5071_50710701_55_dialog_content = "As pessoas da Senhora Melissa não tinham para onde ir depois que ela faleceu. Eu simplesmente as acolhi.",
  ui_story_5071_50710701_56_dialog_content = "Por que você não me contou sobre isso antes?",
  ui_story_5071_50710701_57_dialog_content = "Eu não pensei que você estaria interessado em saber.",
  ui_story_5071_50710701_58_dialog_content = "O jovem demi-humano continua reorganizando o tabuleiro de xadrez. O rosto de Valon ainda não revela a solidão que ele sente em seu coração.",
  ui_story_5071_50710701_59_dialog_content = "Eles jogam xadrez em silêncio, e parece que tudo está bem entre eles.",
  ui_story_5071_50710701_60_dialog_content = "Não tive a chance de te contar como as coisas têm sido ultimamente. Depois de todo esse tempo longe de casa, finalmente fiz algum progresso.",
  ui_story_5071_50710701_61_dialog_content = "Consegui unificar todos os pequenos negócios na área circundante, e as pessoas pobres aqui realmente parecem nos apoiar agora. Nesse ritmo, não demorará muito para eu realizar meu sonho de ter uma guilda poderosa.",
  ui_story_5071_50710701_62_dialog_content = "Parabéns.",
  ui_story_5071_50710701_63_dialog_content = "... Como o pai tem estado?",
  ui_story_5071_50710701_64_dialog_content = "Tudo bem, eu suponho... Mas ele ainda sente muito a sua falta.",
  ui_story_5071_50710701_65_dialog_content = "Haha, não posso deixar de me sentir um pouco estranho quando pergunto sobre nosso pai. Acho que isso te faz um filho melhor da família Istvan do que eu.",
  ui_story_5071_50710701_66_dialog_content = "...",
  ui_story_5071_50710701_67_dialog_content = "Agora percebo que não posso fazer isso sozinho, Kade... Eu preciso do Bastão do Pastor do pai.",
  ui_story_5071_50710701_68_dialog_content = "É um símbolo de autoridade que está em nossa família por gerações. Com ele, finalmente posso assumir o controle dos ativos da nossa família.",
  ui_story_5071_50710701_69_dialog_content = "Só então poderei consolidar meu poder e reunir os chefes de Umbraton... para que eu possa eliminar todos eles.",
  ui_story_5071_50710701_70_dialog_content = "O jovem de cabelos azuis pega outra peça e murmura suavemente, \"Xeque-mate.\"",
  ui_story_5071_50710701_71_dialog_content = "Kade olha para o quadro por alguns momentos antes de voltar seu olhar para cima. \"Seus métodos são muito extremos.\"",
  ui_story_5071_50710701_72_dialog_content = "Pelo bem de Umbraton e dos fracos, não podemos fazer concessões. Nem mesmo um grão de sujeira deve ser deixado para trás.",
  ui_story_5071_50710701_73_dialog_content = "Isso não é justo com essas pessoas.",
  ui_story_5071_50710701_74_dialog_content = "Lembre-me novamente da sua promessa, Kade.",
  ui_story_5071_50710701_75_dialog_content = "Você disse que nunca me trairia, certo? Que sempre me apoiaria e estaria ao meu lado?",
  ui_story_5071_50710701_76_dialog_content = "O jovem semi-humano hesita por um momento enquanto o vento uiva lá fora. Nessa breve pausa, um mensageiro chega com uma mensagem ominosa:",
  ui_story_5071_50710701_77_dialog_content = "\"Uma grande horda de Eclipsitas se reuniu e está marchando diretamente para Umbraton.\"",
  ui_story_5071_50710701_78_dialog_content = "Em resposta à ameaça iminente, Lumopolis começou a discutir se deve ou não ajudar Umbraton. Alguns acreditam que esta é uma oportunidade para finalmente incorporar a cidade como parte de sua própria.",
  ui_story_5071_50710701_79_dialog_content = "Os jogadores de xadrez começaram a fazer seus movimentos... É natural, eu suponho. Até que escapemos da sombra de Lumópolis, este continuará a ser o destino da nossa cidade.",
  ui_story_5071_50710701_80_dialog_content = "Sempre há uma opção alternativa... Se eles desejam negociar, então devemos nos aproximar deles.",
  ui_story_5071_50710701_81_dialog_content = "Serei sua torre e continuarei pavimentando o caminho, então mantenha sua confiança, rei.",
  ui_story_5071_50710701_X81_dialog_content = "Um alto clac sinalizou outro novo jogo.",
  ui_story_5071_50710701_X82_dialog_content = "Era uma torre negra, mas lutava pelo rei branco.",
  ui_story_5071_50710701_82_dialog_content = "Arroto! O quarto da Senhorita Goldie é por aqui?",
  ui_story_5071_50710701_83_dialog_content = "Senhorita Goldie, posso ter seu autógrafo?",
  ui_story_5071_50710701_84_dialog_content = "Os cães de guarda estão aqui!",
  ui_story_5071_50710701_85_dialog_content = "Pronto para atacar!",
  ui_story_5071_50710701_86_dialog_content = "E-E-Espere! Apenas nos deixe lidar com isso...",
  ui_story_5071_50710701_87_dialog_content = "Não podemos causar mais problemas do que já causamos...",
  ui_story_5071_50710701_88_dialog_content = "Quem é você?",
  ui_story_5071_50710701_89_dialog_content = "Eu quero a senhorita Goldie! Senhorita Goldie!",
  ui_story_5071_50710702_1_dialog_content = "Essas pessoas são loucas... Trabalhar na segurança aqui é realmente difícil...",
  ui_story_5071_50710702_2_dialog_content = "Há muitos deles. Está fora de nossas mãos agora, então vamos continuar lendo!",
  ui_story_5071_50710702_3_dialog_content = "Depois de muitos anos, finalmente encontrei a vontade de continuar escrevendo essa biografia.",
  ui_story_5071_50710702_4_dialog_content = "Inicialmente, considerei minha escrita anterior muito lisonjeira e possivelmente uma má interpretação da verdade objetiva. Juntamente com as péssimas críticas dos meus trabalhos anteriores, senti a necessidade de parar de escrever indefinidamente.",
  ui_story_5071_50710702_5_dialog_content = "No entanto, o relato de um amigo sobre o passado me imergiu em uma enxurrada de inspiração. Considerando a má recepção das sequências de \"Sra. Red Mercury\", decidi basear a maior parte da minha escrita na história original, em vez de pura ficção.",
  ui_story_5071_50710702_6_dialog_content = "Talvez o final não seja o que meus leitores uma vez imaginaram, mas uma verdade tão trágica merece ser contada mesmo assim—",
  ui_story_5071_50710702_7_dialog_content = "Isso é tirado diretamente da verdadeira história por trás da Sra. Mercúrio Verm?",
  ui_story_5071_50710702_8_dialog_content = "Estou ainda mais animado para ler agora!",
  ui_story_5071_50710702_9_dialog_content = "Com uma espada como uma estrela cadente, Melissa atacou graciosamente o semi-humano que estava diante dela.",
  ui_story_5071_50710702_10_dialog_content = "\"Renda-se,\" ela ordenou friamente. \"Eu sei que você é a sombra que tem causado estragos em Umbraton.\"",
  ui_story_5071_50710702_11_dialog_content = "Por sequestrar e vender crianças, não teremos piedade de você!",
  ui_story_5071_50710702_12_dialog_content = "O filho de Melissa era como uma joia perdida para ela, uma à qual ela se apegou por muitos anos.",
  ui_story_5071_50710702_13_dialog_content = "Silenciosamente, seu oponente aparou a enxurrada de lâminas. Parecia que ele tinha seus motivos para manter seu teimoso silêncio também.",
  ui_story_5071_50710702_14_dialog_content = "Embora Melissa não tenha encontrado sua filha perdida aqui, ela não tinha intenção de deixar este sequestrador sair livre.",
  ui_story_5071_50710702_15_dialog_content = "No meio das espadas varrendo e das sombras, o semi-humano logo se viu forçado a um canto da sala. De repente, um alvoroço próximo soou.",
  ui_story_5071_50710702_16_dialog_content = "Pai—",
  ui_story_5071_50710702_17_dialog_content = "Cuidado!",
  ui_story_5071_50710702_18_dialog_content = "Uma multidão de crianças assustadas correu na frente dos dois combatentes. Atordoada, Melissa abaixou lentamente sua arma.",
  ui_story_5071_50710702_19_dialog_content = "Ao perceber que havia recebido informações erradas, Melissa guardou sua lâmina com uma expressão de decepção no rosto.",
  ui_story_5071_50710702_20_dialog_content = "\"Posso ajudá-la a encontrar sua filha\", disse o semi-humano conhecido como Kade, após ouvir sua história.",
  ui_story_5071_50710702_21_dialog_content = "Mas em troca, por favor, não se intrometa nos meus assuntos. Não faça nada para me impedir de derrotar as gangues aqui.",
  ui_story_5071_50710702_22_dialog_content = "Quase todas as pessoas nesta cidade são corruptas de uma forma ou de outra. Por que se preocupar com tudo isso?",
  ui_story_5071_50710702_23_dialog_content = "Para que essas crianças possam crescer saudáveis e fortes, mesmo que não estejamos mais lá para protegê-las.",
  ui_story_5071_50710702_24_dialog_content = "Isso... soa muito como a história da mãe da Senhora Sheol.",
  ui_story_5071_50710702_25_dialog_content = "Mas isso ainda não é uma obra de ficção? Talvez devêssemos... ler um pouco mais?",
  ui_story_5071_50710702_26_dialog_content = "Quando Kade viu Melissa pela última vez, ela já estava gravemente doente.",
  ui_story_5071_50710702_27_dialog_content = "Sua doença havia roubado sua beleza e a deixado em um estado triste e abatido.",
  ui_story_5071_50710702_28_dialog_content = "Quando seus olhos finalmente se encontraram novamente, Kade viu vulnerabilidade no olhar desta mulher outrora poderosa.",
  ui_story_5071_50710702_29_dialog_content = "\"Por favor, me ajude a encontrar minha filha.\"",
  ui_story_5071_50710702_30_dialog_content = "Foi seu último e único pedido. Em troca, ela encerrou todos os seus negócios que se envolviam em negociações obscuras.",
  ui_story_5071_50710702_31_dialog_content = "Sei que você vai cumprir sua promessa.",
  ui_story_5071_50710702_32_dialog_content = "Kade ficou em silêncio diante dela. Atrás de suas costas, um punhal afiado em sua mão brilhava com uma frieza pálida.",
  ui_story_5071_50710702_33_dialog_content = "Fique tranquilo, farei tudo que puder por ela.",
  ui_story_5071_50710702_34_dialog_content = "Livre de todas as suas preocupações, Melissa soltou um longo suspiro de alívio.",
  ui_story_5071_50710702_35_dialog_content = "\"Uma última coisa,\" ela disse de repente. \"O que você está escondendo atrás das costas?\"",
  ui_story_5071_50710702_36_dialog_content = "\"Nada\", disse Kade enquanto se aproximava lentamente dela, seu rosto obscurecido pelas sombras. \"Apenas um pequeno presente de despedida.\"",
  ui_story_5071_50710702_37_dialog_content = "<color=#e8d9bb>O texto termina abruptamente aqui. A tinta ainda está fresca, então parece ter sido escrito não faz muito tempo.</color>",
  ui_story_5071_50710702_38_dialog_content = "Hã? Mas como?",
  ui_story_5071_50710702_39_dialog_content = "Bom...",
  ui_story_5071_50710702_40_dialog_content = "O que está acontecendo com vocês duas crianças?",
  ui_story_5071_50710702_41_dialog_content = "É hora do leilão. Você deveria ir e ver se há algo que queira comprar, PlayerName querido.",
  ui_story_5071_50710702_42_dialog_content = "Meu leilão é diferente dos de Umbraton. É transparente e aberto. Você deveria conferir!",
  ui_story_5071_50710702_43_dialog_content = "O Senhor das Sombras e eu trabalhamos muito para fazer isso acontecer.",
  ui_story_5071_50710702_44_dialog_content = "Tudo de bom vai acabar se você não se mover rapidamente.",
  ui_story_5071_50710702_45_dialog_content = "Mas eu não tenho muito dinheiro para gastar... Espere, isso não é importante! Dê uma olhada nisso, Senhora Sheol!",
  ui_story_5071_50710702_46_dialog_content = "Há uma mulher no manuscrito da Sra. Yvonne que tem o mesmo nome que sua mãe...",
  ui_story_5071_50710702_47_dialog_content = "O quê? Deixe-me ver... A Sra. Yvonne sempre baseou suas histórias em Umbraton. Isso não é novidade.",
  ui_story_5071_50710702_48_dialog_content = "É um assassinato... Mas as ficções não são reais. As descrições em um romance geralmente são inventadas.",
  ui_story_5071_50710702_49_dialog_content = "Mas então por que ela usaria um nome verdadeiro?",
  ui_story_5071_50710702_50_dialog_content = "Não interprete demais, querida. Você pode perguntar à Sra. Yvonne depois que o leilão terminar.",
  ui_story_5071_50710702_51_dialog_content = "O que é importante é que o leilão está prestes a começar. Você não pode ficar aqui...",
  ui_story_5071_50710702_52_dialog_content = "Pelo menos não o Vergil, ele ainda tem que avaliar itens para mim!",
  ui_story_5071_50710702_53_dialog_content = "Talvez eu possa conseguir um tesouro barato...",
  ui_story_5071_50710702_54_dialog_content = "Espere por mim, Senhora Sheol!",
  ui_story_5071_50710801_1_dialog_content = "Não tenho nenhum outro pedido, exceto um, Senhor Sombrio. Eu apenas desejo publicar uma biografia sobre você.",
  ui_story_5071_50710801_2_dialog_content = "Tudo bem. Você não precisa da minha permissão.",
  ui_story_5071_50710801_3_dialog_content = "Umbraton acolhe a liberdade criativa.",
  ui_story_5071_50710801_4_dialog_content = "Entendo... E fico aliviado em ouvir você dizer isso, mas ainda gostaria de perguntar sobre certos detalhes daquela época...",
  ui_story_5071_50710801_5_dialog_content = "<color=#e8d9bb>Na cena do leilão na Aeronave Cloudrover</color>",
  ui_story_5071_50710801_6_dialog_content = "Ahem... O item que trouxemos para leilão é \"Um Canto do Deserto Rediesel\", uma obra do Mestre Finch em sua viagem.",
  ui_story_5071_50710801_7_dialog_content = "Mestre Finch é um renomado artista viajante com muitas obras de arte famosas em seu crédito, esta entre elas.",
  ui_story_5071_50710801_8_dialog_content = "Como podemos ver, Mestre Finch retratou o deserto sob um sol brilhante em camadas através de seu estilo romântico único.",
  ui_story_5071_50710801_9_dialog_content = "Ele destacou de forma não convencional a areia em azul para fazê-la parecer ondas do oceano-",
  ui_story_5071_50710801_10_dialog_content = "Hã? Eu pensei que a Guilda Cloudrover era responsável por organizar leilões?",
  ui_story_5071_50710801_11_dialog_content = "Defendemos o comércio livre e a transparência igualitária, para que todos tenham a chance de apresentar suas próprias ideias.",
  ui_story_5071_50710801_12_dialog_content = "Muitas pessoas em Umbraton realizaram leilões clandestinos no passado. Mas a origem das mercadorias sempre foi duvidosa, e o preço muitas vezes era irracional.",
  ui_story_5071_50710801_13_dialog_content = "Somos diferentes, porém. Você pode comprar ou vender em nossos leilões com segurança, com avaliações gratuitas para completar.",
  ui_story_5071_50710801_14_dialog_content = "Desculpe-me, mas esta pintura é uma falsificação... Vendê-la como um artigo genuíno seria uma fraude.",
  ui_story_5071_50710801_15_dialog_content = "(Esse carinha parece uma pessoa totalmente diferente quando está falando sobre sua profissão.)",
  ui_story_5071_50710801_16_dialog_content = "*sons barulhentos*",
  ui_story_5071_50710801_17_dialog_content = "Todos, por favor, acalmem-se! Que prova você tem para chamar isso de falsificação?",
  ui_story_5071_50710801_18_dialog_content = "Exatamente, seus sentidos são mais aguçados do que os nossos?",
  ui_story_5071_50710801_19_dialog_content = "Bem, agora é bastante óbvio quem é o vendedor...",
  ui_story_5071_50710801_20_dialog_content = "O Mestre Finch é famoso por suas representações dos costumes locais que ele viu durante suas viagens...",
  ui_story_5071_50710801_21_dialog_content = "Como resultado... Todas as suas obras de arte utilizam tintas e pigmentos de origem local.",
  ui_story_5071_50710801_22_dialog_content = "Mas o esquema de cores nesta pintura parece áspero e selvagem.",
  ui_story_5071_50710801_23_dialog_content = "Os destaques mais intensos de \"Um Canto no Deserto Rediesel\" deveriam ter sido pintados com pigmentos azuis brilhantes extraídos das camadas subterrâneas do deserto—",
  ui_story_5071_50710801_24_dialog_content = "Mas esta pintura utiliza gemas trituradas, um luxo incomum no Deserto Rediesel.",
  ui_story_5071_50710801_25_dialog_content = "O falsificador falhou em levar em conta as propriedades absorventes da areia quando usada para extrair pigmentos...",
  ui_story_5071_50710801_26_dialog_content = "Além disso, a areia na pintura original criou um tom mais claro, como o Mestre Finch queria que se assemelhasse às ondas do oceano.",
  ui_story_5071_50710801_27_dialog_content = "A tela usada para esta falsificação foi assada para replicar a textura do original. Ao fazer isso, as cores foram acidentalmente escurecidas...",
  ui_story_5071_50710801_28_dialog_content = "É tudo culpa sua! Não disse para ficar longe de todos esses truques sofisticados—",
  ui_story_5071_50710801_29_dialog_content = "Quem você está culpando? Você não conseguiria fazer uma cópia decente sem mim!",
  ui_story_5071_50710801_30_dialog_content = "Segurança, por favor, escolte-os para fora - ah, e certifique-se de que eles levem sua pintura com eles.",
  ui_story_5071_50710801_31_dialog_content = "Uau, Vergílio... Você realmente sabe das coisas!",
  ui_story_5071_50710801_32_dialog_content = "Você acha? É apenas algo pelo qual sou realmente apaixonado, só isso...",
  ui_story_5071_50710801_33_dialog_content = "É claro que ele tem. O profissionalismo do meu pequeno funcionário nunca é questionado.",
  ui_story_5071_50710801_34_dialog_content = "E isso certamente está além do nível de uma criança, querido.",
  ui_story_5071_50710801_35_dialog_content = "Hum...",
  ui_story_5071_50710801_36_dialog_content = "Olá a todos e bem-vindos ao leilão. Eu vou mostrar o próximo item para vocês.",
  ui_story_5071_50710801_37_dialog_content = "Esta é uma pintura a óleo de um cliente anônimo meu. O artista também é desconhecido.",
  ui_story_5071_50710801_38_dialog_content = "Esta é uma obra-prima do ponto de vista técnico. Espero que todos vocês gostem.",
  ui_story_5071_50710801_39_dialog_content = "Esta pintura é chamada - \"A Morte da Senhora\"!",
  ui_story_5071_50710801_40_dialog_content = "Como o valor não pode ser determinado, o lance inicial será de cinquenta milhões.",
  ui_story_5071_50710801_41_dialog_content = "É aquela... a Sra. Red Mercury na pintura? E o assassino parado ao lado parece com...",
  ui_story_5071_50710801_42_dialog_content = "Não, parece ser a Lady Melissa...",
  ui_story_5071_50710801_43_dialog_content = "O que é isso? Por que parece com as costas do Senhor Sombrio?",
  ui_story_5071_50710801_44_dialog_content = "Aquela pintura... Mas como isso pode ser?",
  ui_story_5071_50710801_45_dialog_content = "PlayerName querido, você poderia dar um lance naquela pintura para mim?",
  ui_story_5071_50710801_46_dialog_content = "Não sei de quem é o pedido, mas não posso dar um lance como líder da guilda, então por favor... Apenas diga o preço.",
  ui_story_5071_50710801_47_dialog_content = "Sessenta milhões.",
  ui_story_5071_50710801_48_dialog_content = "Um milhão.",
  ui_story_5071_50710801_49_dialog_content = "Faça uma jogada, querida!",
  ui_story_5071_50710801_50_dialog_content = "Um milhão dois!",
  ui_story_5071_50710801_51_dialog_content = "Um milhão quatro!",
  ui_story_5071_50710801_52_dialog_content = "*tagarela*",
  ui_story_5071_50710801_53_dialog_content = "Bom...",
  ui_story_5071_50710801_54_dialog_content = "(Quanto tempo vai me levar para economizar novamente?)",
  ui_story_5071_50710801_55_dialog_content = "Não fique aí sentada, querida. Dê um lance, dinheiro não é problema!",
  ui_story_5071_50710801_56_dialog_content = "T-Dois milhões!",
  ui_story_5071_50710801_57_dialog_content = "*silêncio*",
  ui_story_5071_50710801_58_dialog_content = "Dois milhões indo uma vez... Mais algum lance? Dois milhões indo duas vezes!",
  ui_story_5071_50710801_59_dialog_content = "Dois milhões três vezes... Vendido para o Celestita!",
  ui_story_5071_50710801_60_dialog_content = "Com certeza estou surpreso que uma obra desconhecida possa alcançar um preço tão alto. Vamos aplaudir o Celestita por ter um olhar tão perspicaz.",
  ui_story_5071_50710801_61_dialog_content = "Senhora Sheol realmente tem bom gosto.",
  ui_story_5071_50710801_62_dialog_content = "Eu não esperava que você gostasse tanto da pintura a ponto de quebrar as regras e conseguir um substituto.",
  ui_story_5071_50710801_63_dialog_content = "Talvez tenhamos muito mais em comum do que percebemos. Não é à toa que o Senhor das Sombras me recomendou você.",
  ui_story_5071_50710801_64_dialog_content = "Estou lisonjeado. Você é realmente impressionante por fundar uma guilda trans-Astra fora de Umbraton.",
  ui_story_5071_50710801_65_dialog_content = "E vejo que você também tem laços com o Senhor Sombrio. Eu deveria ser o único a seguir você.",
  ui_story_5071_50710801_66_dialog_content = "... Eu gosto de você, tanto que não me importo de perder a pintura para você.",
  ui_story_5071_50710801_67_dialog_content = "Bem, obrigado, Sra. Hanstie.",
  ui_story_5071_50710801_68_dialog_content = "D-Devemos ir pagar pela pintura agora, Senhora Sheol.",
  ui_story_5071_50710801_69_dialog_content = "Você achou que eu te deixaria na mão, PlayerName? Vamos, vamos ver a pintura.",
  ui_story_5071_50710801_70_dialog_content = "May Eu vou com você, Senhora Sheol?",
  ui_story_5071_50710801_71_dialog_content = "De nada.",
  ui_story_5071_50710801_72_dialog_content = "Hã? Hmm... Sinto um cheiro—",
  ui_story_5071_50710801_73_dialog_content = "Esse aroma suave...",
  ui_story_5071_50710801_74_dialog_content = "Senhora Sheol... Acho que essa falsificação foi feita por \"A\", meu falsificador favorito.",
  ui_story_5071_50710801_75_dialog_content = "Esta é a primeira vez que vejo uma de suas obras originais depois de conhecê-los por tanto tempo!",
  ui_story_5071_50710801_76_dialog_content = "Oh? A equipe de leilão que contratei desta vez não é tão profissional quanto você, pelo que vejo.",
  ui_story_5071_50710801_77_dialog_content = "A origem desta pintura é desconhecida, então como você deduziu quem é o artista, meu filho?",
  ui_story_5071_50710801_78_dialog_content = "Bem... Eu costumo trabalhar com muitos produtos falsificados, então me familiarizei bastante com o trabalho de muitos falsificadores habilidosos.",
  ui_story_5071_50710801_79_dialog_content = "Mas o maior entre eles é um artista conhecido como \"A.\"",
  ui_story_5071_50710801_80_dialog_content = "Além de suas habilidades incomparáveis, eles também gostam de esconder uma pequena letra \"A\" em algum lugar em suas falsificações. É como uma marca registrada de seu trabalho.",
  ui_story_5071_50710801_81_dialog_content = "Às vezes está no cabelo de uma pessoa ou nos olhos delas - desta vez, está na gola da camisa de uma pessoa.",
  ui_story_5071_50710801_82_dialog_content = "... Você notou tudo isso? Você deve realmente gostar de A.",
  ui_story_5071_50710801_83_dialog_content = "Por mais que eu goste de \"A\", eu realmente acho que eles são bastante egocêntricos. Quer dizer, por que mais eles escolheriam deixar um sinal de sua presença em uma falsificação?",
  ui_story_5071_50710801_84_dialog_content = "\"A\" me parece uma pessoa que nunca desistirá de sua busca para alcançar seus objetivos.",
  ui_story_5071_50710801_85_dialog_content = "Sério? Isso é bem... interessante.",
  ui_story_5071_50710801_86_dialog_content = "Hã?",
  ui_story_5071_50710801_87_dialog_content = "U-Um estranho...",
  ui_story_5071_50710801_88_dialog_content = "Acho que não faz sentido se esconder atrás de mim agora...",
  ui_story_5071_50710801_89_dialog_content = "Não tenha medo. Eu aprecio muito você, meu filho.",
  ui_story_5071_50710801_90_dialog_content = "Posso dizer que você tem um grande potencial. Teria interesse em trabalhar para mim?",
  ui_story_5071_50710801_91_dialog_content = "Desculpe, Sra. Hanstie, mas Vergílio trabalha para mim.",
  ui_story_5071_50710801_92_dialog_content = "Ah, que azar. Parece que a Senhora Sheol sempre me supera.",
  ui_story_5071_50710801_93_dialog_content = "Não, você está exagerando. Mas que tal uma obra de arte à sua escolha da minha coleção privada como compensação?",
  ui_story_5071_50710801_94_dialog_content = "Isso não é necessário. Eu não quero privar os outros de suas posses preciosas—",
  ui_story_5071_50710801_95_dialog_content = "Aliás, você também não sabia quem pintou isso, então por que a afinidade?",
  ui_story_5071_50710801_96_dialog_content = "Duvido que você pagaria um preço tão exorbitante simplesmente por causa da técnica artística.",
  ui_story_5071_50710801_97_dialog_content = "Bem, digamos que eu quisesse ajudar um velho amigo.",
  ui_story_5071_50710801_98_dialog_content = "Se essa pintura chegasse a Umbraton, provavelmente causaria um grande dano à reputação que ele vem construindo.",
  ui_story_5071_50710801_99_dialog_content = "Mas já que você comprou para ele, terminei aqui.",
  ui_story_5071_50710801_100_dialog_content = "Até mais, todos.",
  ui_story_5071_50710801_101_dialog_content = "Espere, Sra. Hanstie, tenho mais uma pergunta para você.",
  ui_story_5071_50710801_102_dialog_content = "Você conhece o Senhor das Sombras há muito tempo?",
  ui_story_5071_50710801_103_dialog_content = "Heheh... Você quer dizer a pessoa real? Provavelmente mais tempo do que você imagina.",
  ui_story_5071_50710801_104_dialog_content = "Hum—",
  ui_story_5071_50710801_105_dialog_content = "Qual é o seu problema? Encarando ela desse jeito... Você está ponderando a proposta dela?",
  ui_story_5071_50710801_106_dialog_content = "N-N-De jeito nenhum! É só que...",
  ui_story_5071_50710801_107_dialog_content = "Vergil... Você também acha que é estranho demais para ser apenas uma coincidência, certo?",
  ui_story_5071_50710801_108_dialog_content = "Esta pintura é exatamente como a parte da história que lemos naquele manuscrito...",
  ui_story_5071_50710801_109_dialog_content = "Será que o amigo artista da Sra. Yvonne não é outro senão o \"A\"?",
  ui_story_5071_50710801_110_dialog_content = "Ela disse que começou a escrever novamente depois de fazer amizade com um certo artista...",
  ui_story_5071_50710801_111_dialog_content = "Você está certo, querido, isso é demais para ser apenas uma coincidência.",
  ui_story_5071_50710801_112_dialog_content = "Como se fosse encenado para nós vermos.",
  ui_story_5071_50710801_113_dialog_content = "Eu não entendo, Senhora Sheol... Qual seria o propósito de tudo isso?",
  ui_story_5071_50710801_114_dialog_content = "Apenas duas explicações para essa cadeia de eventos-",
  ui_story_5071_50710801_115_dialog_content = "Se não for para me dizer a verdade, só pode ser...",
  ui_story_5071_50710801_116_dialog_content = "Qual é o seguimento para este manuscrito, querido?",
  ui_story_5071_50710801_117_dialog_content = "Dê uma olhada no que vem depois—",
  ui_story_5071_50710901_1_dialog_content = "Com um cajado dourado na mão, o semi-humano ficou no centro do Pit. Uma multidão gritando liderada por um velho amigo o cercava por todos os lados.",
  ui_story_5071_50710901_2_dialog_content = "\"Traidor!\" eles gritaram. \"Por que você levaria o exército de Lumópolis direto para a porta de Umbraton?\"",
  ui_story_5071_50710901_3_dialog_content = "O semi-humano permaneceu em silêncio, seu olhar firme focado no rosto de um único homem. Sob seus cabelos azuis, os olhos de Valon estavam cheios de dor e tristeza.",
  ui_story_5071_50710901_4_dialog_content = "Depois de um longo tempo, Valon finalmente abriu a boca para falar. \"Kade... Por quê? Por que você matou nosso pai e roubou o Cajado do Pastor?\"",
  ui_story_5071_50710901_5_dialog_content = "Você virou as costas para o nosso sonho? Por que você obedeceria à vontade de Lumópolis?",
  ui_story_5071_50710901_6_dialog_content = "O Poço... Enfrentei tantos inimigos em seu lugar há tantos anos atrás. Você realmente acha que pode me parar com tão poucas pessoas?",
  ui_story_5071_50710901_7_dialog_content = "Uma única pergunta foi suficiente para enviar pânico por toda a multidão.",
  ui_story_5071_50710901_8_dialog_content = "O quê... Mas eu pensei que eles eram melhores amigos?",
  ui_story_5071_50710901_9_dialog_content = "... Continue lendo.",
  ui_story_5071_50710901_10_dialog_content = "\"Você é muito fraco! É por isso que eu tenho que te substituir!\"",
  ui_story_5071_50710901_11_dialog_content = "Com um rugido, Kade avançou e enfiou o cajado no peito do amigo. Seu rosto enlouquecido e distorcido já não era mais reconhecível, nem mesmo para seu próprio irmão.",
  ui_story_5071_50710901_12_dialog_content = "O-Por quê...",
  ui_story_5071_50710901_13_dialog_content = "Recuso-me a ser a sombra de alguém.",
  ui_story_5071_50710901_14_dialog_content = "Com o rosto ainda congelado de choque, o jovem de cabelos azuis desabou no chão. Logo, o público estava preenchido com desespero.",
  ui_story_5071_50710901_15_dialog_content = "Em sua dor e fúria, eles se lançaram na luta—",
  ui_story_5071_50710901_16_dialog_content = "F-Vire para a próxima página!",
  ui_story_5071_50710901_17_dialog_content = "A brutal fúria de Kade finalmente foi liberada. Por estarem em seu caminho, ele rapidamente destroçou seus concidadãos de Umbraton.",
  ui_story_5071_50710901_18_dialog_content = "Para erradicar toda a dissidência, ele banhou Umbraton em um inferno AZURE, garantindo que ninguém fosse poupado de sua WRATH.",
  ui_story_5071_50710901_19_dialog_content = "De maneira peremptória, ele finalmente agarrou a autoridade absoluta em suas mãos.",
  ui_story_5071_50710901_20_dialog_content = "Para assumir o controle de Umbraton, ele traiu seu sonho e entregou sua casa a Lumopolis.",
  ui_story_5071_50710901_21_dialog_content = "Para isso, ele tirou a vida de seu irmão e usurpou seu sobrenome, além de usurpar o status proeminente de sua família—",
  ui_story_5071_50710901_22_dialog_content = "Ele escolheu seguir um caminho de maldade e perversidade. Ao ascender ao poder, ele encobriu seu passado e a existência de Valon, seu ex-irmão.",
  ui_story_5071_50710901_23_dialog_content = "Quando Umbraton finalmente cai sob seu controle total, ninguém se lembra de qualquer parte de seu passado cruel.",
  ui_story_5071_50710901_24_dialog_content = "Tudo o que eles sabem é que ele comanda sua gangue com um cajado manchado de sangue.",
  ui_story_5071_50710901_25_dialog_content = "Istvan, o Senhor Sombrio de Umbraton.",
  ui_story_5071_50710901_26_dialog_content = "O-O que?",
  ui_story_5071_50710901_27_dialog_content = "Esse cara, Kade... Ele era o Senhor das Sombras o tempo todo?",
  ui_story_5071_50710901_28_dialog_content = "Isso não pode estar certo! O Senhor das Sombras nunca trairia Umbraton dessa maneira!",
  ui_story_5071_50710901_29_dialog_content = "(Sempre senti algo perigoso escondido no coração do Senhor Sombrio, mas a história neste manuscrito...)",
  ui_story_5071_50710901_30_dialog_content = "...",
  ui_story_5071_50710901_31_dialog_content = "Senhora Sheol, a Senhora das Sombras...",
  ui_story_5071_50710901_32_dialog_content = "As pessoas são secretas. Não podemos simplesmente acreditar no que eles dizem, mas—",
  ui_story_5071_50710901_33_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5071_50710901_34_dialog_content = "O que está acontecendo? De onde veio essa explosão?",
  ui_story_5071_50710901_35_dialog_content = "Senhora Sheol! P-Por algum motivo, os guardas de Lumópolis a bordo nos atacaram de repente!",
  ui_story_5071_50710901_36_dialog_content = "Por que os guardas de Lumopolis nos atacariam?",
  ui_story_5071_50710901_37_dialog_content = "Eu desagradei alguém?",
  ui_story_5071_50710901_38_dialog_content = "Pare com isso! O que você acha que está fazendo com a aeronave da Senhora Sheol?",
  ui_story_5071_50710901_39_dialog_content = "Ainda estamos no ar! Se você continuar danificando o dirigível, todos a bordo morrerão—",
  ui_story_5071_50710901_40_dialog_content = "Vamos ensinar uma lição dura a esses tolos!",
  ui_story_5071_50710901_41_dialog_content = "Pare! Não faça isso...",
  ui_story_5071_50710901_42_dialog_content = "Isso colocará todos em grave perigo!",
  ui_story_5071_50710901_43_dialog_content = "Pare de mexer no meu território!",
  ui_story_5071_50710901_X43_dialog_content = "A-ahn?!",
  ui_story_5071_50710901_X44_dialog_content = "Por que vocês ignorantes brutamontes...",
  ui_story_5071_50710901_X45_dialog_content = "Como ousa tentar destruir minha aeronave!",
  ui_story_5071_50710901_X46_dialog_content = "Eca!",
  ui_story_5071_50710901_X47_dialog_content = "O-Que chute incrível!",
  ui_story_5071_50710901_X48_dialog_content = "Não posso acreditar que esse é o meu chefe!",
  ui_story_5071_50710901_X49_dialog_content = "É-Esta é a primeira vez que a vejo lutar!",
  ui_story_5071_50710901_44_dialog_content = "O-O que um incrível chute em queda—",
  ui_story_5071_50710901_45_dialog_content = "Senhora Sheol...",
  ui_story_5071_50710901_46_dialog_content = "Senhor Sombrio, parece haver uma agitação lá fora. Alguém parece ter se infiltrado.",
  ui_story_5071_50710901_47_dialog_content = "Ah?",
  ui_story_5071_50710901_48_dialog_content = "Vejo que o \"convidado\" está ficando impaciente. Interessante.",
  ui_story_5071_50710901_49_dialog_content = "?",
  ui_story_5071_50711001_1_dialog_content = "O que houve?",
  ui_story_5071_50711001_2_dialog_content = "Senhor das Sombras! Você finalmente chegou! Estes—",
  ui_story_5071_50711001_3_dialog_content = "Senhor Sombrio, por que está fazendo isso? Não foi você quem nos ordenou a fazer isso?",
  ui_story_5071_50711001_4_dialog_content = "Você nos ordenou para remover esses encrenqueiros, então por que você...",
  ui_story_5071_50711001_5_dialog_content = "!",
  ui_story_5071_50711001_6_dialog_content = "Então o Senhor Sombrio está por trás disso?",
  ui_story_5071_50711001_7_dialog_content = "Não é de se admirar que esses guardas de Lumopolis sejam...",
  ui_story_5071_50711001_8_dialog_content = "Por que eles estão nos tratando assim...",
  ui_story_5071_50711001_9_dialog_content = "Fique quieto. A situação não é—",
  ui_story_5071_50711001_10_dialog_content = "<color=#e8d9bb>Inúmeras folhas de papel de repente voam pelo ar e caem como flocos de neve. Estes são—</color>",
  ui_story_5071_50711001_11_dialog_content = "Os manuscritos da Sra. Yvonne?",
  ui_story_5071_50711001_12_dialog_content = "Todas as páginas foram espalhadas por toda parte! Quem poderia ter...",
  ui_story_5071_50711001_13_dialog_content = "Espere, estas páginas do manuscrito são todas iguais. Dê uma olhada.",
  ui_story_5071_50711001_14_dialog_content = "Depois de muitos anos, finalmente retornei a este lugar. Istvan é o governante de Umbraton agora, e o sonho de Valon da Guilda de Umbraton se tornou uma ferramenta de sua autoridade.",
  ui_story_5071_50711001_15_dialog_content = "Devo continuar escrevendo em nome da verdade? Ou devo manter essas histórias enterradas profundamente em meu coração?",
  ui_story_5071_50711001_16_dialog_content = "Sempre assisti a eventos perversos se desenrolando diante de mim, desgastando minha consciência. No início, pensei que tinha me acostumado com isso.",
  ui_story_5071_50711001_17_dialog_content = "Se eu não tivesse descoberto a verdade sobre suas últimas ambições, eu poderia ter continuado observando de longe—",
  ui_story_5071_50711001_18_dialog_content = "Por pura coincidência, aprendi sobre a insaciável ganância de Istvan através de seus subordinados. Embora ele esteja firmemente no topo, ainda deseja mais.",
  ui_story_5071_50711001_19_dialog_content = "Embora se apresente como um governante generoso, ele secretamente está insatisfeito com as gangues e guildas neutras.",
  ui_story_5071_50711001_20_dialog_content = "Aqueles que operam fora do controle de sua guilda o deixaram nervoso... Ele não tolerará rebelião de qualquer tipo.",
  ui_story_5071_50711001_21_dialog_content = "Por esse motivo, ele planeja usar a Guilda Cloudrover para reunir sua oposição em potencial e destruí-los de uma vez por todas. Ao fazer isso, ele alcançará o que sempre buscou - controle absoluto sobre Umbraton.",
  ui_story_5071_50711001_22_dialog_content = "Com o pouco tempo que me resta neste mundo, desejo fazer justiça a um homem cujo passado foi esquecido.",
  ui_story_5071_50711001_23_dialog_content = "—Assinado, Yvonne.",
  ui_story_5071_50711001_24_dialog_content = "Isso é verdade?",
  ui_story_5071_50711001_25_dialog_content = "A Sra. Yvonne e o Senhor Sombrio acabaram de ter uma reunião, certo?",
  ui_story_5071_50711001_26_dialog_content = "Acalme-se! Tem algo estranho neste manuscrito.",
  ui_story_5071_50711001_27_dialog_content = "Já que o Senhor Sombrio está aqui, isso não significa que a Sra. Yvonne está...",
  ui_story_5071_50711001_28_dialog_content = "Isso é muito unilateral...",
  ui_story_5071_50711001_29_dialog_content = "Seremos todos silenciados?",
  ui_story_5071_50711001_30_dialog_content = "Você tem mais? Mostre-nos!",
  ui_story_5071_50711001_31_dialog_content = "H-Espere!",
  ui_story_5071_50711001_32_dialog_content = "Por favor, mantenham a compostura, todos.",
  ui_story_5071_50711001_33_dialog_content = "É... É um...",
  ui_story_5071_50711001_34_dialog_content = "Isso é verdade? Isso é realmente um relato do passado do Senhor Sombrio?",
  ui_story_5071_50711001_35_dialog_content = "*suspiro* Eles não estão ouvindo nada—",
  ui_story_5071_50711001_36_dialog_content = "Esses rumores eram realmente verdadeiros? E ele quer nos matar agora?",
  ui_story_5071_50711001_37_dialog_content = "Parem de discutir. Isso é apenas um romance. Vocês realmente acreditam que é verdade?",
  ui_story_5071_50711001_38_dialog_content = "Mas combina perfeitamente com os rumores...",
  ui_story_5071_50711001_39_dialog_content = "Já que você sabe que são rumores, quão confiáveis você acha que eles são?",
  ui_story_5071_50711001_40_dialog_content = "Mas a Guilda Umbraton realmente controla nossas rotas comerciais. Como você sabe que ele não está nos usando para se tornar mais poderoso?",
  ui_story_5071_50711001_41_dialog_content = "Todo o nosso dinheiro está depositado na Guilda de Umbraton... Se ele realmente decidir nos matar e pegar nosso dinheiro...",
  ui_story_5071_50711001_42_dialog_content = "Comerciantes estúpidos, maus comerciantes! Por que vocês acreditam em tudo que ouvem?",
  ui_story_5071_50711001_43_dialog_content = "O chefe não é esse tipo de pessoa!",
  ui_story_5071_50711001_44_dialog_content = "É apenas uma adaptação!",
  ui_story_5071_50711001_45_dialog_content = "Você não vai explicar, Senhor das Sombras?",
  ui_story_5071_50711001_46_dialog_content = "(Senhor das Sombras?)",
  ui_story_5071_50711001_47_dialog_content = "(Ele está... observando eles?)",
  ui_story_5071_50711001_48_dialog_content = "Parece que o líder da Guilda do Pantera Vermelha tem algo a dizer... A Guilda do Papagaio Cinza, também...",
  ui_story_5071_50711001_49_dialog_content = "(Não, não é isso...)",
  ui_story_5071_50711001_50_dialog_content = "A Gangue do Falcão Enferrujado, também... Entendo.",
  ui_story_5071_50711001_51_dialog_content = "(Ele está avaliando sua presa.)",
  ui_story_5071_50711001_52_dialog_content = "Relatando! Isso é ruim, Senhora Sheol!",
  ui_story_5071_50711001_53_dialog_content = "Srta. Yvonne está...",
  ui_story_5071_50711001_54_dialog_content = "<size=45>A Sra. Yvonne está morta na sala de recepção temporária!</size>",
  ui_story_5071_50711101_1_dialog_content = "O limpador responsável pela limpeza desta sala de recepção temporária é quem fez a descoberta.",
  ui_story_5071_50711101_2_dialog_content = "Tudo está arrumado e limpo na cena. Não houve luta entre a vítima e o assassino.",
  ui_story_5071_50711101_3_dialog_content = "A única coisa que encontramos foi alguns cabelos no tapete em que a Sra. Yvonne estava deitada.",
  ui_story_5071_50711101_4_dialog_content = "Isso não é o cabelo de um Aurorian comum. Na verdade, parece mais com o cabelo de uma fera, mas foi mantido em excelente condição...",
  ui_story_5071_50711101_5_dialog_content = "Senhor das Sombras, este salão de recepção temporário foi emprestado a você... Certo?",
  ui_story_5071_50711101_6_dialog_content = "Lembre-nos onde você estava agora mesmo, meu senhor?",
  ui_story_5071_50711101_7_dialog_content = "Cuidado com o que você está dizendo. Você está duvidando do meu chefe?",
  ui_story_5071_50711101_8_dialog_content = "Seleucid.",
  ui_story_5071_50711101_9_dialog_content = "Mas chefe...",
  ui_story_5071_50711101_10_dialog_content = "Você deveria ser mais cuidadoso se era apenas uma conjectura e não uma acusação direta.",
  ui_story_5071_50711101_11_dialog_content = "Até um momento atrás, eu estava discutindo os livros da Sra. Yvonne com ela.",
  ui_story_5071_50711101_12_dialog_content = "Eu só vim para ver o que era a comoção.",
  ui_story_5071_50711101_13_dialog_content = "Mas a Sra. Yvonne estava animada na época, afirmando que acabara de ter uma inspiração.",
  ui_story_5071_50711101_14_dialog_content = "Então eu a deixei sozinha, não querendo perturbá-la.",
  ui_story_5071_50711101_15_dialog_content = "E a Sra. Yvonne morreu aqui depois. Como isso é possível?",
  ui_story_5071_50711101_16_dialog_content = "Acabamos de ouvir que a Sra. Yvonne tem alguns materiais comprometedores sobre o passado do Senhor Sombrio.",
  ui_story_5071_50711101_17_dialog_content = "É suspeito como ela morreu...",
  ui_story_5071_50711101_18_dialog_content = "Todos, por favor, não espalhem rumores entre o público.",
  ui_story_5071_50711101_19_dialog_content = "Quem é esse? Quem está espalhando boatos? Apareça!",
  ui_story_5071_50711101_20_dialog_content = "Talvez também seremos devorados pelas sombras, assim como ela.",
  ui_story_5071_50711101_21_dialog_content = "May Eu pergunto quem é você, senhor? Parece que você realmente deseja <color=#FFB400>falar o que pensa</color>, então por que não se aproxima para que todos nós possamos ouvir?",
  ui_story_5071_50711101_22_dialog_content = "Chega, Kleken.",
  ui_story_5071_50711101_23_dialog_content = "Não estrague o dia importante de Sheol.",
  ui_story_5071_50711101_24_dialog_content = "Ah... Como isso pode ser...",
  ui_story_5071_50711101_25_dialog_content = "Srta. Yvonne...",
  ui_story_5071_50711101_26_dialog_content = "Ela parece tão tranquila com aquele sorriso no rosto, como se estivesse apenas dormindo...",
  ui_story_5071_50711101_27_dialog_content = "Ela não tem nenhum ferimento, então podemos descartar uma emboscada...",
  ui_story_5071_50711101_28_dialog_content = "É possível... que ela tenha sido envenenada?",
  ui_story_5071_50711101_29_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5071_50711101_30_dialog_content = "A-A aeronave está tremendo!",
  ui_story_5071_50711101_31_dialog_content = "Provavelmente é devido ao ataque de agora há pouco... Não entrem em pânico, todos.",
  ui_story_5071_50711101_32_dialog_content = "Essa aeronave é robusta e confiável—",
  ui_story_5071_50711101_33_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5071_50711101_34_dialog_content = "... Entre em contato com o líder de engenharia e peça para ele verificar se há danos.",
  ui_story_5071_50711101_35_dialog_content = "Sim, senhora!",
  ui_story_5071_50711101_36_dialog_content = "Todos, por favor, permaneçam calmos e me ouçam.",
  ui_story_5071_50711101_37_dialog_content = "Hoje é um dia importante para minha amiga. Estou aqui estritamente para comemorar o sonho dela se tornando realidade.",
  ui_story_5071_50711101_38_dialog_content = "Não vou sabotar esta ocasião alegre, nem tolerar que alguém o faça.",
  ui_story_5071_50711101_39_dialog_content = "Os Guardiões embarcarão e investigarão assim que pousarmos.",
  ui_story_5071_50711101_40_dialog_content = "Claro, eles também vão me escrutinar. Aceito todas as consequências caso eles me encontrem envolvido de alguma forma.",
  ui_story_5071_50711101_41_dialog_content = "Mas eu me lembro que os Guardiões seguem as ordens da Guilda Umbraton...",
  ui_story_5071_50711101_42_dialog_content = "E todos eles são da Gangue Istvan.",
  ui_story_5071_50711101_43_dialog_content = "Sua filha não é a líder da Guilda de Umbraton?",
  ui_story_5071_50711101_44_dialog_content = "Eu não te conheço de todo, mas parece que você tem uma opinião forte sobre mim.",
  ui_story_5071_50711101_45_dialog_content = "Isso é uma ameaça?",
  ui_story_5071_50711101_46_dialog_content = "Há algo que eu estou realmente curioso, Senhor das Sombras. Você realmente será punido?",
  ui_story_5071_50711101_47_dialog_content = "O chamado Regulamento de Segurança de Umbraton acabou de ser anunciado. Sua promessa é muito vazia!",
  ui_story_5071_50711101_48_dialog_content = "Nunca esperei a morte da Sra. Yvonne. Que pena...",
  ui_story_5071_50711101_49_dialog_content = "Como seu velho amigo, pensei que você poderia ter mudado.",
  ui_story_5071_50711101_50_dialog_content = "Mesmo após todos esses anos, parece que você e Umbraton ainda não esqueceram as cicatrizes do passado.",
  ui_story_5071_50711101_51_dialog_content = "Istvan... não, <color=#FFB400>Kade</color>, você realmente não vai nos deixar viver?",
  ui_story_5071_50711101_52_dialog_content = "Você fará como fez há tantos anos atrás...",
  ui_story_5071_50711101_53_dialog_content = "E destruir todos que desobedecem você mais uma vez?",
  ui_story_5071_50711101_54_dialog_content = "...",
  ui_story_5071_50711101_55_dialog_content = "*sussurra*",
  ui_story_5071_50711101_56_dialog_content = "Ouvi dizer que o Shadowlord removeu todos que se opuseram a ele para...",
  ui_story_5071_50711101_57_dialog_content = "Você está falando sobre aquele incidente do Poço nos manuscritos, certo?",
  ui_story_5071_50711101_58_dialog_content = "O Pit estava cheio de líderes de Umbraton antes da Crise Darkover nos atingir. Ouvi dizer que o Shadowlord lutou sozinho contra cem ali.",
  ui_story_5071_50711101_59_dialog_content = "Isso mesmo. Eles eram exatamente como nós. Eles também eram líderes de Umbraton...",
  ui_story_5071_50711101_60_dialog_content = "Ele é tão poderoso. É por isso que ele é o Senhor das Sombras.",
  ui_story_5071_50711101_61_dialog_content = "Você ouve isso, <color=#FFB400>Kade</color>? Seu passado não foi completamente obscurecido.",
  ui_story_5071_50711101_62_dialog_content = "Você assassinou seu amigo e seu pai adotivo, e eu sei que não sou o único que se lembra!",
  ui_story_5071_50711101_63_dialog_content = "Então o conteúdo desses manuscritos é...",
  ui_story_5071_50711101_64_dialog_content = "Temo que o passado seja muito mais cruel do que o documentado. Ele pode ter adotado meios ainda mais descarados e inescrupulosos para chegar onde está agora—",
  ui_story_5071_50711101_65_dialog_content = "Ele definitivamente é capaz de fazer algo assim!",
  ui_story_5071_50711101_66_dialog_content = "Os métodos dele são totalmente inaceitáveis. Ainda podemos confiar nele?",
  ui_story_5071_50711101_67_dialog_content = "Ouvi dizer há muito tempo que ele traiu seu amigo e se rendeu a Lumópolis para alcançar seu status atual...",
  ui_story_5071_50711101_68_dialog_content = "Ele é o lendário filho demoníaco...",
  ui_story_5071_50711101_69_dialog_content = "Todas essas chamadas reformas ignoram completamente nossos interesses. Para que elas se destinam...",
  ui_story_5071_50711101_70_dialog_content = "Ele realmente quer eliminar todos nós?",
  ui_story_5071_50711101_71_dialog_content = "Estou realmente feliz em te ver novamente hoje... <color=#FFB400>Ava</color>.",
  ui_story_5071_50711101_72_dialog_content = "Mas mesmo agora eu não entendo por que você escolheria este momento para aparecer.",
  ui_story_5071_50711101_73_dialog_content = "Por um breve segundo, eu sinceramente esperava que você estivesse aqui pelos sonhos dele.",
  ui_story_5071_50711101_74_dialog_content = "Mas essa é a sua verdadeira intenção, eu vejo.",
  ui_story_5071_50711101_75_dialog_content = "Você e eu não somos iguais. Sou o único que realmente se lembra dos seus sonhos.",
  ui_story_5071_50711101_76_dialog_content = "Senhora Sheol, devemos pousar assim que a equipe de engenharia terminar a inspeção.",
  ui_story_5071_50711101_77_dialog_content = "Os Guardiões devem estar a caminho e cuidarão do resto.",
  ui_story_5071_50711101_78_dialog_content = "Mas agora só há natureza abaixo de nós.",
  ui_story_5071_50711101_79_dialog_content = "Também não estamos longe do território Eclipsita.",
  ui_story_5071_50711101_80_dialog_content = "Esse homem... pode não nos deixar sair assim.",
  ui_story_5071_50711101_81_dialog_content = "É possível que, pelo bem da reforma, ele até...",
  ui_story_5071_50711101_82_dialog_content = "Não há necessidade de temer, pessoal!",
  ui_story_5071_50711101_83_dialog_content = "Minha guilda tem uma série de aeronaves menores estacionadas por perto. Se vocês estiverem dispostos a confiar em mim, terei prazer em transportar todos vocês de volta para Umbraton.",
  ui_story_5071_50711101_84_dialog_content = "Leve-me! Eu vou com você!",
  ui_story_5071_50711101_85_dialog_content = "Nada vai acontecer ainda, pois ainda há muitas pessoas aqui, mas se continuarmos a ficar neste dirigível...",
  ui_story_5071_50711101_86_dialog_content = "Eu tenho uma família. Eu não quero morrer!",
  ui_story_5071_50711101_87_dialog_content = "*sussurra*",
  ui_story_5071_50711101_88_dialog_content = "E-eu vou com você também.",
  ui_story_5071_50711101_89_dialog_content = "Eu também!",
  ui_story_5071_50711101_90_dialog_content = "Vamos sair daqui agora. Eu não quero ficar aqui.",
  ui_story_5071_50711101_91_dialog_content = "Vamos lá, por que você está nos tratando como se fôssemos algum tipo de vilões?",
  ui_story_5071_50711101_92_dialog_content = "Vocês são os que têm nos bajulado todo esse tempo—",
  ui_story_5071_50711101_93_dialog_content = "Ei, vocês também podem estar em apuros se continuarem seguindo ela.",
  ui_story_5071_50711101_94_dialog_content = "Afinal, não podemos garantir que não faremos algo semelhante se você ficar.",
  ui_story_5071_50711101_95_dialog_content = "Corram, corram!",
  ui_story_5071_50711101_96_dialog_content = "Deixe-os ir.",
  ui_story_5071_50711101_97_dialog_content = "Acredito que a senhorita Hanstie tem seu próprio plano.",
  ui_story_5071_50711101_98_dialog_content = "E para esse fim, ela definitivamente não vai prejudicar sua preciosa audiência.",
  ui_story_5071_50711101_99_dialog_content = "Mas eles certamente vão atirar lama se os deixarmos ir—",
  ui_story_5071_50711101_100_dialog_content = "Siga-os em um pequeno dirigível.",
  ui_story_5071_50711101_101_dialog_content = "Apenas mantenha distância e garanta que as pessoas estão seguras.",
  ui_story_5071_50711101_102_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5071_50711101_103_dialog_content = "Parece que este dirigível realmente está condenado. Eu deveria avisar a todos vocês—",
  ui_story_5071_50711101_104_dialog_content = "Continuar ao lado daquele homem só vai colocá-lo em perigo mortal.",
  ui_story_5071_50711101_105_dialog_content = "Por favor, não fale assim sobre o Senhor Sombrio, especialmente porque ele ainda não fez nada.",
  ui_story_5071_50711101_106_dialog_content = "Ele pode se manter escondido nas sombras o tempo todo, mas eu sei sua verdadeira identidade.",
  ui_story_5071_50711101_107_dialog_content = "Ele é um homem que matou seu irmão e roubou tudo de seu pai adotivo. Não só isso, ele fez de tudo para garantir que ninguém se lembrasse deles.",
  ui_story_5071_50711101_108_dialog_content = "Um homem que abandonaria seu próprio nome, tudo por ganho pessoal.",
  ui_story_5071_50711101_109_dialog_content = "Ele não é nada além de um demônio que pisa em qualquer um entre ele e o trono que busca.",
  ui_story_5071_50711101_X109_dialog_content = "Você não é digno de segurar o <color=#FFB400>Bastão do Pastor</color>, Kade!",
  ui_story_5071_50711101_110_dialog_content = "...",
  ui_story_5071_50711101_111_dialog_content = "... Não importa o que você diga, eu ainda escolho acreditar no Shadowlord que sempre conheci.",
  ui_story_5071_50711101_112_dialog_content = "Bem colocado, mas me desculpe, Sra. Hanstie, você pode sair primeiro.",
  ui_story_5071_50711101_113_dialog_content = "Discordo. Acho que estou melhor ficando aqui.",
  ui_story_5071_50711101_114_dialog_content = "Sinto cheiro de notícias bombásticas, então também não vou sair.",
  ui_story_5071_50711101_115_dialog_content = "...",
  ui_story_5071_50711101_116_dialog_content = "Vocês vão viver para se arrepender disso, cada um de vocês.",
  ui_story_5071_50711101_117_dialog_content = "Tenho certeza que todos vocês estão cientes de sua capacidade para a tirania, então por que ignorar isso?",
  ui_story_5071_50711101_118_dialog_content = "Lamentável... Vocês todos são tão lamentáveis.",
  ui_story_5071_50711101_119_dialog_content = "Adeus, \"Sra. Hanstie.\"",
  ui_story_5071_50711101_120_dialog_content = "Bem, então você também deveria...",
  ui_story_5071_50711101_121_dialog_content = "Eu sinto inimigos!",
  ui_story_5071_50711101_122_dialog_content = "Senhora Sheol, cuidado! Esses soldados—",
  ui_story_5071_50711101_123_dialog_content = "Eles têm cúmplices! Eles—",
  ui_story_5071_50711101_124_dialog_content = "Cale a boca!",
  ui_story_5071_50711101_125_dialog_content = "Lembre-se do que o chefe disse. Não deixe sobreviventes.",
  ui_story_5071_50711101_126_dialog_content = "Isto não é bom! <size=45>Todos, preparem-se para a batalha!</size>",
  ui_story_5071_50711102_1_dialog_content = "O pessoal de segurança está todo...",
  ui_story_5071_50711102_2_dialog_content = "Parece que todos foram massacrados. *suspiro*",
  ui_story_5071_50711102_3_dialog_content = "Ainda bem que estamos deste lado...",
  ui_story_5071_50711102_4_dialog_content = "Você tá bem, chefe? Olhe pela janela, estou aqui!",
  ui_story_5071_50711102_5_dialog_content = "Enviei você para garantir que as pessoas estão seguras. O que está fazendo de volta aqui?",
  ui_story_5071_50711102_6_dialog_content = "Notei que os caras maus estavam agindo de forma suspeita e fiquei preocupado com você.",
  ui_story_5071_50711102_7_dialog_content = "Então, você tem tudo sob controle, chefe?",
  ui_story_5071_50711102_8_dialog_content = "... Venha e tire as pessoas daqui.",
  ui_story_5071_50711102_9_dialog_content = "Eu não vou mencionar PlayerName, mas por que você está ficando, Vergil?",
  ui_story_5071_50711102_10_dialog_content = "Huh? Este é o seu navio, não é, chefe?",
  ui_story_5071_50711102_11_dialog_content = "Qual é o problema? Ainda estou trabalhando, então devo estar no meu melhor comportamento, certo?",
  ui_story_5071_50711102_12_dialog_content = "...",
  ui_story_5071_50711102_13_dialog_content = "Acabei de ler aqueles manuscritos, Senhor das Sombras.",
  ui_story_5071_50711102_14_dialog_content = "A história escrita neles é muito parecida com a sua, mas ainda não acredito nisso.",
  ui_story_5071_50711102_15_dialog_content = "Então eu preciso perguntar, você realmente fez todas essas coisas? Para a Senhora Melissa—",
  ui_story_5071_50711102_16_dialog_content = "PlayerName!",
  ui_story_5071_50711102_17_dialog_content = "É errado da sua parte me ignorar e responsabilizar a parte culpada.",
  ui_story_5071_50711102_18_dialog_content = "S-Desculpe...",
  ui_story_5071_50711102_19_dialog_content = "Embora agora não seja a hora de discutir isso.",
  ui_story_5071_50711102_20_dialog_content = "Ainda estamos no dirigível, e temos que lidar com a falha primeiro.",
  ui_story_5071_50711102_21_dialog_content = "Quando isso acabar, pode apostar que vou receber meu troco com juros.",
  ui_story_5071_50711102_22_dialog_content = "Eu vou esperar por você.",
  ui_story_5071_50711102_23_dialog_content = "Aliás, você é uma pessoa generosa, não é, Senhor Sombrio?",
  ui_story_5071_50711102_24_dialog_content = "Obviamente, você se esforçou muito e fez muitos favores para eles.",
  ui_story_5071_50711102_25_dialog_content = "Apenas para eles te abandonarem e correrem ao menor estímulo.",
  ui_story_5071_50711102_26_dialog_content = "Ei! Por que você também está sendo enigmática, Senhora Sheol?",
  ui_story_5071_50711102_27_dialog_content = "Parem agora! Este não é o momento para estarmos lutando uns contra os outros. Precisamos nos unir.",
  ui_story_5071_50711102_28_dialog_content = "Eu adoraria entrevistar o Senhor Sombrio agora, mas não sinto que o momento é o certo...",
  ui_story_5071_50711102_29_dialog_content = "Senhor das Sombras, o que devemos fazer agora?",
  ui_story_5071_50711102_30_dialog_content = "Agradeço a todos vocês por manterem a fé em mim.",
  ui_story_5071_50711102_31_dialog_content = "Meu povo vai te retornar em segurança ao chão.",
  ui_story_5071_50711102_32_dialog_content = "Seleucid, envie dirigíveis para evacuar os passageiros.",
  ui_story_5071_50711102_33_dialog_content = "Essas sombras do passado estão atrás de mim.",
  ui_story_5071_50711102_34_dialog_content = "Você irá escoltar os passageiros para fora deste navio.",
  ui_story_5071_50711102_35_dialog_content = "Chefe...",
  ui_story_5071_50711102_36_dialog_content = "Isso é uma ordem.",
  ui_story_5071_50711102_37_dialog_content = "Entendo...",
  ui_story_5071_50711102_38_dialog_content = "Este é o Bethel. Entre.",
  ui_story_5071_50711102_39_dialog_content = "Pai, avistamos suspeitos na estrada de carga para Twin Pavilions Bay.",
  ui_story_5071_50711102_40_dialog_content = "Eles estavam enviando armas e mercenários para Umbraton e foram detidos.",
  ui_story_5071_50711102_41_dialog_content = "Como está indo do seu lado? O lançamento da donzela ocorreu sem problemas?",
  ui_story_5071_50711102_42_dialog_content = "Está tudo bem por aqui, sem preocupações.",
  ui_story_5071_50711102_43_dialog_content = "Bethel, nossos \"convidados\" travessos provavelmente aparecerão de volta em casa.",
  ui_story_5071_50711102_44_dialog_content = "Como anfitrião, confio que você saiba como cumprimentá-los.",
  ui_story_5071_50711102_45_dialog_content = "Entendido. Por favor, tome cuidado, pai.",
  ui_story_5071_50711102_46_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5071_50711102_47_dialog_content = "Isso é ruim... O dirigível ainda não recuperou seu equilíbrio.",
  ui_story_5071_50711102_48_dialog_content = "Todo o navio está tremendo, e parece que estamos perdendo impulso...",
  ui_story_5071_50711102_49_dialog_content = "Você é um piloto experiente de Colossus, então por favor não me assuste assim, querido.",
  ui_story_5071_50711102_50_dialog_content = "Isso não deveria estar acontecendo se os reparos já estiverem concluídos.",
  ui_story_5071_50711102_51_dialog_content = "Se a condição da aeronave continuar piorando, vamos continuar perdendo altitude... e vamos colidir com Umbraton!",
  ui_story_5071_50711102_52_dialog_content = "Senhora Sheol! Senhora Sheol! Notícias terríveis—",
  ui_story_5071_50711102_53_dialog_content = "Encontramos nossa equipe de engenharia lá embaixo. Todos eles foram...",
  ui_story_5071_50711102_54_dialog_content = "O quê?",
  ui_story_5071_50711201_1_dialog_content = "Ah não, temos que ir para a sala de controle principal agora.",
  ui_story_5071_50711201_2_dialog_content = "Os pilotos ainda estão lá dentro!",
  ui_story_5071_50711201_3_dialog_content = "Isso é-",
  ui_story_5071_50711201_4_dialog_content = "Chegamos tarde demais. Os pilotos estão todos... e os painéis de controle estão destruídos.",
  ui_story_5071_50711201_5_dialog_content = "Isso está indo longe demais...",
  ui_story_5071_50711201_6_dialog_content = "Devemos pensar em uma maneira de virar essa aeronave.",
  ui_story_5071_50711201_7_dialog_content = "Um passo atrás novamente...",
  ui_story_5071_50711201_8_dialog_content = "...",
  ui_story_5071_50711201_9_dialog_content = "Espera, o que é isso?",
  ui_story_5071_50711201_10_dialog_content = "Você realmente fez parecer com Soroz aqui?",
  ui_story_5071_50711201_11_dialog_content = "Eu pensei que você estava apenas brincando naquele momento...",
  ui_story_5071_50711201_12_dialog_content = "Se você vier à cerimônia como meu convidado especial de honra...",
  ui_story_5071_50711201_13_dialog_content = "Vou fazer a sala de controle ser uma duplicata da do Colossus!",
  ui_story_5071_50711201_14_dialog_content = "Então, você está vindo?",
  ui_story_5071_50711201_X11_dialog_content = "Não é difícil para mim de jeito nenhum.",
  ui_story_5071_50711201_15_dialog_content = "Claro, você é o principal truque na promoção, afinal.",
  ui_story_5071_50711201_16_dialog_content = "Então, talvez eu possa pilotá-lo?",
  ui_story_5071_50711201_17_dialog_content = "Isso é verdade! Você é o especialista, então faça o que quiser.",
  ui_story_5071_50711201_18_dialog_content = "Eu só preciso começar a jogar, e deveria funcionar como de costume—",
  ui_story_5071_50711201_19_dialog_content = "Hã—",
  ui_story_5071_50711201_20_dialog_content = "Não há resposta!",
  ui_story_5071_50711201_21_dialog_content = "Esses sistemas de controle são completamente diferentes dos que estão no Soroz!",
  ui_story_5071_50711201_X21_dialog_content = "Não tenho ideia de como consertar isso.",
  ui_story_5071_50711201_X22_dialog_content = "Verdade, o painel não é de origem celestita, mas uma antiga antiguidade que comprei.",
  ui_story_5071_50711201_22_dialog_content = "Eles também estão presos.",
  ui_story_5071_50711201_23_dialog_content = "Isso é porque é apenas um truque... Não funciona, eu vejo.",
  ui_story_5071_50711201_24_dialog_content = "Mas como...",
  ui_story_5071_50711201_25_dialog_content = "Antiguidade, você disse?",
  ui_story_5071_50711201_26_dialog_content = "E eu já vi esse tipo de painel de controle antigo antes, pessoal!",
  ui_story_5071_50711201_27_dialog_content = "Você sabe como funciona? Consegue consertar?",
  ui_story_5071_50711201_28_dialog_content = "Dê-me algum tempo e eu deveria ser capaz de restaurá-lo.",
  ui_story_5071_50711201_29_dialog_content = "Ainda temos tempo?",
  ui_story_5071_50711201_30_dialog_content = "Parece que estamos caindo cada vez mais rápido.",
  ui_story_5071_50711201_31_dialog_content = "Espere! Se este dirigível realmente é uma réplica do Colosso, então sua estrutura...",
  ui_story_5071_50711201_32_dialog_content = "Eu tenho uma ideia, todos!",
  ui_story_5071_50711201_33_dialog_content = "Se conseguirmos ajustar a orientação das asas de fora, deveríamos ser capazes de diminuir nossa descida e fazer um pouso de emergência.",
  ui_story_5071_50711201_34_dialog_content = "O que deveríamos fazer?",
  ui_story_5071_50711201_35_dialog_content = "Por favor, venha comigo!",
  ui_story_5071_50711201_36_dialog_content = "Pegue isso, PlayerName!",
  ui_story_5071_50711201_37_dialog_content = "É um manual resumido para apresentá-lo aos esquemas do navio.",
  ui_story_5071_50711201_38_dialog_content = "Ficarei aqui para proteger Vergil e deixarei o navio com você.",
  ui_story_5071_50711201_39_dialog_content = "Vamos.",
  ui_story_5071_50711201_40_dialog_content = "Espere, há mais um problema... As asas do dirigível estão expostas. Vamos precisar de um ônibus para chegar perto!",
  ui_story_5071_50711201_41_dialog_content = "Vamos conferir o convés superior!",
  ui_story_5071_50711201_42_dialog_content = "PlayerName, Senhor Sombrio, por favor...",
  ui_story_5071_50711201_X42_dialog_content = "Que sorte, ainda tem um ônibus espacial sobrando!",
  ui_story_5071_50711201_44_dialog_content = "Vejo que Seleucid deixou um para trás.",
  ui_story_5071_50711201_45_dialog_content = "Levante-se e me diga o que fazer.",
  ui_story_5071_50711201_46_dialog_content = "Deixe-me dar uma olhada primeiro nos esquemas estruturais... Pronto!",
  ui_story_5071_50711201_47_dialog_content = "Tanto as aeronaves quanto os Colossus têm asas. Embora suas estruturas sejam diferentes, a lógica por trás delas é exatamente a mesma.",
  ui_story_5071_50711201_48_dialog_content = "Ao ajustar a junta logo atrás da asa, podemos alterar a trajetória do navio e fazê-lo virar.",
  ui_story_5071_50711201_49_dialog_content = "Espere!",
  ui_story_5071_50711201_50_dialog_content = "Ah...",
  ui_story_5071_50711201_51_dialog_content = "É esta a \"asa\" que você estava falando?",
  ui_story_5071_50711201_52_dialog_content = "Haha, com certeza é maior do que precisa ser.",
  ui_story_5071_50711201_53_dialog_content = "Tem certeza de que pode mudar a direção?",
  ui_story_5071_50711201_54_dialog_content = "Tente nos voar um pouco mais perto para que eu possa dar uma olhada mais de perto no mecanismo, Senhor Sombrio!",
  ui_story_5071_50711201_55_dialog_content = "Isso é-",
  ui_story_5071_50711201_56_dialog_content = "Oh não, este mecanismo é muito mais rudimentar do que os da Colossus!",
  ui_story_5071_50711201_57_dialog_content = "Para criar asas que poderiam ser alimentadas por energia, eles abandonaram o design original. Essas asas não podem ser ajustadas manualmente de forma alguma...",
  ui_story_5071_50711201_58_dialog_content = "Haha! Despreocupado e aspirante, agora este é o <color=#FFB400>sonho</color> que todo jovem deveria ter!",
  ui_story_5071_50711201_59_dialog_content = "Compreensível—",
  ui_story_5071_50711201_60_dialog_content = "As asas que carregam um sonho não cederão facilmente!",
  ui_story_5071_50711201_61_dialog_content = "Não chegue mais perto, ou seremos sugados—",
  ui_story_5071_50711201_62_dialog_content = "Como vou mudar de direção sem me aproximar?",
  ui_story_5071_50711201_63_dialog_content = "Senhor das Sombras?",
  ui_story_5071_50711201_64_dialog_content = "Você, assuma a pilotagem.",
  ui_story_5071_50711201_65_dialog_content = "Ugh!",
  ui_story_5071_50711201_66_dialog_content = "Você está sendo muito imprudente! Se você enfiar a mão naquelas engrenagens gigantes, você vai—",
  ui_story_5071_50711201_67_dialog_content = "Diga-me para qual lado virar, PlayerName!",
  ui_story_5071_50711201_68_dialog_content = "Ei, você—",
  ui_story_5071_50711201_69_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5071_50711201_70_dialog_content = "(Inacreditável! O Senhor Sombrio está de alguma forma suportando o peso de toda a asa...)",
  ui_story_5071_50711201_71_dialog_content = "Para a sua esquerda! Gire esse mecanismo e ele moverá o resto da asa!",
  ui_story_5071_50711201_72_dialog_content = "Hyaaaah!",
  ui_story_5071_50711201_73_dialog_content = "Tente não—cair—com tanta pressa!",
  ui_story_5071_50711201_74_dialog_content = "Ranger—Ranger—",
  ui_story_5071_50711201_75_dialog_content = "(Está se movendo - aquela asa gigantesca está realmente se movendo!)",
  ui_story_5071_50711201_76_dialog_content = "Você conseguiu, Senhor Sombrio! Estamos mudando de curso!",
  ui_story_5071_50711201_77_dialog_content = "Ainda não é suficiente—",
  ui_story_5071_50711201_78_dialog_content = "Preciso tirá-lo de Umbraton—",
  ui_story_5071_50711201_79_dialog_content = "Andando.",
  ui_story_5071_50711201_80_dialog_content = "Estrondo-",
  ui_story_5071_50711201_81_dialog_content = "Ah não! O motor traseiro explodiu!",
  ui_story_5071_50711201_82_dialog_content = "(Nesse ritmo, não conseguiremos mudar completamente de direção antes de bater!)",
  ui_story_5071_50711201_83_dialog_content = "Não é suficiente. Ainda vai colidir na borda de Umbraton...",
  ui_story_5071_50711201_84_dialog_content = "Volte, Senhor das Sombras! Qualquer coisa a mais e você—",
  ui_story_5071_50711201_85_dialog_content = "Levante-se contra o vento!",
  ui_story_5071_50711201_86_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5071_50711201_87_dialog_content = "F-Fogos de artifício?",
  ui_story_5071_50711201_88_dialog_content = "Quem diabos está soltando fogos de artifício no dirigível agora...",
  ui_story_5071_50711201_89_dialog_content = "Ei, olha aquilo!",
  ui_story_5071_50711201_90_dialog_content = "O dirigível da Guilda Cloudrover está voando para cá!",
  ui_story_5071_50711201_91_dialog_content = "Esta é uma das celebrações para o voo inaugural... Eu só não esperava que fosse tão perto de nós!",
  ui_story_5071_50711201_92_dialog_content = "Que fogos de artifício maravilhosos! Aquele dirigível também é realmente espetacular.",
  ui_story_5071_50711201_93_dialog_content = "A Senhora Sheol deve querer que nós também aproveitemos o evento!",
  ui_story_5071_50711201_94_dialog_content = "Ei, seus idiotas! Por que estão parados aí?",
  ui_story_5071_50711201_95_dialog_content = "Apresse-se e saia daqui! O dirigível está prestes a cair!",
  ui_story_5071_50711201_96_dialog_content = "Por que a Gangue Istvan é tão ameaçadora?",
  ui_story_5071_50711201_97_dialog_content = "Corra! Ouvi dizer que o Shadowlord começou um banho de sangue e eliminou todos na aeronave!",
  ui_story_5071_50711201_98_dialog_content = "Eles querem derrubar o Dirigível Cloudrover em nossas favelas!",
  ui_story_5071_50711201_99_dialog_content = "Siga-nos! Precisamos buscar abrigo fora da cidade—",
  ui_story_5071_50711201_100_dialog_content = "Fique longe de nós! Não te ofendemos de forma alguma!",
  ui_story_5071_50711201_101_dialog_content = "Vamos começar a atacar se você se aproximar mais!",
  ui_story_5071_50711201_102_dialog_content = "Por que você está tão paranóico conosco? Ei, pare de jogar pedras nas pessoas!",
  ui_story_5071_50711201_103_dialog_content = "A Gangue Istvan está atacando civis!",
  ui_story_5071_50711201_104_dialog_content = "<size=45>Ei!</size>",
  ui_story_5071_50711201_105_dialog_content = "Acalmem-se, todos... Ataquem-nos mais uma vez e não teremos escolha senão retaliar.",
  ui_story_5071_50711201_106_dialog_content = "Por que esses idiotas de repente...",
  ui_story_5071_50711201_107_dialog_content = "Deve ser a mulher que tentou causar confusão no dirigível!",
  ui_story_5071_50711201_108_dialog_content = "Pare aí mesmo!",
  ui_story_5071_50711201_109_dialog_content = "*suspiro* Imprudente como sempre, vejo. Isso não será fácil de lidar agora.",
  ui_story_5071_50711201_110_dialog_content = "Isso é-",
  ui_story_5071_50711201_111_dialog_content = "O dirigível está mudando de direção?",
  ui_story_5071_50711201_112_dialog_content = "Parece que eles consertaram o painel de controle.",
  ui_story_5071_50711201_113_dialog_content = "Vamos voltar.",
  ui_story_5071_50711201_114_dialog_content = "Espere um pouco.",
  ui_story_5071_50711201_115_dialog_content = "Este botão aciona os fogos de artifício, este é para transmissão, e este é...",
  ui_story_5071_50711201_116_dialog_content = "Vergil! Você realmente conseguiu consertar o painel de controle?",
  ui_story_5071_50711201_117_dialog_content = "Na verdade não. Os controles direcionais estão funcionando novamente, mas ainda não conseguimos recuperar a altitude.",
  ui_story_5071_50711201_118_dialog_content = "Ah... Isso provavelmente é porque um dos motores explodiu...",
  ui_story_5071_50711201_119_dialog_content = "Ainda vai cair por aqui...",
  ui_story_5071_50711201_120_dialog_content = "Se mirarmos corretamente e pousarmos no Rio do Ouro, talvez a aeronave possa permanecer intacta.",
  ui_story_5071_50711201_121_dialog_content = "Para qual direção devo voar, Senhora Sheol? Em direção ao rio?",
  ui_story_5071_50711201_122_dialog_content = "Mas as pessoas em ambos os lados do rio não sofrerão?",
  ui_story_5071_50711201_123_dialog_content = "Vamos mover para o vale. Ninguém mora lá.",
  ui_story_5071_50711201_124_dialog_content = "Mas se eu fizer isso, esta aeronave será reduzida a um monte de sucata.",
  ui_story_5071_50711201_125_dialog_content = "É tudo minha culpa que a sua aeronave...",
  ui_story_5071_50711201_126_dialog_content = "O que você está dizendo, Senhor das Sombras? Você faz parecer que é o mentor por trás de tudo isso.",
  ui_story_5071_50711201_127_dialog_content = "...",
  ui_story_5071_50711201_128_dialog_content = "Explique-me como voar com isso e vocês podem ir embora.",
  ui_story_5071_50711201_129_dialog_content = "Senhora Sheol?",
  ui_story_5071_50711201_130_dialog_content = "Alguém tem que pilotar essa coisa, certo? Sem mencionar que é minha.",
  ui_story_5071_50711201_131_dialog_content = "Então vocês deveriam—",
  ui_story_5071_50711201_132_dialog_content = "Saia e deixe-me pilotar.",
  ui_story_5071_50711201_133_dialog_content = "Senhor das Sombras?",
  ui_story_5071_50711201_134_dialog_content = "O que você está fazendo—",
  ui_story_5071_50711201_135_dialog_content = "Pare de tentar fazer o trabalho de outras pessoas, Senhora Sheol.",
  ui_story_5071_50711201_136_dialog_content = "Sem mencionar que eu já tenho experiência com isso.",
  ui_story_5071_50711201_137_dialog_content = "Saia. Aqueles que ansiavam por voar não deveriam ter seus sonhos despedaçados no céu.",
  ui_story_5071_50711201_138_dialog_content = "Senhor das Sombras...",
  ui_story_5071_50711201_139_dialog_content = "Pegue as duas crianças e retorne em segurança.",
  ui_story_5071_50711201_140_dialog_content = "... Você ainda se lembra do favor que me deve?",
  ui_story_5071_50711201_141_dialog_content = "Eu não esqueço minhas promessas.",
  ui_story_5071_50711201_142_dialog_content = "Bom. Vou mantê-los seguros.",
  ui_story_5071_50711201_143_dialog_content = "Em troca, espero que você cumpra sua promessa e atenda ao meu pedido.",
  ui_story_5071_50711201_144_dialog_content = "Meu desejo é ficar vivo, simples assim.",
  ui_story_5071_50711201_145_dialog_content = "... Eu prometo.",
  ui_story_5071_50711201_146_dialog_content = "Não vamos perder mais tempo. Vamos!",
  ui_story_5071_50711201_147_dialog_content = "May a Sombra vigia você.",
  ui_story_5071_50711201_148_dialog_content = "<color=#FFB400>Valon</color>, velha amizade... Vamos investir mais neste sonho...",
  ui_story_5071_50711202_1_dialog_content = "Você finalmente voltou, Sr. Borriman.",
  ui_story_5071_50711202_2_dialog_content = "Não acho que uma apresentação seja necessária.",
  ui_story_5071_50711202_3_dialog_content = "S-Senhora Bethel? Ah, por que você veio de repente?",
  ui_story_5071_50711202_4_dialog_content = "Você nem nos avisou—",
  ui_story_5071_50711202_5_dialog_content = "Eu peguei uma banda de mercenários armados fora da cidade. Eles estavam tentando invadir Umbraton.",
  ui_story_5071_50711202_6_dialog_content = "Julgando pelos seus veículos, pessoal de apoio e este testemunho...",
  ui_story_5071_50711202_7_dialog_content = "Suspeitamos da sua Guilda do Pantera Vermelha, da Guilda do Papagaio Cinza e da Gangue do Falcão Ferrugem...",
  ui_story_5071_50711202_8_dialog_content = "... estão entre os três cúmplices mínimos neste incidente.",
  ui_story_5071_50711202_9_dialog_content = "Aqui está a prova fotográfica de você traficando armas ilegalmente.",
  ui_story_5071_50711202_10_dialog_content = "Gostaria que você viesse conosco sob o Regulamento de Segurança de Umbraton.",
  ui_story_5071_50711202_11_dialog_content = "E-Espere um segundo. Deve ter havido algum tipo de mal-entendido.",
  ui_story_5071_50711202_12_dialog_content = "Você não pode me levar embora assim!",
  ui_story_5071_50711202_13_dialog_content = "Só mais uma hora. Não! Talvez até mais meia hora ou algo assim...",
  ui_story_5071_50711202_14_dialog_content = "Como assim?",
  ui_story_5071_50711202_15_dialog_content = "É como se você tivesse algo planejado...",
  ui_story_5071_50711202_16_dialog_content = "<size=45>Ah!</size>",
  ui_story_5071_50711202_17_dialog_content = "O que está acontecendo lá fora?",
  ui_story_5071_50711202_18_dialog_content = "Por que há caos por toda parte?",
  ui_story_5071_50711202_19_dialog_content = "Leve-o sob custódia.",
  ui_story_5071_50711202_20_dialog_content = "Sim, senhora!",
  ui_story_5071_50711202_21_dialog_content = "Bethel para a guilda. O que está acontecendo?",
  ui_story_5071_50711202_22_dialog_content = "Senhora Bethel, você voltou!",
  ui_story_5071_50711202_23_dialog_content = "O Senhor das Sombras é...",
  ui_story_5071_50711202_24_dialog_content = "Acalme-se. O que aconteceu com meu pai? Me conte!",
  ui_story_5071_50711202_25_dialog_content = "O dirigível em que a Senhora Sheol e ele estão está prestes a cair!",
  ui_story_5071_50711202_26_dialog_content = "O quê?",
  ui_story_5071_50711202_27_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5071_50711202_28_dialog_content = "Isso é... o som do dirigível caindo?",
  ui_story_5071_50711202_29_dialog_content = "Senhora Bethel, o que deveríamos fazer?",
  ui_story_5071_50711202_30_dialog_content = "A coisa que caiu da aeronave parece ter pousado na cidade.",
  ui_story_5071_50711202_31_dialog_content = "Alguém está se escondendo entre as pessoas na cidade e incitando um motim. Enquanto isso, muitos mercenários fora da cidade estão...",
  ui_story_5071_50711202_32_dialog_content = "Seleucid gostaria que nós ajudássemos o Senhor Sombrio, mas sem a sua aprovação—",
  ui_story_5071_50711202_33_dialog_content = "Pai…",
  ui_story_5071_50711202_34_dialog_content = "Entendi.",
  ui_story_5071_50711202_35_dialog_content = "Ele me mandou embora porque sentiu um perigo iminente.",
  ui_story_5071_50711202_36_dialog_content = "Senhora Betel?",
  ui_story_5071_50711202_37_dialog_content = "Acalme-se, acho que nada vai acontecer com o Senhor Sombrio.",
  ui_story_5071_50711202_38_dialog_content = "Além disso, dê minha ordem a todos na guilda.",
  ui_story_5071_50711202_39_dialog_content = "Sim, senhora!",
  ui_story_5071_50711202_40_dialog_content = "Alguém está de olho em Umbraton. Não podemos entrar em pânico e dar a eles uma abertura.",
  ui_story_5071_50711202_41_dialog_content = "Vou entregar a lista e a prova aos Guardiões. Envie Kleken para a sede deles—",
  ui_story_5071_50711202_42_dialog_content = "Diga a ele para ajudar os Guardiões a prender os culpados e estar alerta, pois eles aproveitarão a oportunidade para fugir ou resistir.",
  ui_story_5071_50711202_43_dialog_content = "Sim, senhora!",
  ui_story_5071_50711202_44_dialog_content = "Diga ao Seleucid para reunir as unidades de combate dos Guardiões e enviar metade para defender os arredores.",
  ui_story_5071_50711202_45_dialog_content = "Chame Patty e Patsy. Envie-os para me ajudar com o caos na cidade.",
  ui_story_5071_50711202_46_dialog_content = "Além disso, envie o reforço principal para ajudar os residentes. Em seguida, envie duas unidades para procurar o Shadowlord!",
  ui_story_5071_50711202_47_dialog_content = "Antes que ele retorne, devemos manter a ordem e defender este lugar em seu nome, entendeu?",
  ui_story_5071_50711202_48_dialog_content = "Sim, Senhora Bethel!",
  ui_story_5071_50711202_49_dialog_content = "Eu acredito em você, pai, para ser seu eu habitual...",
  ui_story_5071_50711202_50_dialog_content = "E faça outro <color=#FFB400>retorno dourado</color>!",
  ui_story_5071_50711301_1_dialog_content = "Uma aeronave tão bonita... se foi assim...",
  ui_story_5071_50711301_2_dialog_content = "O Senhor das Sombras conseguiu! Ele caiu em uma parte vazia da selva—",
  ui_story_5071_50711301_3_dialog_content = "Aproxime-se antes de pousar, querido.",
  ui_story_5071_50711301_4_dialog_content = "Estávamos no ar, mas agora...",
  ui_story_5071_50711301_5_dialog_content = "Os sonhos das pessoas em Umbraton nunca duram. Não há nada que você possa fazer sobre isso.",
  ui_story_5071_50711301_6_dialog_content = "O fogo é tão violento... Não sobrou nada, exceto restos queimados...",
  ui_story_5071_50711301_7_dialog_content = "Nada é poupado, nem mesmo as preciosas obras de arte... O-O que faremos agora, Senhora Sheol?",
  ui_story_5071_50711301_8_dialog_content = "Não me importo tanto com a minha coleção pessoal quanto com os itens de leilão dos clientes, alguns dos quais nem podem ser reproduzidos... Vou ter que pagar por eles do meu próprio bolso.",
  ui_story_5071_50711301_9_dialog_content = "Senhora Sheol...",
  ui_story_5071_50711301_10_dialog_content = "Estou bem, querida. Nos negócios, às vezes se ganha, às vezes se perde.",
  ui_story_5071_50711301_11_dialog_content = "E eu ainda não estou totalmente no vermelho. Vamos procurar o Shadowlord.",
  ui_story_5071_50711301_12_dialog_content = "E-Está tão quente... O Senhor das Sombras realmente poderia ter sobrevivido a algo assim?",
  ui_story_5071_50711301_13_dialog_content = "Espreitar em lugares invisíveis é o que a Sombra faz de melhor. Ele deve estar vivo.",
  ui_story_5071_50711301_14_dialog_content = "Cuidado, Senhora Sheol! As chamas estão muito fortes por lá!",
  ui_story_5071_50711301_15_dialog_content = "(Ainda nada... Não consigo sentir a presença do Senhor Sombrio em lugar nenhum.)",
  ui_story_5071_50711301_16_dialog_content = "Senhor das Sombras? Senhor das Sombras?",
  ui_story_5071_50711301_17_dialog_content = "Você está com dificuldade de ouvir por causa da idade avançada? Pare de brincar.",
  ui_story_5071_50711301_18_dialog_content = "(O que vai acontecer com Umbraton? E Bethel... O que eu deveria dizer a ela...)",
  ui_story_5071_50711301_19_dialog_content = "Isso não vai funcionar, Senhora Sheol! Por favor, saia antes que tudo pegue fogo...",
  ui_story_5071_50711301_20_dialog_content = "Ele ainda tem dívidas para acertar comigo. Seu crédito é bom demais para desistir!",
  ui_story_5071_50711301_21_dialog_content = "Mas Senhora Sheol...",
  ui_story_5071_50711301_22_dialog_content = "Eu não entendo... O Senhor Sombrio é uma boa pessoa, ou uma má?",
  ui_story_5071_50711301_23_dialog_content = "Vergil...",
  ui_story_5071_50711301_24_dialog_content = "Nunca é apenas preto ou branco para os adultos.",
  ui_story_5071_50711301_25_dialog_content = "Mas ele se arriscou para nos salvar - isso é um fato incontestável.",
  ui_story_5071_50711301_26_dialog_content = "Mas o incêndio... Temos que conseguir alguém para apagar o fogo.",
  ui_story_5071_50711301_27_dialog_content = "Devemos contar para Bethel?",
  ui_story_5071_50711301_28_dialog_content = "*suspiro* Bethel deve ser informado disso.",
  ui_story_5071_50711301_29_dialog_content = "Especialmente quando eu senti o cheiro de conspiração em tudo isso.",
  ui_story_5071_50711301_30_dialog_content = "A Sra. Yvonne provavelmente morreu de veneno, e os Guardas Lumo nos atacaram no navio...",
  ui_story_5071_50711301_31_dialog_content = "O mentor não estava me visando, mas sim Umbraton - ou mais especificamente, o Shadowlord.",
  ui_story_5071_50711301_32_dialog_content = "O Senhor Sombrio mencionou \"Sombras do passado\". Talvez ele tenha descoberto quem está por trás disso?",
  ui_story_5071_50711301_33_dialog_content = "Sombra do passado? Então acredito que a Srta. Hanstie tem algo a dizer sobre isso.",
  ui_story_5071_50711301_34_dialog_content = "Espera, tem alguém vindo!",
  ui_story_5071_50711301_35_dialog_content = "Piu—Piu—",
  ui_story_5071_50711301_36_dialog_content = "Isso é... uma coruja?",
  ui_story_5071_50711301_37_dialog_content = "Bom, você os encontrou. Volte para mim agora.",
  ui_story_5071_50711301_38_dialog_content = "Piu—Piu—",
  ui_story_5071_50711301_39_dialog_content = "Você é... Sra. Hanstie?",
  ui_story_5071_50711301_40_dialog_content = "(Essa coruja... Algo parece muito familiar nela...)",
  ui_story_5071_50711301_41_dialog_content = "Não acredito que este é o lugar... Havia um Pit impressionante aqui há muito tempo.",
  ui_story_5071_50711301_42_dialog_content = "É também o lugar onde aquele traidor matou seu irmão.",
  ui_story_5071_50711301_43_dialog_content = "!",
  ui_story_5071_50711301_44_dialog_content = "Poderia ser isso o destino? Estou ao seu lado mais uma vez, Valon.",
  ui_story_5071_50711301_45_dialog_content = "E aquele traidor conseguiu fazer um pouso forçado neste lugar também!",
  ui_story_5071_50711301_46_dialog_content = "Parece que nem mesmo Umbraton vai salvá-lo desta última retribuição que ele merece!",
  ui_story_5071_50711301_47_dialog_content = "Não vou mais precisar sujar minhas mãos...",
  ui_story_5071_50711301_48_dialog_content = "Ei... Hehehe.",
  ui_story_5071_50711301_49_dialog_content = "Eu sabia. Você é a \"sombra do passado\" do Senhor das Sombras, não é, Sra. Hanstie?",
  ui_story_5071_50711301_50_dialog_content = "O que diabos aconteceu naquela época? Este lugar...",
  ui_story_5071_50711301_51_dialog_content = "A explicação daquele escritor não foi clara o suficiente para você?",
  ui_story_5071_50711301_52_dialog_content = "\"Com sangue frio, o traidor conhecido como Kade assassinou Valon, seu irmão mais querido. Ao fazer isso, ele o roubou de tudo que era e traiu Umbraton.\"",
  ui_story_5071_50711301_53_dialog_content = "Como parte do passado que ele procurou erradicar, fui forçado a viver fora da cidade todos esses anos.",
  ui_story_5071_50711301_54_dialog_content = "Sofri humilhações indescritíveis enquanto lutava para chegar ao topo do mundo dos negócios, tudo para que eu pudesse voltar à minha cidade natal um dia—",
  ui_story_5071_50711301_55_dialog_content = "E arrancar a máscara daquele traidor com minhas próprias mãos!",
  ui_story_5071_50711301_56_dialog_content = "Ele não é digno do sobrenome de Valon! Ele não merece se chamar \"Istvan\"!",
  ui_story_5071_50711301_57_dialog_content = "Desculpe interromper—",
  ui_story_5071_50711301_58_dialog_content = "As coisas estavam tão loucas antes que eu não tive a chance de falar...",
  ui_story_5071_50711301_59_dialog_content = "Eu tenho me perguntado sobre algo todo esse tempo. A Sra. Yvonne realmente escreveu aqueles manuscritos que vimos com sua própria mão?",
  ui_story_5071_50711301_60_dialog_content = "O que você está dizendo, Vergílio?",
  ui_story_5071_50711301_61_dialog_content = "A Sra. Yvonne era muito apaixonada por escrita, e sua caligrafia reflete isso. Sua caligrafia é geralmente muito livre, e cada palavra é escrita com muito pouca preocupação com a estética.",
  ui_story_5071_50711301_62_dialog_content = "Mas os últimos manuscritos foram escritos meticulosamente, e a tinta era muito mais escura. Não só isso, a forma e a intenção por trás das palavras eram completamente diferentes.",
  ui_story_5071_50711301_63_dialog_content = "Havia... um certo nível de artesanato neles.",
  ui_story_5071_50711301_64_dialog_content = "Havia também um aroma suave persistindo nas páginas daqueles manuscritos.",
  ui_story_5071_50711301_65_dialog_content = "... Essas pistas me dizem que foram obra de \"A\", o mestre falsificador.",
  ui_story_5071_50711301_66_dialog_content = "Um aroma...",
  ui_story_5071_50711301_67_dialog_content = "Cheira a <color=#FFB400>lírios</color>!",
  ui_story_5071_50711301_68_dialog_content = "\"Adoro como você a retrata: misteriosa, forte, desinibida.\"",
  ui_story_5071_50711301_69_dialog_content = "\"Minha admiração por ela como guardiã silenciosa é a razão pela qual eu amo tanto os lírios.\"",
  ui_story_5071_50711301_70_dialog_content = "\"Lembranças eternas, amor intransponível e bênçãos profundas. Isso é o que os lírios simbolizam.\"",
  ui_story_5071_50711301_71_dialog_content = "Srta. Hanstie...",
  ui_story_5071_50711301_72_dialog_content = "<color=#e8d9bb>A Sra. Hanstie sorri levemente, sem negar nem reconhecer nada.</color>",
  ui_story_5071_50711301_73_dialog_content = "<color=#e8d9bb>A verdade está embebida na tinta. Neste ponto, importa se foi Yvonne ou Hanstie que escreveu?</color>",
  ui_story_5071_50711301_74_dialog_content = "Todos nós usamos máscaras diferentes. Se eu sou ou não o \"A\" não tem efeito no resultado.",
  ui_story_5071_50711301_75_dialog_content = "*soluçando* Mas por que você faria isso? Eu... Eu sempre te admirei...",
  ui_story_5071_50711301_76_dialog_content = "Bem, a Sra. Yvonne mencionou que obteve a inspiração de um \"amigo artista\".",
  ui_story_5071_50711301_77_dialog_content = "Vejo que esse amigo é você.",
  ui_story_5071_50711301_78_dialog_content = "Você realmente é do tipo prático, fazendo tudo por um velho rancor.",
  ui_story_5071_50711301_79_dialog_content = "Como o dano colateral em seu esquema, gostaria de saber se você me compensaria pelo dirigível e minhas enormes perdas.",
  ui_story_5071_50711301_80_dialog_content = "Se o seu sonho roubado morrer aqui, não tenho nenhum remorso.",
  ui_story_5071_50711301_81_dialog_content = "Oh, minha querida Sra. Hanstie, isso na verdade era o meu sonho.",
  ui_story_5071_50711301_82_dialog_content = "Não é nada como as histórias exageradas que você inventou—",
  ui_story_5071_50711301_83_dialog_content = "Você tem se aproveitado começando com a forma como minha mãe morreu, não é?",
  ui_story_5071_50711301_84_dialog_content = "Talvez seja verdade—",
  ui_story_5071_50711301_85_dialog_content = "Ou talvez seja apenas boato.",
  ui_story_5071_50711301_86_dialog_content = "De qualquer forma, tais rumores não teriam sido espalhados em primeiro lugar se não houvesse nenhuma prova.",
  ui_story_5071_50711301_87_dialog_content = "Não tenho absolutamente nenhum interesse na verdade sobre a Senhora Melissa. Estou satisfeito contanto que eu possa continuar a usar os rumores sobre ela.",
  ui_story_5071_50711301_88_dialog_content = "Sim, todos vocês deveriam ser capazes de ver a verdadeira face de Kade agora.",
  ui_story_5071_50711301_89_dialog_content = "Não—",
  ui_story_5071_50711301_90_dialog_content = "Isso... Isso não faz sentido!",
  ui_story_5071_50711301_91_dialog_content = "E o que você saberia, criança?",
  ui_story_5071_50711301_92_dialog_content = "Você fala constantemente sobre mostrar às pessoas a verdade sobre o passado. Por que o passado da Senhora Mercury deveria ser diferente?",
  ui_story_5071_50711301_93_dialog_content = "Você sabe como é importante para a Senhora Sheol aprender sobre sua mãe...",
  ui_story_5071_50711301_94_dialog_content = "Mas você está apenas usando esse conhecimento como uma moeda de troca para machucar outras pessoas—",
  ui_story_5071_50711301_95_dialog_content = "Como você pode ser tão egoísta!",
  ui_story_5071_50711301_96_dialog_content = "PlayerName...",
  ui_story_5071_50711301_97_dialog_content = "Chega!",
  ui_story_5071_50711301_98_dialog_content = "Você ganha a vida fazendo produtos falsificados, mas simplesmente não consegue resistir a deixar sua própria marca neles.",
  ui_story_5071_50711301_99_dialog_content = "Para conseguir sua vingança, você recorre aos meios mais cruéis e desprezíveis—",
  ui_story_5071_50711301_100_dialog_content = "Você pode querer expor o passado do Shadowlord, mas não há um pingo de verdade por trás de suas ações.",
  ui_story_5071_50711301_101_dialog_content = "Alguém tão egoísta e arrogante quanto você só visaria o Senhor Sombrio para servir aos seus próprios interesses...",
  ui_story_5071_50711301_102_dialog_content = "Eu disse chega, seu pirralho inútil!",
  ui_story_5071_50711301_103_dialog_content = "Venha agora, isso está abaixo de você, Senhora Hanstie.",
  ui_story_5071_50711301_104_dialog_content = "Veja, você até assustou o Vergil.",
  ui_story_5071_50711301_105_dialog_content = "A Sra. Yvonne foi envenenada até a morte.",
  ui_story_5071_50711301_106_dialog_content = "Já vi um tipo similar de veneno antes...",
  ui_story_5071_50711301_107_dialog_content = "Cansei de ouvir suas palavras.",
  ui_story_5071_50711301_108_dialog_content = "Parece que não há como dissuadir vocês, teimosos tolos, deste caminho errôneo.",
  ui_story_5071_50711301_109_dialog_content = "Não tenho escolha a não ser enterrar mais alguns subordinados de Kade no local de descanso de Valon.",
  ui_story_5071_50711301_110_dialog_content = "Saiam, homens!",
  ui_story_5071_50711301_111_dialog_content = "Ficando sério agora, eu vejo.",
  ui_story_5071_50711301_112_dialog_content = "Estamos cercados...",
  ui_story_5071_50711301_113_dialog_content = "Acho que é hora de você fazer o que faz de melhor, querida.",
  ui_story_5071_50711301_114_dialog_content = "Eu só vi você navegar com os outros antes. Deixe-me experimentar isso pessoalmente hoje!",
  ui_story_5071_50711301_115_dialog_content = "Pegue o Vergílio e fique atrás de mim!",
  ui_story_5071_50711301_116_dialog_content = "Não posso me dar ao luxo de perder meu melhor cliente e funcionário.",
  ui_story_5071_50711302_1_dialog_content = "Eles estão recebendo mais reforços. Isso não é bom.",
  ui_story_5071_50711302_2_dialog_content = "Não vamos durar mesmo com você por perto, querido.",
  ui_story_5071_50711302_3_dialog_content = "Bethel e os outros devem ter notado uma confusão tão grande. Tenho certeza de que eles já estão a caminho...",
  ui_story_5071_50711302_4_dialog_content = "Receio que não possamos resistir até lá.",
  ui_story_5071_50711302_5_dialog_content = "Sou uma empresária, não uma lutadora, mas estamos sem opções...",
  ui_story_5071_50711302_6_dialog_content = "PlayerName, Vergil, vocês dois vão encontrar o Senhor das Sombras. Eu vou cuidar deles.",
  ui_story_5071_50711302_7_dialog_content = "Mas…",
  ui_story_5071_50711302_8_dialog_content = "Tenha fé nele! Nunca vi ninguém tão comprometido com suas promessas quanto ele em todos os meus anos de negócios.",
  ui_story_5071_50711302_9_dialog_content = "Por favor, acredite nele e em si mesmo, PlayerName.",
  ui_story_5071_50711302_10_dialog_content = "Só você pode encontrá-lo neste caos. Não desista!",
  ui_story_5071_50711302_11_dialog_content = "... Entendo.",
  ui_story_5071_50711302_12_dialog_content = "Vamos, Virgílio.",
  ui_story_5071_50711302_13_dialog_content = "Partindo tão cedo?",
  ui_story_5071_50711302_14_dialog_content = "Qual é a pressa, Sra. Hanstie? Ainda temos questões em aberto.",
  ui_story_5071_50711302_15_dialog_content = "É baixo mentir sobre a mãe de alguém, você sabe.",
  ui_story_5071_50711302_16_dialog_content = "Como esperado da filha da Sra. Red Mercury, seu temperamento não é diferente do dela.",
  ui_story_5071_50711302_17_dialog_content = "Embora eu a admire muito, nunca me importei com você na minha vida.",
  ui_story_5071_50711302_18_dialog_content = "Então, o que eu fiz de errado e eu deveria me desculpar?",
  ui_story_5071_50711302_19_dialog_content = "Você realmente é um tolo impudente.",
  ui_story_5071_50711302_20_dialog_content = "Você pode até saber um pouco de negócios agora, mas sua visão continua tão ruim quanto sempre.",
  ui_story_5071_50711302_21_dialog_content = "Desde a última vez, você não fez nada além de ficar no meu caminho.",
  ui_story_5071_50711302_22_dialog_content = "Última vez? Agora eu tenho que perguntar quando foi isso.",
  ui_story_5071_50711302_23_dialog_content = "... Esses foram deslizes triviais, mas seu maior pecado foi pensar que você poderia roubar descaradamente o sonho de outra pessoa.",
  ui_story_5071_50711302_24_dialog_content = "Eu sou a única pessoa que pode continuar o sonho de Valon!",
  ui_story_5071_50711302_25_dialog_content = "Você não é digno!",
  ui_story_5071_50711302_26_dialog_content = "PlayerName está certo. Você já é um líder de guilda, mas ainda é mais egocêntrico do que uma criança.",
  ui_story_5071_50711302_27_dialog_content = "Você e Kade realmente não são diferentes um do outro - não vou me segurar contra você, não importa o quanto você se pareça com sua mãe.",
  ui_story_5071_50711302_28_dialog_content = "Eu vou destruir você, junto com Kade e sua preciosa Guilda Cloudrover—",
  ui_story_5071_50711302_29_dialog_content = "Vou fazer todos vocês se espatifarem no <color=#FFB400>solo</color>!",
  ui_story_5071_50711302_30_dialog_content = "Tudo bem... Já que você já me atacou, que mal mais eu poderia fazer à minha imagem?",
  ui_story_5071_50711302_31_dialog_content = "(Senhor das Sombras... Você realmente está vivo lá fora? Se sim, onde você está?)",
  ui_story_5071_50711302_32_dialog_content = "(Ou será que a Senhora Sheol estava apenas tentando nos dar tempo para escapar?)",
  ui_story_5071_50711302_33_dialog_content = "(Por favor, deixe-me ouvir sua voz... ou então—)",
  ui_story_5071_50711302_34_dialog_content = "*tosse* A-A fumaça—está ficando muito densa—",
  ui_story_5071_50711302_35_dialog_content = "Desculpe, Vergil... Mas eu tenho que continuar procurando pelo Shadowlord. Você deveria voltar para Umbraton e pedir reforços.",
  ui_story_5071_50711302_36_dialog_content = "Não posso fazer isso. A Senhora Sheol pediu para nós dois procurarmos por ele.",
  ui_story_5071_50711302_37_dialog_content = "Ela disse que o Senhor Sombrio sempre cumpre suas promessas, então eu também acreditaria nele!",
  ui_story_5071_50711302_38_dialog_content = "Vergil... Huh?",
  ui_story_5071_50711302_39_dialog_content = "(Sinto uma mistura de emoções poderosas e caóticas, e está vindo de dentro das chamas!)",
  ui_story_5071_50711302_40_dialog_content = "Virgílio, precisamos passar por essas chamas—",
  ui_story_5071_50711302_41_dialog_content = "Ai—E-Espere por mim!",
  ui_story_5071_50711302_42_dialog_content = "(Senhor das Sombras... Se você realmente está aí, por favor diga algo—)",
  ui_story_5071_50711302_43_dialog_content = "Senhor das Sombras... Senhor das Sombras!",
  ui_story_5071_50711302_44_dialog_content = "Senhor das Sombras—",
  ui_story_5071_50711302_45_dialog_content = "PlayerName?",
  ui_story_5071_50711302_46_dialog_content = "É realmente você! Graças a Deus você está... Hã?",
  ui_story_5071_50711302_47_dialog_content = "Cuidado, atrás de você!",
  ui_story_5071_50711302_48_dialog_content = "Não—",
  ui_story_5071_50711302_49_dialog_content = "Não se preocupe, eles estão fora.",
  ui_story_5071_50711302_50_dialog_content = "Esses caras foram realmente persistentes. Eles estavam escondidos aqui o tempo todo?",
  ui_story_5071_50711302_51_dialog_content = "Não acredito que eles até te encontraram antes de nós.",
  ui_story_5071_50711302_52_dialog_content = "O desejo da Sra. Hanstie de erradicar tudo é aterrorizante. Ela está indo com tudo contra nós.",
  ui_story_5071_50711302_53_dialog_content = "Deixe ela fazer o que quiser...",
  ui_story_5071_50711302_54_dialog_content = "Senhor das Sombras?",
  ui_story_5071_50711302_55_dialog_content = "Estou me sentindo... um pouco cansado—",
  ui_story_5071_50711302_56_dialog_content = "Você parece estar com muita dor. Você está machucado?",
  ui_story_5071_50711302_57_dialog_content = "*tosse*",
  ui_story_5071_50711302_58_dialog_content = "Venha conosco! A fumaça está ficando muito densa por aqui!",
  ui_story_5071_50711302_59_dialog_content = "Não é fumaça.",
  ui_story_5071_50711302_60_dialog_content = "Não é fumaça? Então o que são esses vapores pretos?",
  ui_story_5071_50711302_61_dialog_content = "(Espera, essa névoa negra... É a mesma que o <color=#FFB400>veneno do Arte</color> de antes?)",
  ui_story_5071_50711302_62_dialog_content = "Heheh, então você finalmente descobriu?",
  ui_story_5071_50711302_63_dialog_content = "Deixei você vivo para que eventualmente pudesse ouvir sua confissão—",
  ui_story_5071_50711302_64_dialog_content = "Então pule a conversinha.",
  ui_story_5071_50711302_65_dialog_content = "Isso é apenas... a maneira da Sra. Hanstie de bater na porta.",
  ui_story_5071_50711302_66_dialog_content = "Os vapores têm persistido desde que começamos a lutar um contra o outro.",
  ui_story_5071_50711302_67_dialog_content = "Quanto mais você lutou, mais você inalou.",
  ui_story_5071_50711302_68_dialog_content = "Mesmo que a maior parte tenha sido queimada pelo fogo, não há como saber quanto você já inalou...",
  ui_story_5071_50711302_69_dialog_content = "Entregue o antídoto!",
  ui_story_5071_50711302_70_dialog_content = "Eu pensei que os Lobos Negros foram exterminados? Como vocês ainda estão produzindo este veneno?",
  ui_story_5071_50711302_71_dialog_content = "\"Veneno\"? Hahaha—Acho que você está enganado, amigo.",
  ui_story_5071_50711302_72_dialog_content = "Além disso, os Lobos Negros eram apenas um bando de vira-latas inúteis.",
  ui_story_5071_50711302_73_dialog_content = "Qual é a sua conexão com os Lobos Negros? E Arte e Hanstie...",
  ui_story_5071_50711302_74_dialog_content = "Deixa para lá, apenas nos dê o antídoto—",
  ui_story_5071_50711302_75_dialog_content = "Não se preocupe, PlayerName... Eles também inalaram a névoa.",
  ui_story_5071_50711302_76_dialog_content = "Se fosse tóxico, eles morreriam mais rápido, dado o quão fracos são.",
  ui_story_5071_50711302_77_dialog_content = "Hehe, como esperado do famoso Senhor Sombrio. Mesmo nesta condição, você ainda está perfeitamente calmo.",
  ui_story_5071_50711302_78_dialog_content = "Acho que você está prestes a chegar à parte do solilóquio onde revela a trama.",
  ui_story_5071_50711302_79_dialog_content = "Não deixe sua chance de ser ouvido escapar, palhaço desajeitado.",
  ui_story_5071_50711302_80_dialog_content = "Humph—Estávamos apenas seguindo as ordens da Sra. Hanstie, mas isso é exatamente o que todos nós queremos.",
  ui_story_5071_50711302_81_dialog_content = "Você consegue sentir agora, não é? Uma sensação de inquietação vindo do fundo de dentro - uma sensação de violência.",
  ui_story_5071_50711302_82_dialog_content = "Esse é o efeito da nossa névoa negra modificada. Ela não te mata mais - apenas te preenche de raiva e faz você ceder aos seus impulsos mais selvagens.",
  ui_story_5071_50711302_83_dialog_content = "Nessa condição, ninguém pode possivelmente suprimir seus desejos mais profundos.",
  ui_story_5071_50711302_84_dialog_content = "Não me diga que vocês—",
  ui_story_5071_50711302_85_dialog_content = "Isso mesmo! Nosso objetivo é usá-lo para liberar a fera escondida sob a máscara de Istvan!",
  ui_story_5071_50711302_86_dialog_content = "<size=50>O demônio do Abismo—Kade!</size>",
  ui_story_5071_50711302_87_dialog_content = "Vamos trazer à tona o monstro enterrado nas profundezas do seu coração!",
  ui_story_5071_50711302_88_dialog_content = "Todas essas pessoas que vêm ao seu resgate saberão exatamente quem você é!",
  ui_story_5071_50711302_89_dialog_content = "Agora mostre a eles! Mostre às pessoas que você diz amar a horrenda loucura de sua alma!",
  ui_story_5071_50711302_90_dialog_content = "Vocês... Vocês são os únicos loucos por aqui!",
  ui_story_5071_50711302_91_dialog_content = "Entregue o antídoto - deixa pra lá, eu mesmo vou pegá-lo de você...",
  ui_story_5071_50711302_92_dialog_content = "Com o meu poder, não terei problemas em encontrar o antídoto em você—",
  ui_story_5071_50711302_93_dialog_content = "Hã?",
  ui_story_5071_50711302_94_dialog_content = "(A presença dele... Desapareceu completamente!)",
  ui_story_5071_50711302_95_dialog_content = "Ei! Acorde! Você—",
  ui_story_5071_50711302_96_dialog_content = "...",
  ui_story_5071_50711302_97_dialog_content = "Você pode parar agora, PlayerName.",
  ui_story_5071_50711302_98_dialog_content = "Ele terminou sua vida.",
  ui_story_5071_50711302_99_dialog_content = "Eles não levaram antídoto consigo porque estavam prontos para morrer.",
  ui_story_5071_50711302_100_dialog_content = "Ainda há outros! Precisamos impedi-los de...",
  ui_story_5071_50711302_101_dialog_content = "(O que está acontecendo? Mesmo cercados por um inferno furioso... as chamas da vida estão se apagando, uma a uma...)",
  ui_story_5071_50711302_102_dialog_content = "Pare! Não faça mais isso, ou todos vocês—",
  ui_story_5071_50711302_103_dialog_content = "Uaaau—",
  ui_story_5071_50711302_104_dialog_content = "PlayerName, estou muito feliz que—",
  ui_story_5071_50711302_105_dialog_content = "Um jovem como você lamentaria o inimigo.",
  ui_story_5071_50711302_106_dialog_content = "Mas também lamento dizer que a maioria das pessoas aqui provavelmente...",
  ui_story_5071_50711302_107_dialog_content = "Como... Como eles poderiam fazer isso consigo mesmos sem hesitação? E de uma maneira tão horrível—",
  ui_story_5071_50711302_108_dialog_content = "Acredito que você já sabia a resposta.",
  ui_story_5071_50711302_109_dialog_content = "Isso é...",
  ui_story_5071_50711302_110_dialog_content = "O brasão da família Gambi... de antigamente...",
  ui_story_5071_50711302_111_dialog_content = "Uma família que eu destruí—",
  ui_story_5071_50711302_112_dialog_content = "Todos eles estão carregando algo semelhante.",
  ui_story_5071_50711302_113_dialog_content = "Este é o Colo, aquele é o Luka, e aquele pertence aos Bonas...",
  ui_story_5071_50711302_114_dialog_content = "Vejo que os líderes que se afogaram no Poço deixaram todas as suas sombras para trás—",
  ui_story_5071_50711302_115_dialog_content = "É aqui que as sombras do passado finalmente alcançam.",
  ui_story_5071_50711302_116_dialog_content = "Urgh... Há uma sensação de queimação no meu peito...",
  ui_story_5071_50711302_117_dialog_content = "Um impulso me levando a incendiar... a destruir tudo...",
  ui_story_5071_50711302_118_dialog_content = "Seu rosto...",
  ui_story_5071_50711302_119_dialog_content = "Imagino que eu não pareça agradável. Então, eu pareço bárbaro?",
  ui_story_5071_50711302_120_dialog_content = "(Que expressão aterrorizante... Até suas veias estão completamente visíveis. Ele não se parece em nada com o Senhor das Sombras de antes...)",
  ui_story_5071_50711302_121_dialog_content = "Devemos ir, Senhor das Sombras—",
  ui_story_5071_50711302_122_dialog_content = "Se não conseguirmos encontrar o antídoto aqui, tenho certeza de que podemos encontrar algo em Umbraton...",
  ui_story_5071_50711302_123_dialog_content = "De qualquer maneira, precisamos nos afastar dessas chamas!",
  ui_story_5071_50711302_124_dialog_content = "Você está certo, mas... Urgh—",
  ui_story_5071_50711302_125_dialog_content = "Apenas se apoie em mim! Eu vou nos tirar daqui!",
  ui_story_5071_50711302_126_dialog_content = "O fogo em mim está queimando mais quente do que a chama aqui.",
  ui_story_5071_50711302_127_dialog_content = "Eu... não acho que consigo aguentar por muito mais tempo.",
  ui_story_5071_50711302_128_dialog_content = "Isto está destinado. Meu passado está me alcançando—",
  ui_story_5071_50711302_129_dialog_content = "Deixe-me e saia daqui. Eu não posso deixar você se machucar...",
  ui_story_5071_50711302_130_dialog_content = "Pare de dizer algo assim!",
  ui_story_5071_50711302_131_dialog_content = "Isso mesmo! Ainda precisamos que você resgate a Senhora Sheol!",
  ui_story_5071_50711302_132_dialog_content = "Eu gostaria de manter minha promessa também, mas... Urgh—",
  ui_story_5071_50711302_133_dialog_content = "Eles estão certos. Eu sinto que quero destruir algo...",
  ui_story_5071_50711302_134_dialog_content = "Rápido! Eu não estou brincando sobre isso. Eu...",
  ui_story_5071_50711302_135_dialog_content = "De jeito nenhum, não vou te deixar para trás! Tenho certeza que há outro jeito—",
  ui_story_5071_50711302_136_dialog_content = "Eu disse, saia daqui! Agora!",
  ui_story_5071_50711302_137_dialog_content = "Deixe-me em paz!",
  ui_story_5071_50711302_138_dialog_content = "É isso... Eu me conheço melhor do que você.",
  ui_story_5071_50711302_139_dialog_content = "Não...",
  ui_story_5071_50711302_140_dialog_content = "Deve haver outra maneira.",
  ui_story_5071_50711302_141_dialog_content = "(Tem que haver! Mesmo se—)",
  ui_story_5071_50711302_142_dialog_content = "Peço desculpas. Sei que provavelmente vai me culpar por isso mais tarde, mas não tenho outra escolha agora.",
  ui_story_5071_50711302_143_dialog_content = "PlayerName...",
  ui_story_5071_50711302_144_dialog_content = "Fique de olho em nós, Vergílio! Estamos contando com você!",
  ui_story_5071_50711302_145_option_content = "Aumento de Força!",
  ui_story_5071_50711401_1_dialog_content = "Então este é o mundo interior do Senhor Sombrio? Há tantas emoções conflitantes aqui...",
  ui_story_5071_50711401_2_dialog_content = "Eu me lembro daqui, isto é—",
  ui_story_5071_50711401_3_dialog_content = "Foi essa a voz do Senhor das Sombras?",
  ui_story_5071_50711401_4_dialog_content = "Quando a Crise de Darkover chegou, eu representei o pai e a associação interina de guildas para negociar reforços de Lumópolis. Então...",
  ui_story_5071_50711401_5_dialog_content = "Onde você está, Senhor das Sombras?",
  ui_story_5071_50711401_6_dialog_content = "Nunca imaginei que veria aquele dia novamente.",
  ui_story_5071_50711401_7_dialog_content = "Ele não pode me ouvir... Se eu não posso alcançá-lo assim, então não tenho escolha a não ser encontrar uma brecha em suas emoções.",
  ui_story_5071_50711401_8_dialog_content = "Mas para onde ele foi...",
  ui_story_5071_50711401_9_dialog_content = "Esse lugar... É algum tipo de arena?",
  ui_story_5071_50711401_10_dialog_content = "... Por que tantas pessoas se reuniram aqui?",
  ui_story_5071_50711401_11_dialog_content = "Eu também levei um grande susto... Você consegue se lembrar da última vez que tantos chefes se reuniram juntos?",
  ui_story_5071_50711401_12_dialog_content = "São... Todos essas pessoas são membros de gangues?",
  ui_story_5071_50711401_13_dialog_content = "Já que todos estão dispostos a vir e falar individualmente, quero ouvir o que todos têm a dizer.",
  ui_story_5071_50711401_14_dialog_content = "Ouvi dizer que o velho Istvan e várias guildas conspiraram para trair Umbraton, e <color=#FFB400>seu filho adotivo passará com aquele cajado como prova</color>.",
  ui_story_5071_50711401_15_dialog_content = "Quero pegar aquele cajado e ordenar à associação de guildas que distribua suprimentos e arme todos para lutar contra os Eclipsitas.",
  ui_story_5071_50711401_16_dialog_content = "Então são eles que chamaram todos aqueles nobres de Lumopolis? Esses caras estão totalmente armados e estacionados do lado de fora em uma situação de emergência. Acho que eles querem nos manter aqui.",
  ui_story_5071_50711401_17_dialog_content = "Esses caras de Lumopolis sempre estiveram procurando uma chance de ocupar Umbraton. Vamos apenas dar a eles o que querem e deixar este lugar.",
  ui_story_5071_50711401_18_dialog_content = "Mas esta é a nossa casa!",
  ui_story_5071_50711401_19_dialog_content = "Não diga isso. Eu não considero esses esgotos fedorentos como minha casa.",
  ui_story_5071_50711401_20_dialog_content = "Quer lutar comigo no Pit?",
  ui_story_5071_50711401_21_dialog_content = "Eu não concordo com esses caras de Lumópolis invadindo nosso território assim! Eles não abandonaram Umbraton e voltaram para casa porque estavam com medo do exército Eclipsite? Por que eles voltaram?",
  ui_story_5071_50711401_22_dialog_content = "Já os vimos partir uma vez, e agora eles querem guarnecer suas forças aqui? Isso é justo?",
  ui_story_5071_50711401_23_dialog_content = "Vamos parar de discutir! Se você me perguntar, deveríamos trabalhar juntos para ganhar algum dinheiro com isso! Essas pessoas pobres na cidade não têm nada a ver conosco, então vamos tirar o máximo de dinheiro que pudermos delas e usar esse dinheiro para bajular aqueles caras de Lumopolis!",
  ui_story_5071_50711401_24_dialog_content = "Você está certo. Já que estamos todos aqui, deveríamos simplesmente roubar essas guildas—",
  ui_story_5071_50711401_25_dialog_content = "Meu patrocinador está entre eles!",
  ui_story_5071_50711401_26_dialog_content = "Este é o Poço. Proponho que usemos as regras mais antigas para decidir quem fica com o cajado.",
  ui_story_5071_50711401_27_dialog_content = "Não podemos todos trabalhar juntos? Ainda não sabemos quantas pessoas vão escoltar o pessoal.",
  ui_story_5071_50711401_28_dialog_content = "Quem sobreviver até o fim pode liderar nossos homens para conquistá-lo. É tão simples quanto isso.",
  ui_story_5071_50711401_29_dialog_content = "Em seus olhos, esse funcionário é mais importante do que Umbraton?",
  ui_story_5071_50711401_30_dialog_content = "Claro! O Bastão do Pastor representa o clã do velho Istvan e até se torna o símbolo da associação das guildas...",
  ui_story_5071_50711401_31_dialog_content = "<size=45>Chega!</size>",
  ui_story_5071_50711401_32_dialog_content = "A coisa mais importante agora é o paradeiro daquele moleque Kade e da equipe. O que está demorando tanto?",
  ui_story_5071_50711401_33_dialog_content = "Essas pessoas estavam no comando de Umbraton naquela época? Que lugar horrível para se estar...",
  ui_story_5071_50711401_34_dialog_content = "Preciso usar meus poderes para encontrar o Shadowlord, e rapidamente...",
  ui_story_5071_50711401_35_dialog_content = "Ouvi dizer que o filho do velho Istvan, Valon, está indo muito bem e já está gerenciando várias guildas.",
  ui_story_5071_50711401_36_dialog_content = "Ele até nos deu muitos benefícios. Eu me pergunto o que ele pensa sobre este ataque Eclipsite.",
  ui_story_5071_50711401_37_dialog_content = "Ali! Uma versão mais jovem do Senhor das Sombras está se escondendo naquele canto—",
  ui_story_5071_50711401_38_dialog_content = "Huh? Quem é aquele na frente dele?",
  ui_story_5071_50711401_39_dialog_content = "Você ouviu isso, Kade?",
  ui_story_5071_50711401_40_dialog_content = "Estes são os chefes de Umbraton que você deseja salvar.",
  ui_story_5071_50711401_41_dialog_content = "Eu não tenho tempo para falar sobre isso, Valon. Temos que ir, o tempo não espera por ninguém!",
  ui_story_5071_50711401_X41_dialog_content = "Valon? Por que há apenas uma vaga lembrança de Valon na memória do Senhor Sombrio?",
  ui_story_5071_50711401_42_dialog_content = "Aquele jovem Senhor da Cidade me disse que nos ajudaria a superar a crise!",
  ui_story_5071_50711401_43_dialog_content = "O reforço está fora do portão, mas ainda não fez nenhum movimento, então eles estão nos dando mais respeito do que o habitual.",
  ui_story_5071_50711401_44_dialog_content = "Eu só preciso ir assinar o pacto, e eles lutarão ao lado de Umbraton contra o exército Eclipsite!",
  ui_story_5071_50711401_45_dialog_content = "Se você se mostrar agora, eles só vão atacar você. Fique e converse comigo por um tempo, e eu vou te ajudar a criar um plano.",
  ui_story_5071_50711401_46_dialog_content = "Não se preocupe, estamos seguros aqui. Ninguém vai nos ouvir.",
  ui_story_5071_50711401_47_dialog_content = "Quais são os termos deste pacto, Kade? O que você está disposto a dar a Lumópolis em troca de sua ajuda?",
  ui_story_5071_50711401_48_dialog_content = "Pessoas de Umbraton? Comércio livre? Ou serão ainda mais impostos? Eles já deixaram Umbraton para trás e só vai piorar se voltarem!",
  ui_story_5071_50711401_49_dialog_content = "Por que você trairia Umbraton apenas para se humilhar diante de Lumópolis? Você realmente desistiu do nosso sonho?",
  ui_story_5071_50711401_50_dialog_content = "Foi aprovado pelo nosso pai, bem como pela associação de guildas. Esta vara em minha mão e a carta assinada são a prova.",
  ui_story_5071_50711401_51_dialog_content = "Isso representa o consentimento unânime deles.",
  ui_story_5071_50711401_52_dialog_content = "As pessoas no fundo da sociedade de Umbraton, aquelas que foram oprimidas tanto por Lumopolis quanto pelas maiores guildas — você já perguntou como elas se sentem sobre isso?",
  ui_story_5071_50711401_53_dialog_content = "Nossa inteligência diz que a horda de Eclipsitas estará aqui em um dia, mas as forças independentes de Umbraton têm suas próprias agendas.",
  ui_story_5071_50711401_54_dialog_content = "Apesar de tudo, pai e a associação foram os primeiros a procurar Lumópolis em busca de proteção. Enquanto isso, a família Gambi e seus aliados começaram a aumentar o preço do bilhete para o transporte para fora da cidade...",
  ui_story_5071_50711401_55_dialog_content = "As pessoas mais pobres desta cidade não têm como se defender ou escapar. Tudo o que podem fazer é sentar e esperar pela morte.",
  ui_story_5071_50711401_56_dialog_content = "Vamos defendê-lo juntos!",
  ui_story_5071_50711401_57_dialog_content = "Isso não é mais do que um pensamento otimista da sua parte. A maioria das pessoas quer sair de Umbraton, mas recebi informações de que várias gangues começaram a roubar essas pessoas enquanto elas tentam fugir.",
  ui_story_5071_50711401_58_dialog_content = "Qualquer um com um mínimo de força continua a ignorar os fracos e os sofredores. Eu não sei por que Umbraton tem que ser assim, mas é isso que nossa cidade natal é...",
  ui_story_5071_50711401_59_dialog_content = "Felizmente, esses bandidos são pessoas de Umbraton de corpo e alma. Tudo o que é preciso é uma pequena provocação para fazer o sangue deles ferver.",
  ui_story_5071_50711401_60_dialog_content = "É por isso que eu tenho cutucado eles das sombras, apenas para que eles pudessem encontrar este lugar. Com algumas palavras escolhidas e a promessa de recompensas, eles devem se tornar cooperativos o suficiente.",
  ui_story_5071_50711401_61_dialog_content = "O que exatamente você quer?",
  ui_story_5071_50711401_62_dialog_content = "Eu te disse antes, Kade. Eu tenho trabalhado duro para aumentar minha força.",
  ui_story_5071_50711401_63_dialog_content = "Vou usar a invasão dos Eclipsitas para livrar Umbraton de sua praga, de uma vez por todas.",
  ui_story_5071_50711401_64_dialog_content = "Tudo o que temos que fazer é sacrificar essas pessoas, e seremos capazes de levar os inocentes em segurança para fora da cidade.",
  ui_story_5071_50711401_65_dialog_content = "Você deveria estar ao meu lado, purgando o pus podre da cidade, em vez de implorar por ajuda à sujeira de Lumopolis. Isso é o que Umbraton realmente precisa agora.",
  ui_story_5071_50711401_66_dialog_content = "Por que, Valon? Você mudou...",
  ui_story_5071_50711401_67_dialog_content = "Por que você não conseguiu uni-los contra os Eclipsitas, em vez de dividi-los com brigas internas?",
  ui_story_5071_50711401_68_dialog_content = "Qual é a diferença entre você e aqueles nobres sanguinários que estavam aqui?",
  ui_story_5071_50711401_69_dialog_content = "Esses homens são a escória de Umbraton, os líderes dos criminosos mais repugnantes que corromperam nossa cidade. Deixá-los viver só trará danos a outras pessoas.",
  ui_story_5071_50711401_70_dialog_content = "Esta é a nossa única chance, Kade! Ajude-me a nos livrar deles para que possamos levar os inocentes em segurança...",
  ui_story_5071_50711401_71_dialog_content = "As mortes deles são necessárias para a sobrevivência das pessoas mais vulneráveis de Umbraton!",
  ui_story_5071_50711401_72_dialog_content = "... E daí se eles fugiram?",
  ui_story_5071_50711401_73_dialog_content = "Lumopolis governaria Umbraton, e as pessoas daqui no futuro enfrentariam os mesmos problemas que nós enfrentamos.",
  ui_story_5071_50711401_74_dialog_content = "E haveria outro filho demoníaco como eu, nascido na sombra e rejeitado por todos.",
  ui_story_5071_50711401_75_dialog_content = "Então o ciclo começaria de novo.",
  ui_story_5071_50711401_76_dialog_content = "Não foi fácil chegar a um acordo com Lumópolis, e eu devo aproveitar esta oportunidade para um diálogo igualitário...",
  ui_story_5071_50711401_77_dialog_content = "Parece que não há como mudar sua decisão agora...",
  ui_story_5071_50711401_78_dialog_content = "<size=45><color=#FFB400>Ouçam todos, Kade está aqui!</color></size>",
  ui_story_5071_50711401_79_dialog_content = "*silêncio repentino*",
  ui_story_5071_50711401_80_dialog_content = "Valon! Como você pôde!",
  ui_story_5071_50711401_81_dialog_content = "Você ouve o som de todos esses passos? Agora você não tem escolha a não ser lutar contra todos eles e me ajudar a livrar esta cidade de sua sujeira!",
  ui_story_5071_50711401_82_dialog_content = "Mas não se preocupe. Meus homens e eu lutaremos ao seu lado, como aliados.",
  ui_story_5071_50711401_83_dialog_content = "Não sejamos impulsivos. Ainda podemos trabalhar juntos. Faremos aquele garoto entregar o cajado, então transferiremos alguns suprimentos para defesa!",
  ui_story_5071_50711401_84_dialog_content = "Urgh! Q-Quem—",
  ui_story_5071_50711401_85_dialog_content = "Alguém foi atacado! Droga, vocês têm segundas intenções e não querem trabalhar juntos, eu sabia!",
  ui_story_5071_50711401_86_dialog_content = "Vamos matar essa criança demônio primeiro e lutar pelo cajado depois!",
  ui_story_5071_50711401_87_dialog_content = "Sai da frente, não tenho tempo para você.",
  ui_story_5071_50711401_88_dialog_content = "Mãos fora do meu sinal!",
  ui_story_5071_50711401_89_dialog_content = "Eu digo, saia do caminho-",
  ui_story_5071_50711401_90_dialog_content = "Você vai morrer se não reagir, Kade. Se isso acontecer, todos os nossos sonhos morrerão com você.",
  ui_story_5071_50711401_91_dialog_content = "Droga! Sai da frente!",
  ui_story_5071_50711401_92_dialog_content = "Não tentem me impedir, pessoas de visão curta!",
  ui_story_5071_50711401_93_dialog_content = "Eu o esfaqueei. Rápido! Ajude-me—",
  ui_story_5071_50711401_94_dialog_content = "Ugh!",
  ui_story_5071_50711401_95_dialog_content = "É isso que vocês querem, suas pragas? Bem, vocês conseguiram!",
  ui_story_5071_50711401_96_dialog_content = "Não, pare! Essa luta é inútil—",
  ui_story_5071_50711401_97_dialog_content = "Transformem-se em cinzas, todos vocês!",
  ui_story_5071_50711401_98_dialog_content = "Ninguém pode me ouvir...",
  ui_story_5071_50711401_99_dialog_content = "É um massacre... Eu não sabia que o Senhor Sombrio tinha um lado tão brutal... Ele perdeu completamente o controle?",
  ui_story_5071_50711401_100_dialog_content = "Foi assim que ele acabou matando seu melhor amigo?",
  ui_story_5071_50711401_101_dialog_content = "Espere um segundo, o que estou pensando? A quebra nas emoções do Senhor Sombrio deveria estar bem aqui!",
  ui_story_5071_50711401_102_dialog_content = "Por favor, me escute! Você precisa recobrar o juízo—",
  ui_story_5071_50711402_1_dialog_content = "Os chefes são todos...",
  ui_story_5071_50711402_2_dialog_content = "Olhe! Acho que o exército de Lumópolis está se movendo. Parece que eles estão vindo para cá... certo?",
  ui_story_5071_50711402_3_dialog_content = "Você e eu somos os únicos que restaram agora...",
  ui_story_5071_50711402_4_dialog_content = "Parabéns por sobreviver ao Poço pela segunda vez, Kade.",
  ui_story_5071_50711402_5_dialog_content = "*ruge*",
  ui_story_5071_50711402_6_dialog_content = "Saia do caminho, Valon! Eu tenho que ir selar o pacto com provas...",
  ui_story_5071_50711402_7_dialog_content = "Mesmo depois de tudo isso, você ainda acredita nas mentiras de Lumópolis?",
  ui_story_5071_50711402_8_dialog_content = "Você se lembra do <color=#FFB400>sonho</color> que eu te contei uma vez, Kade?",
  ui_story_5071_50711402_9_dialog_content = "A fundação já foi estabelecida. Venha comigo, e com o poder do Cajado do Pastor, podemos unir a associação de guildas e o povo fraco de Umbraton sob nosso comando.",
  ui_story_5071_50711402_10_dialog_content = "Vamos criar um novo lar para nós, um refúgio seguro para almas perdidas como nós.",
  ui_story_5071_50711402_11_dialog_content = "Um lugar onde podemos viver em felicidade e igualdade, onde podemos viajar para qualquer lugar e fazer negócios com qualquer um na <color=#FFB400>terra</color>—",
  ui_story_5071_50711402_12_dialog_content = "(Uma guilda itinerante... Será que foi assim que a <color=#FFB400>Guilda Continental</color> começou? E a ideia de comércio livre soa exatamente como a <color=#FFB400>Guilda Cloudrover</color>!)",
  ui_story_5071_50711402_13_dialog_content = "(O sonho do Sr. Valon... Não é diferente do da Senhora Sheol! É por isso que a Sra. Hanstie continuava dizendo que ela roubou o sonho de outra pessoa!)",
  ui_story_5071_50711402_14_dialog_content = "Mas e o pai? E os trabalhadores da guilda que não querem sair?",
  ui_story_5071_50711402_15_dialog_content = "E quanto àquelas crianças enganadas para entrar em uma gangue? Se eles também não quiserem sair—",
  ui_story_5071_50711402_16_dialog_content = "... Pai e essas pessoas não estão dispostas a ir embora. Pode ter mais a ver com não querer desistir de suas perspectivas, não algum tipo de amor.",
  ui_story_5071_50711402_17_dialog_content = "Tantas pessoas foram privadas de boas vidas aqui, e elas não querem nada mais do que partir. Você realmente as forçaria a ficar aqui e morrer por esta cidade podre?",
  ui_story_5071_50711402_18_dialog_content = "Você chora pelas crianças na rua, mas aqueles que trabalham para as guildas podem ser seus pais ou irmãos!",
  ui_story_5071_50711402_19_dialog_content = "A conexão entre nós e nossa cidade natal é mais forte do que você pensa, e ninguém pode cortar esse vínculo.",
  ui_story_5071_50711402_20_dialog_content = "As pessoas podem amar ou odiar sua casa, mas nunca devem abandoná-la—",
  ui_story_5071_50711402_21_dialog_content = "Estou ficando com meu pai e defendendo nossa casa do nosso jeito.",
  ui_story_5071_50711402_22_dialog_content = "A horda de Eclipsitas chegará em breve, e o exército de Lumópolis também está se preparando para a batalha. Em pouco tempo, este lugar será mergulhado em total caos.",
  ui_story_5071_50711402_23_dialog_content = "O povo de Lumópolis não se importará se você ficar aqui para morrer!",
  ui_story_5071_50711402_24_dialog_content = "Ao menos morremos por nosso lar.",
  ui_story_5071_50711402_25_dialog_content = "Pai e eu nunca concordamos...",
  ui_story_5071_50711402_26_dialog_content = "Nunca tive a aprovação dele, ao contrário de você. No final, parece que você realmente é o melhor filho de Istvan.",
  ui_story_5071_50711402_27_dialog_content = "Mas você é diferente dele. Desde que você começou a me encorajar a seguir meu sonho, eu sabia que você era a única pessoa que poderia realmente me entender.",
  ui_story_5071_50711402_28_dialog_content = "Então, por favor, pelo bem do nosso sonho, apenas venha comigo—",
  ui_story_5071_50711402_29_dialog_content = "Nosso sonho é mudar este lugar! Se não conseguirmos resistir, o sonho se torna uma mentira.",
  ui_story_5071_50711402_30_dialog_content = "Foi difícil finalmente convencê-los a se unir. Eu não posso desistir agora...",
  ui_story_5071_50711402_31_dialog_content = "É tudo mentira, Kade! Essas pessoas estão apenas interessadas em se beneficiar! Eles logo começarão a lutar entre si!",
  ui_story_5071_50711402_32_dialog_content = "Eu entendo que as gangues decepcionam as pessoas. Mas eles não estão necessariamente além da ajuda.",
  ui_story_5071_50711402_33_dialog_content = "Muitos deles não tiveram escolha. Mas se até eu pude ter uma aspiração justa, outras pessoas também poderiam!",
  ui_story_5071_50711402_34_dialog_content = "Enquanto persistirmos, deixaremos a semente.",
  ui_story_5071_50711402_35_dialog_content = "Mesmo que não sejamos nós, um dia, de alguma forma, alguém vai realizar nosso sonho.",
  ui_story_5071_50711402_36_dialog_content = "Kade... Você tem lutado no presente todo esse tempo. Você está sendo imprudente e focando apenas no ataque, assim como quando jogamos xadrez.",
  ui_story_5071_50711402_37_dialog_content = "Punir o mal dessa maneira só vai destruir tudo à nossa frente. Desde quando você... conseguiu ver além disso?",
  ui_story_5071_50711402_38_dialog_content = "Umbraton dependerá de si mesmo no futuro, mas isso não significa que não possamos fazer aliados. Não podemos lutar sozinhos, mas pedir ajuda a Lumópolis.",
  ui_story_5071_50711402_39_dialog_content = "Você é quem me fez entender o significado da amizade, Valon. Por que você mudou?",
  ui_story_5071_50711402_40_dialog_content = "Lumopolis é a fonte da escuridão de Umbraton... Enquanto eles se banham arrogantemente na luz, deixam o resto de nós presos nas sombras.",
  ui_story_5071_50711402_41_dialog_content = "Eu invejo você por deixar seu ódio ir embora e seguir em frente tão facilmente.",
  ui_story_5071_50711402_42_dialog_content = "Mas eu nunca posso perdoar essas pessoas. Comprometer-se com sujeira como eles não é diferente de fechar os olhos para suas injustiças, e eu me recuso a fazer isso.",
  ui_story_5071_50711402_43_dialog_content = "Proteger as pessoas que me importam... já exige toda a minha força.",
  ui_story_5071_50711402_44_dialog_content = "Valon...",
  ui_story_5071_50711402_45_dialog_content = "Nem uma vez você conseguiu me vencer no xadrez, Kade. O que te faz pensar que pode vencer todo Lumópolis?",
  ui_story_5071_50711402_46_dialog_content = "Quando se trata de engano, ninguém é melhor do que eles—",
  ui_story_5071_50711402_47_dialog_content = "Por favor, Kade, estou implorando. Dê-me o Bastão do Pastor e venha comigo...",
  ui_story_5071_50711402_48_dialog_content = "Eu... recuso.",
  ui_story_5071_50711402_49_dialog_content = "É assim que tem que terminar entre nós? Realmente só pode haver um vencedor no Fosso?",
  ui_story_5071_50711402_50_dialog_content = "Nunca pensei que nossas lâminas se cruzariam um dia... Mas eu...",
  ui_story_5071_50711402_51_dialog_content = "O que está acontecendo aqui? Onde está o nosso contato, Sr. Kade?",
  ui_story_5071_50711402_52_dialog_content = "!",
  ui_story_5071_50711402_53_dialog_content = "Você não tem permissão para entrar!",
  ui_story_5071_50711402_54_dialog_content = "Eu não tenho tempo para lidar com vocês. Onde está o Sr. Kade?",
  ui_story_5071_50711402_55_dialog_content = "Escória de Lumopolis! Como ousam arrastar seu exército para nossa casa!",
  ui_story_5071_50711402_56_dialog_content = "Expulse-os daqui!",
  ui_story_5071_50711402_57_dialog_content = "Não sejam tão arrogantes, seus reles que vivem nos fossos de Umbraton.",
  ui_story_5071_50711402_58_dialog_content = "Derrote-os e descubra onde Kade está. Não deixe que ele seja morto por essa escória.",
  ui_story_5071_50711402_59_dialog_content = "Malditos habitantes de Lumopolis! Urgh!",
  ui_story_5071_50711402_60_dialog_content = "Está aí, Sr. Kade? Porque já faz algum tempo desde a nossa hora de reunião acordada, nós...",
  ui_story_5071_50711402_61_dialog_content = "É realmente esse o seu plano, Kade?",
  ui_story_5071_50711402_62_dialog_content = "Você realmente está disposto a se rebaixar tanto? Que desgraça!",
  ui_story_5071_50711402_63_dialog_content = "Recue. Você não pode entrar em Umbraton desse jeito.",
  ui_story_5071_50711402_64_dialog_content = "Sr. Kade, eu não acho que você tenha uma compreensão suficiente do que é um compromisso. Um acordo é mais importante do que qualquer coisa.",
  ui_story_5071_50711402_65_dialog_content = "Reforços!",
  ui_story_5071_50711402_66_dialog_content = "Você traiu todo o Umbraton ao deixar esses cães entrarem em nossa casa!",
  ui_story_5071_50711402_67_dialog_content = "Morador de Umbraton! Cuidado com a linguagem!",
  ui_story_5071_50711402_68_dialog_content = "Eu não vou deixar você profanar minha casa!",
  ui_story_5071_50711402_69_dialog_content = "Não ataque. Abaixe a arma, Valon!",
  ui_story_5071_50711402_70_dialog_content = "Recuar! Recuar! Droga, a Luminática daquele cara—",
  ui_story_5071_50711402_71_dialog_content = "O comandante foi ferido! Retaliate! Retorne o golpe neles!",
  ui_story_5071_50711402_72_dialog_content = "Vocês, arrogantes tolos, não vão escapar tão facilmente! Eu—",
  ui_story_5071_50711402_73_dialog_content = "(Oh, não, os soldados de Lumópolis estão atirando indiscriminadamente... Preciso impedi-los!)",
  ui_story_5071_50711402_74_dialog_content = "(Ratos, eu simplesmente não consigo parar com tudo isso...)",
  ui_story_5071_50711402_75_dialog_content = "<color=#e8d9bb>Bang—</color>",
  ui_story_5071_50711402_76_dialog_content = "V-Você escória... Kade—",
  ui_story_5071_50711402_77_dialog_content = "<size=40>Valon!</size>",
  ui_story_5071_50711402_78_dialog_content = "<size=50>Ahhhh!</size>",
  ui_story_5071_50711402_79_dialog_content = "Fora! Todos vocês, fora!",
  ui_story_5071_50711402_80_dialog_content = "Vamos recuar agora! Esse cara enlouqueceu e não se importa mais com o acordo. Retiro!",
  ui_story_5071_50711402_81_dialog_content = "Retiro! Volte, agora!",
  ui_story_5071_50711402_82_dialog_content = "Valon...",
  ui_story_5071_50711402_83_dialog_content = "Kade... As coisas sempre parecem ir de mal a pior aqui em Umbraton. Como vamos salvar este lugar agora?",
  ui_story_5071_50711402_84_dialog_content = "A sombra de Lumopolis... apagará as chamas... E Umbraton nunca será purificado...",
  ui_story_5071_50711402_85_dialog_content = "Agora quem será... o salvador dos oprimidos...",
  ui_story_5071_50711402_86_dialog_content = "É possível! É possível, Valon. Só me dê mais tempo. Só temos que passar por essa crise...",
  ui_story_5071_50711402_87_dialog_content = "Seu sonho ainda pode se tornar realidade, e este lugar vai prosperar!",
  ui_story_5071_50711402_88_dialog_content = "Heheh... Você realmente é... muito ingênuo...",
  ui_story_5071_50711402_89_dialog_content = "Não conte ao pai o que eu fiz... não porque eu esteja envergonhado... mas porque eu não quero que ele sofra...",
  ui_story_5071_50711402_90_dialog_content = "... Eu prometo.",
  ui_story_5071_50711402_91_dialog_content = "Aproxime-se, irmão... Ainda tenho algo para te dizer...",
  ui_story_5071_50711402_92_dialog_content = "*tossindo* ... Somos homens de Umbraton, de corpo e alma. A violência nunca sairá de nossos corações...",
  ui_story_5071_50711402_93_dialog_content = "Já que não consigo te impedir de fazer tudo isso, pelo menos mantenha sua promessa para mim...",
  ui_story_5071_50711402_94_dialog_content = "A partir de agora, você terá que fazer o que for necessário para manter Umbraton vivo...",
  ui_story_5071_50711402_95_dialog_content = "Eu... prometo.",
  ui_story_5071_50711402_96_dialog_content = "Meu irmão.",
  ui_story_5071_50711402_97_dialog_content = "...",
  ui_story_5071_50711402_98_dialog_content = "Não... Não... Você não fez isso de jeito nenhum, fez, Senhor Sombrio?",
  ui_story_5071_50711402_99_dialog_content = "... Aquelas pessoas foram atraídas pelo alvoroço e só entraram em Umbraton para garantir que o pacto fosse cumprido.",
  ui_story_5071_50711402_100_dialog_content = "Eles eram muito distantes para nos mostrar respeito, mas nós éramos um pouco sensíveis demais. Não aprendemos a cooperar até que pagamos o preço.",
  ui_story_5071_50711402_101_dialog_content = "Mas isso me absolve dos meus pecados?",
  ui_story_5071_50711402_102_dialog_content = "Uma pessoa sábia uma vez disse, \"O poder das palavras pode prender a alma.\"",
  ui_story_5071_50711402_103_dialog_content = "Então eu simplesmente não consigo me libertar das palavras de Valon.",
  ui_story_5071_50711501_1_dialog_content = "Para preservar nossa aliança com Lumópolis, nunca expliquei a morte de Valon para ninguém. De qualquer forma, foi tudo minha culpa.",
  ui_story_5071_50711501_2_dialog_content = "Mas isso claramente não é a verdade...",
  ui_story_5071_50711501_3_dialog_content = "Quando me tornei uma Criança de Istvan, jurei nunca matar os meus ou prejudicar os interesses da nossa família...",
  ui_story_5071_50711501_4_dialog_content = "Mas no final, eu quebrei aquele voto. Não importa como alguém visse, eu não tinha o direito de enfrentar nosso Pai.",
  ui_story_5071_50711501_5_dialog_content = "E ainda assim, pouco antes de morrer, nosso Pai escolheu deixar tudo em minhas mãos. E assim, \"Istvan\" se tornou meu novo nome.",
  ui_story_5071_50711501_6_dialog_content = "Senhor das Sombras...",
  ui_story_5071_50711501_7_dialog_content = "Decidi me tornar uma Sombra...",
  ui_story_5071_50711501_8_dialog_content = "Viverei na escuridão como uma sombra e recorrerei a qualquer coisa para garantir a sobrevivência de Umbraton.",
  ui_story_5071_50711501_9_dialog_content = "Escondi o passado de mim mesmo por tanto tempo que mal consigo me lembrar... Mas os pecados do meu passado ainda me assombram como pesadelos.",
  ui_story_5071_50711501_10_dialog_content = "Um preço justo em troca da minha sobrevivência.",
  ui_story_5071_50711501_11_dialog_content = "Não... Isso não é justo de jeito nenhum.",
  ui_story_5071_50711501_12_dialog_content = "Pelo futuro de Umbraton, estou disposto a sacrificar tudo. É assim que eu sempre fiz as coisas.",
  ui_story_5071_50711501_13_dialog_content = "Como o homem arrogante que sou, sacrificarei tudo e assumirei a responsabilidade por tudo. Valon... Ele foi o primeiro \"preço\" que tive que pagar.",
  ui_story_5071_50711501_14_dialog_content = "Você não fez nada de errado... Você sabe disso, certo? Mas ainda assim escolhe se punir dessa maneira.",
  ui_story_5071_50711501_15_dialog_content = "... Eu tomei essa decisão pelo bem de Umbraton, e as consequências são minhas para suportar. Independentemente de certo ou errado, eu só desejo proteger esta cidade.",
  ui_story_5071_50711501_16_dialog_content = "Sempre acreditei que alguém se destacará neste lugar de escuridão algum dia, uma pessoa que acabará por me suceder.",
  ui_story_5071_50711501_17_dialog_content = "Estou feliz em dizer que posso ver esse desejo se tornando realidade em breve.",
  ui_story_5071_50711501_18_dialog_content = "Se você realmente se sente assim, então por que ainda está preso nessas memórias...?",
  ui_story_5071_50711501_19_dialog_content = "Por que, de fato... Quando acordo no meio da noite, às vezes me faço a mesma pergunta.",
  ui_story_5071_50711501_20_option_content = "É por causa da sua culpa.",
  ui_story_5071_50711501_21_dialog_content = "Você está dizendo que eu ainda me culpo?",
  ui_story_5071_50711501_22_option_content = "É por causa do seu arrependimento.",
  ui_story_5071_50711501_23_dialog_content = "Arrependimento... Você acha que é isso que eu sinto?",
  ui_story_5071_50711501_24_dialog_content = "Acho que, em algum lugar profundo do seu coração, você sempre sentiu remorso sobre essas coisas.",
  ui_story_5071_50711501_X24_dialog_content = "É por isso que você não conseguia se lembrar de como Valon se parecia.",
  ui_story_5071_50711501_X25_dialog_content = "...",
  ui_story_5071_50711501_25_dialog_content = "Você realmente não considerou contar a verdade para as pessoas?",
  ui_story_5071_50711501_26_dialog_content = "A verdade pode cortar mais fundo do que qualquer lâmina às vezes. Pela paz, devo continuar essa farsa, não importa o quão superficial possa ser.",
  ui_story_5071_50711501_27_dialog_content = "Eu não me arrependo de nada—",
  ui_story_5071_50711501_28_dialog_content = "Você deveria ter percebido isso até agora... Mas você tem vivido em culpa e remorso todo esse tempo.",
  ui_story_5071_50711501_29_dialog_content = "Remorso por não contar a verdade ao Sr. Valon e ao velho Istvan.",
  ui_story_5071_50711501_30_dialog_content = "Perspicaz como sempre, mas essas velhas sombras já se foram há muito tempo. Nunca terei a chance de me reconciliar com eles novamente.",
  ui_story_5071_50711501_31_dialog_content = "É por isso que você começou a se punir... E a se prender neste pesadelo...",
  ui_story_5071_50711501_32_dialog_content = "Interpretei meu papel por tanto tempo que mal consigo distinguir a diferença. Eu me tornei um com as sombras, ou as sombras estão simplesmente desempenhando meu papel?",
  ui_story_5071_50711501_33_dialog_content = "Tudo o que eu fiz... Será que realmente é suficiente?",
  ui_story_5071_50711501_34_dialog_content = "Você já desistiu de tanto por Umbraton...",
  ui_story_5071_50711501_35_dialog_content = "Se eu não tivesse hesitado, se eu tivesse parado Valon quando tive a chance, talvez as coisas tivessem sido diferentes—",
  ui_story_5071_50711501_36_dialog_content = "Eu nunca quis pagar o preço com a vida dele.",
  ui_story_5071_50711501_37_dialog_content = "Heh... Se ainda consigo sentir isso, então parece que o velho Kade ainda existe dentro de mim. Depois de todo esse tempo, ainda estou desesperado pelo seu perdão, minha querida amiga...",
  ui_story_5071_50711501_38_dialog_content = "Ei—",
  ui_story_5071_50711501_39_dialog_content = "Hahahahaha—",
  ui_story_5071_50711501_40_dialog_content = "Senhor das Sombras?",
  ui_story_5071_50711501_41_dialog_content = "Talvez eu realmente tenha envelhecido. Será que realmente perdi a paixão da minha juventude?",
  ui_story_5071_50711501_42_dialog_content = "Como pude permitir que me entregasse a tais pensamentos?",
  ui_story_5071_50711501_43_dialog_content = "Você finalmente voltou a si, Senhor das Sombras!",
  ui_story_5071_50711501_44_dialog_content = "Não é suficiente, ainda não é suficiente!",
  ui_story_5071_50711501_45_dialog_content = "Há mais fúria ardente para ser liberada!",
  ui_story_5071_50711501_46_dialog_content = "(As emoções do Senhor Sombrio estão começando a se estabilizar, mas eu sinto algo mais em seu coração. Algo tênue...)",
  ui_story_5071_50711501_47_dialog_content = "Se não fosse pela sua ajuda agora, eu teria esquecido as lições do passado. As sombras existem para me lembrar de não cometer os mesmos erros novamente.",
  ui_story_5071_50711501_48_dialog_content = "Chega de enrolação!",
  ui_story_5071_50711501_49_dialog_content = "Se eles querem brutalidade, então brutalidade é o que vão receber! Não vou mais me conter!",
  ui_story_5071_50711501_50_dialog_content = "Você está quase lá, Senhor Sombrio! Acorde!",
  ui_story_5071_50711501_51_dialog_content = "(Funcionou? Meu corpo... Minha consciência está ficando embaçada... Como se eu estivesse sendo puxado daqui...)",
  ui_story_5071_50711501_52_dialog_content = "Senhor Sombrio... Estarei te esperando do lado de fora...",
  ui_story_5071_50711501_53_dialog_content = "Obrigado, gentil Celestita.",
  ui_story_5071_50711501_54_dialog_content = "Eu também deveria...",
  ui_story_5071_50711501_55_dialog_content = "Kade.",
  ui_story_5071_50711501_56_dialog_content = "?!",
  ui_story_5071_50711501_57_dialog_content = "Sinceramente... já faz muito tempo.",
  ui_story_5071_50711501_58_dialog_content = "Valon...?",
  ui_story_5071_50711501_59_dialog_content = "Kade... Eu tenho uma pergunta que quero que você responda novamente.",
  ui_story_5071_50711501_60_dialog_content = "Você pode olhar nos meus olhos e responder sinceramente?",
  ui_story_5071_50711501_61_dialog_content = "...",
  ui_story_5071_50711501_62_dialog_content = "Qual preço você está disposto a pagar para salvar Umbraton?",
  ui_story_5071_50711501_63_dialog_content = "... Você realmente precisa perguntar?",
  ui_story_5071_50711501_64_dialog_content = "Tudo! Eu vou pagar tudo!",
  ui_story_5071_50711501_65_dialog_content = "É bem a sua cara... dizer isso, Kade...",
  ui_story_5071_50711501_66_dialog_content = "Agora vá, meu irmão! Mostre a todos os inimigos de Umbraton sua determinação!",
  ui_story_5071_50711501_67_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5071_50711501_68_dialog_content = "Heh, não achei que eu poderia durar tanto tempo.",
  ui_story_5071_50711501_69_dialog_content = "O dirigível está prestes a explodir. Você realmente acredita que Kade vai voltar?",
  ui_story_5071_50711501_70_dialog_content = "Sim. E PlayerName também me prometeu voltar com o Shadowlord.",
  ui_story_5071_50711501_71_dialog_content = "Kade não é nada além de uma existência vazia... Mesmo que ele sobreviva, ele não poderia possivelmente te salvar agora.",
  ui_story_5071_50711501_72_dialog_content = "Seu verdadeiro rosto só vai encher todos vocês de desespero.",
  ui_story_5071_50711501_73_dialog_content = "Senhora Hanstie, estamos aqui...",
  ui_story_5071_50711501_74_dialog_content = "Mais reforços mesmo agora?",
  ui_story_5071_50711501_75_dialog_content = "E até conseguiu que os Eclipsitas lutassem por ela? Isso piorou muito.",
  ui_story_5071_50711501_76_dialog_content = "Concentre seus ataques! Não dê a ela a chance de recuperar o fôlego!",
  ui_story_5071_50711501_77_dialog_content = "Senhor das Sombras...",
  ui_story_5071_50711501_78_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5071_50711501_79_dialog_content = "O que está acontecendo?",
  ui_story_5071_50711501_80_dialog_content = "Houve uma grande explosão repentina...",
  ui_story_5071_50711501_81_dialog_content = "E-Espere! O que é isso?",
  ui_story_5071_50711501_82_dialog_content = "Há alguém no fogo... C-Pode ser...",
  ui_story_5071_50711501_83_dialog_content = "Senhor das Sombras!!!",
  ui_story_5071_50711501_84_dialog_content = "Milhares de cicatrizes... e chamas azuis ferozes. É ele...",
  ui_story_5071_50711501_85_dialog_content = "<size=45>Esse é o demônio do The Pit!!!</size>",
  ui_story_5071_50711501_86_dialog_content = "Ele não pode ser derrotado... Ele é uma lenda invencível... Como podemos possivelmente...",
  ui_story_5071_50711501_87_dialog_content = "Sem correr, seus covardes! Nosso objetivo é vingar-nos desse homem!",
  ui_story_5071_50711501_88_dialog_content = "Por mais velho que ele esteja agora, não há como ele possivelmente derrotar tantos oponentes...",
  ui_story_5071_50711501_89_dialog_content = "Mesmo depois de tudo isso, você ainda quer fugir?",
  ui_story_5071_50711501_90_dialog_content = "N-Nós não vamos deixar você!",
  ui_story_5071_50711501_91_dialog_content = "Você está atrasado, Senhor Sombrio. A velhice está te alcançando?",
  ui_story_5071_50711501_92_dialog_content = "Perdoe-me, Sheol. Você estava certo - eu estive preso atrás de uma máscara tão triste todo esse tempo.",
  ui_story_5071_50711501_93_dialog_content = "Mas agora, acho que é hora de deixar minha velha sombra retornar.",
  ui_story_5071_50711501_94_dialog_content = "Ava... Minha hesitação é o que me fez perder Valon.",
  ui_story_5071_50711501_95_dialog_content = "Mas eu não vou hesitar mais - Mesmo que você seja meu inimigo.",
  ui_story_5071_50711501_96_dialog_content = "Silêncio! Você não tem o direito de falar o nome de Valon!",
  ui_story_5071_50711501_97_dialog_content = "Quando esse incidente começou, eu sabia que você tinha uma mão nisso o tempo todo—",
  ui_story_5071_50711501_98_dialog_content = "Você é livre para buscar vingança contra mim, mas deveria ter deixado os inocentes em paz.",
  ui_story_5071_50711501_99_dialog_content = "Cale a boca! Cala a boca! Você não faz ideia do quanto eu sofri!",
  ui_story_5071_50711501_100_dialog_content = "Fiz tantas coisas indizíveis, tudo por este momento!",
  ui_story_5071_50711501_101_dialog_content = "Pintei tantas falsificações repugnantes por dinheiro... E para te expor, realizei tantos experimentos repugnantes...",
  ui_story_5071_50711501_102_dialog_content = "Toda a força e as pessoas que reuni ao longo dos anos, tudo para que pudéssemos ter nossa vingança!",
  ui_story_5071_50711501_103_dialog_content = "Seu plano falhou. A mente do Senhor das Sombras está perfeitamente estável agora; ele nunca mais perderá o controle!",
  ui_story_5071_50711501_104_dialog_content = "É mesmo? Muito bem então... Se você insiste em manter seu disfarce inútil...",
  ui_story_5071_50711501_105_dialog_content = "Então vou apaziguar o espírito de Valon matando você mesmo!",
  ui_story_5071_50711501_106_dialog_content = "Todos vocês, ataquem!",
  ui_story_5071_50711501_107_dialog_content = "Esses vendidos patéticos são toda a ajuda que você conseguiu obter?",
  ui_story_5071_50711501_108_dialog_content = "Urgh—",
  ui_story_5071_50711501_109_dialog_content = "Não nos subestime, Ava!",
  ui_story_5071_50711501_110_dialog_content = "N-Não somos páreo para ele. Corre!",
  ui_story_5071_50711501_111_dialog_content = "A escuridão que Valon e eu conquistamos no passado é muito maior do que qualquer coisa que você já viu!",
  ui_story_5071_50711501_112_dialog_content = "V-Você monstro...",
  ui_story_5071_50711501_113_dialog_content = "O-O Senhor Sombrio está ficando selvagem—",
  ui_story_5071_50711501_114_dialog_content = "Agora que toda a graça foi posta de lado, prepare-se para implorar por misericórdia!",
  ui_story_5071_50711501_115_dialog_content = "C-Como pode ser isso?! Seu corpo está coberto de feridas, então por que ele...",
  ui_story_5071_50711501_116_dialog_content = "Continue atacando! Ele deve estar perdendo força agora!",
  ui_story_5071_50711501_117_dialog_content = "Perdendo força? Eu estou apenas aquecendo!",
  ui_story_5071_50711501_118_dialog_content = "T-Tudo foi queimado em cinzas... Esse cara é eterno...",
  ui_story_5071_50711501_119_dialog_content = "Grrrrr!",
  ui_story_5071_50711501_120_dialog_content = "Isto é o que ele tem escondido, uma aparência em chamas no caos...",
  ui_story_5071_50711501_121_dialog_content = "Você está feliz agora?",
  ui_story_5071_50711501_122_dialog_content = "Parabéns, essa é a fera que você queria, não é?",
  ui_story_5071_50711501_123_dialog_content = "D-Depressa! Traga aquela coisa agora mesmo!!!",
  ui_story_5071_50711501_124_dialog_content = "Eu pagarei qualquer preço, então apenas traga...",
  ui_story_5071_50711501_125_dialog_content = "<size=50>Ava—!!!</size>",
  ui_story_5071_50711502_1_dialog_content = "Vocês todos viram isso? Até aquele Eclipsite não conseguiu detê-lo. Istvan é o verdadeiro monstro!",
  ui_story_5071_50711502_2_dialog_content = "Fugindo, não é?",
  ui_story_5071_50711502_3_dialog_content = "Não chegue mais perto—",
  ui_story_5071_50711502_4_dialog_content = "!",
  ui_story_5071_50711502_5_dialog_content = "Valon...",
  ui_story_5071_50711502_6_dialog_content = "Você gostaria que eu poupasse ela?",
  ui_story_5071_50711502_7_dialog_content = "Socorro—",
  ui_story_5071_50711502_8_dialog_content = "Você é patética, Ava!",
  ui_story_5071_50711502_9_dialog_content = "Não...",
  ui_story_5071_50711502_10_dialog_content = "Desista. Não vou te machucar, mas você receberá a justiça que merece.",
  ui_story_5071_50711502_11_dialog_content = "Vou continuar o sonho de Valon, nosso sonho.",
  ui_story_5071_50711502_12_dialog_content = "Esse sonho... obviamente despedaçado...",
  ui_story_5071_50711502_13_dialog_content = "É uma pena, Ava, eu nunca pensei que você cairia tão baixo.",
  ui_story_5071_50711502_14_dialog_content = "Especialmente quando você era de Valon...",
  ui_story_5071_50711502_15_dialog_content = "Não diga isso para mim. Eu não preciso da sua pena!",
  ui_story_5071_50711502_16_dialog_content = "Você não pode chegar tão longe sem muita ajuda.",
  ui_story_5071_50711502_17_dialog_content = "Aqueles que me odeiam se aproveitaram de você... Isso é imperdoável!",
  ui_story_5071_50711502_18_dialog_content = "...",
  ui_story_5071_50711502_19_dialog_content = "Se você não está disposto a revelar, eu descobrirei quem eles são por conta própria.",
  ui_story_5071_50711502_20_dialog_content = "Mas eu prometo a você, você terá um julgamento justo.",
  ui_story_5071_50711502_21_dialog_content = "Pare de derramar lágrimas de jacaré. Isso é nojento!",
  ui_story_5071_50711502_22_dialog_content = "Você matou Valon e tirou tudo dele, mas não foi julgado.",
  ui_story_5071_50711502_23_dialog_content = "Por que deveríamos ser seu cordeiro sacrificial?",
  ui_story_5071_50711502_24_dialog_content = "Eu te amaldiçoo! May que seu coração fique preso para sempre no abismo!",
  ui_story_5071_50711502_25_dialog_content = "... Há muito tempo atrás, Valon e eu ainda tínhamos esperança nas leis e regras de Umbraton.",
  ui_story_5071_50711502_26_dialog_content = "Ele ansiava por uma nova ordem e confiou esse sonho a mim.",
  ui_story_5071_50711502_27_dialog_content = "Se possível, eu preferiria não te cobrar por isso.",
  ui_story_5071_50711502_28_dialog_content = "Valon...",
  ui_story_5071_50711502_29_dialog_content = "Você fundou a Guilda Continental para Valon, não foi?",
  ui_story_5071_50711502_30_dialog_content = "Mesmo quando você está cheio de ódio, por amor você ainda mantém essa pureza...",
  ui_story_5071_50711502_31_dialog_content = "Chega, pare...",
  ui_story_5071_50711502_32_dialog_content = "Eu me escondi nas sombras tempo suficiente para saber que tipo de pessoa está além da ajuda.",
  ui_story_5071_50711502_33_dialog_content = "Ava, ainda há pureza em seu coração.",
  ui_story_5071_50711502_34_dialog_content = "Essa é a sombra do seu passado.",
  ui_story_5071_50711502_35_dialog_content = "Portanto, eu prometo a você aqui e agora—",
  ui_story_5071_50711502_36_dialog_content = "Um dia, quando você tiver expiado seus crimes e eu tiver terminado de reformar Umbraton...",
  ui_story_5071_50711502_37_dialog_content = "Você está convidado a tirar minha vida.",
  ui_story_5071_50711502_38_dialog_content = "Você...",
  ui_story_5071_50711502_39_dialog_content = "Lá lá, vejo os Guardiões vindo com equipes de resgate.",
  ui_story_5071_50711502_40_dialog_content = "Diga a eles tudo o que você tem a dizer.",
  ui_story_5071_50711502_41_dialog_content = "... Me solta!",
  ui_story_5071_50711502_42_dialog_content = "Por que eu?",
  ui_story_5071_50711502_43_dialog_content = "O verdadeiro açougueiro está bem na sua frente!",
  ui_story_5071_50711502_44_dialog_content = "Olhe para ele, veja essas cicatrizes feias! Você não entende?",
  ui_story_5071_50711502_45_dialog_content = "Ele é o maior pecador e inimigo de Umbraton!",
  ui_story_5071_50711502_46_dialog_content = "Você esqueceu como sua mãe morreu?",
  ui_story_5071_50711502_47_dialog_content = "...",
  ui_story_5071_50711502_48_dialog_content = "Eu realmente não fui feito para isso. Apressem-se, Guardiões!",
  ui_story_5071_50711502_49_dialog_content = "Todos vocês viram através dele, certo?",
  ui_story_5071_50711502_50_dialog_content = "Tremam de medo, todos e todos aqueles que desejam permanecer ao lado dele!",
  ui_story_5071_50711502_51_dialog_content = "A verdade virá à tona um dia!",
  ui_story_5071_50711502_52_dialog_content = "<color=#FFB400>Eu te amaldiçoo, Kade!</color>",
  ui_story_5071_50711601_1_dialog_content = "A causa da morte de Yvonne finalmente é tornada pública e é veneno. Ela ainda estava no auge quando Hanstie a assassinou.",
  ui_story_5071_50711601_2_dialog_content = "Lamento não ter tido mais conversas com ela.",
  ui_story_5071_50711601_3_dialog_content = "Ela era uma pessoa tão boa...",
  ui_story_5071_50711601_4_dialog_content = "Vergil também levou muito a sério e não dormiu ou comeu por dias. Vou ter que atribuir mais trabalho para tirar a mente dele disso.",
  ui_story_5071_50711601_5_dialog_content = "Não acho que você deveria sobrecarregá-lo assim, Senhora Sheol...",
  ui_story_5071_50711601_6_dialog_content = "Em memória da Sra. Yvonne, estamos lançando seus livros. Este é o primeiro lote.",
  ui_story_5071_50711601_7_dialog_content = "Por favor, entregue algumas cópias ao Senhor Sombrio.",
  ui_story_5071_50711601_8_dialog_content = "Tenho certeza de que isso deixaria o Senhor Sombrio realmente feliz... Hã? O que são todos esses livros atrás de você?",
  ui_story_5071_50711601_9_dialog_content = "Ah, isso! Essa é a nova impressão da Sra. Red Mercury, minha série favorita.",
  ui_story_5071_50711601_X9_dialog_content = "Os lírios na capa são tão simples e bonitos... Como é apropriado para a Sra. Mercúrio Vermelho... e para sua mãe também...",
  ui_story_5071_50711601_X10_dialog_content = "Memórias eternas, amor intransponível e bênçãos profundas. Isso é o que os lírios simbolizam.",
  ui_story_5071_50711601_X11_dialog_content = "... Sem perguntas?",
  ui_story_5071_50711601_X12_dialog_content = "Você já me contou sobre minha mãe, certo?",
  ui_story_5071_50711601_X13_dialog_content = "Sim.",
  ui_story_5071_50711601_X14_dialog_content = "Então o que há para perguntar?",
  ui_story_5071_50711601_X15_dialog_content = "... A verdade é uma espada de dois gumes. Às vezes, optei por mentiras brancas.",
  ui_story_5071_50711601_X16_dialog_content = "Sua mãe realmente morreu de doença, da depressão que ela caiu tentando te encontrar.",
  ui_story_5071_50711601_X17_dialog_content = "Visitei-a em seu leito de morte e ouvi seu último pedido.",
  ui_story_5071_50711601_X18_dialog_content = "Foi o grande amor que uma mãe tinha por sua filha. Eu não queria que você se sentisse culpada, então...",
  ui_story_5071_50711601_X19_dialog_content = "Posso contar isso como outro favor que você me deve?",
  ui_story_5071_50711601_X20_dialog_content = "... Só brincando. Obrigado, tio.",
  ui_story_5071_50711601_X21_dialog_content = "Apenas não faça mais isso.",
  ui_story_5071_50711601_X22_dialog_content = "A honestidade deve ser a política para fazer negócios em Umbraton.",
  ui_story_5071_50711601_X23_dialog_content = "Haha, vou manter esse conselho em mente, Senhora Sheol.",
  ui_story_5071_50711601_X24_dialog_content = "A mãe ficará feliz em saber que os lírios também são perfeitos para mim!",
  ui_story_5071_50711601_10_dialog_content = "Que pena que estou muito ocupado para ler em paz.",
  ui_story_5071_50711601_11_dialog_content = "É uma pena o que aconteceu com a aeronave...",
  ui_story_5071_50711601_12_dialog_content = "Tudo bem, não é a primeira vez que isso acontece comigo. Você ganha algumas, perde outras. É assim que os negócios funcionam.",
  ui_story_5071_50711601_13_dialog_content = "Eu sou livre para fazer negócios em qualquer lugar sem um dirigível de qualquer maneira.",
  ui_story_5071_50711601_14_dialog_content = "Fico aliviado em ouvir isso e ver o quão otimista você é sobre tudo, Senhora Sheol! Cuide-se!",
  ui_story_5071_50711601_15_dialog_content = "Estou feliz que meu querido PlayerName está me consolando, mas fazer isso com seu Colossus a reboque me incomoda um pouco.",
  ui_story_5071_50711601_16_dialog_content = "Desculpe—",
  ui_story_5071_50711601_17_dialog_content = "Certo...",
  ui_story_5071_50711601_18_dialog_content = "Você vai e voa orgulhosamente com nossos sonhos a reboque...",
  ui_story_5071_50711601_19_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5071_50711601_20_dialog_content = "Digitar.",
  ui_story_5071_50711601_21_dialog_content = "Sou eu, Senhor das Sombras. Vim entregar alguns livros— Hã?",
  ui_story_5071_50711601_22_dialog_content = "O que é? Minha aparência te assustou?",
  ui_story_5071_50711601_23_dialog_content = "O que houve?",
  ui_story_5071_50711601_24_dialog_content = "A fumaça nas sombras ainda não se dissipou— Algo me diz que a luta ainda não acabou.",
  ui_story_5071_50711601_25_dialog_content = "... Eu vou apenas deixar esses livros aqui.",
  ui_story_5071_50711601_26_dialog_content = "Sheol realmente gosta de te enviar em recados assim... Obrigado.",
  ui_story_5071_50711601_27_dialog_content = "Você ainda tem pesadelos hoje em dia?",
  ui_story_5071_50711601_28_dialog_content = "Haha, isso tudo depende de como você define \"pesadelos\". Eu costumava ser prisioneiro da minha culpa, e meus sonhos estavam cheios de memórias distorcidas do passado.",
  ui_story_5071_50711601_29_dialog_content = "Mas agora eu só sonho com a verdade nua e crua. Você chamaria meus sonhos de \"pesadelos\" agora?",
  ui_story_5071_50711601_30_dialog_content = "<color=#e8d9bb>Toc, toc, toc..</color>",
  ui_story_5071_50711601_31_dialog_content = "Por favor, fique aqui. Não há necessidade de sair.",
  ui_story_5071_50711601_32_dialog_content = "Entre-",
  ui_story_5071_50711601_33_dialog_content = "Senhor Istvan! Senhor Istvan!",
  ui_story_5071_50711601_34_dialog_content = "Meu querido Senhor Istvan... Por favor, aceite meu respeito. Você deve se lembrar de mim. Nós éramos parceiros.",
  ui_story_5071_50711601_35_dialog_content = "Se você se lembra da nossa amizade, por favor, ouça minha sincera confissão...",
  ui_story_5071_50711601_36_dialog_content = "Diga.",
  ui_story_5071_50711601_37_dialog_content = "Eu vacilei na Aeronave Cloudrover e agi de maneira inadequada com alguns amigos ruins...",
  ui_story_5071_50711601_38_dialog_content = "Quando a Guilda os fechar, nossa guilda também será... Por favor, acredite em mim! Estou sinceramente me arrependendo!",
  ui_story_5071_50711601_39_dialog_content = "Então... Por favor, tenha piedade e permita-me retornar à Guilda.",
  ui_story_5071_50711601_40_dialog_content = "Você diz que somos parceiros.",
  ui_story_5071_50711601_41_dialog_content = "Mas quando as reformas começaram, você se escondeu das sombras por medo de se envolver comigo.",
  ui_story_5071_50711601_42_dialog_content = "Não, não foi isso que aconteceu.",
  ui_story_5071_50711601_43_dialog_content = "Atrás das minhas costas, você e seus associados fizeram uma fortuna através do seu negócio clandestino...",
  ui_story_5071_50711601_44_dialog_content = "Nos seus momentos mais gloriosos, você nunca levou em consideração o meu conselho.",
  ui_story_5071_50711601_45_dialog_content = "Foi apenas depois que a Guilda sancionou seu negócio que você veio até mim pedindo perdão.",
  ui_story_5071_50711601_46_dialog_content = "E-Eu... é porque...",
  ui_story_5071_50711601_47_dialog_content = "Poupe-me de suas desculpas - Nem uma vez você me respeitou ou me viu como um parceiro de negócios.",
  ui_story_5071_50711601_48_dialog_content = "Em seus olhos, o Senhor Sombrio não é nada além de um obstáculo a ser superado.",
  ui_story_5071_50711601_49_dialog_content = "Não... não é isso. Por favor, escute-me!",
  ui_story_5071_50711601_50_dialog_content = "Vou mudar para melhor! Não vou mais conspirar com essas pessoas. Vou desistir do meu negócio clandestino!",
  ui_story_5071_50711601_51_dialog_content = "Por favor, peça à Guilda para ser leniente conosco! Deixe-nos uma saída. Eu imploro a você, Senhor Sombrio!",
  ui_story_5071_50711601_52_dialog_content = "Sair.",
  ui_story_5071_50711601_53_dialog_content = "Então... e a minha guilda... Senhor das Sombras?",
  ui_story_5071_50711601_54_dialog_content = "...",
  ui_story_5071_50711601_55_dialog_content = "Sim! Sim! Vou me perder agora! Estou indo embora agora...",
  ui_story_5071_50711601_56_dialog_content = "Lamento que você tenha que presenciar isso.",
  ui_story_5071_50711601_57_dialog_content = "<color=#FFB400>(Ele está ainda mais ameaçador do que antes!!!)</color>",
  ui_story_5071_50711601_58_dialog_content = "Para ser honesto, até eu sinto um pouco de medo ao te ver assim...",
  ui_story_5071_50711601_59_dialog_content = "Hahaha! Por favor, tire isso da sua cabeça, meu amigo - Eu só quero jogar uma partida de xadrez com você.",
  ui_story_5071_50711601_60_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5071_50711601_61_dialog_content = "Pai…",
  ui_story_5071_50711601_62_dialog_content = "... Entre.",
  ui_story_5071_50711601_63_dialog_content = "Os resultados da pesquisa saíram. Ninguém se opôs ao projeto de reforma.",
  ui_story_5071_50711601_64_dialog_content = "Estou realmente dando uma aparência tão tirânica?",
  ui_story_5071_50711601_65_dialog_content = "Não era minha intenção fazer isso, mas não vou negar sua utilidade nas negociações.",
  ui_story_5071_50711601_66_dialog_content = "Haha, suponho que isso realmente torne as coisas complicadas muito mais simples.",
  ui_story_5071_50711601_67_dialog_content = "Além disso, Pai, temos descobertas preliminares sobre quem está por trás de Hanstie.",
  ui_story_5071_50711601_68_dialog_content = "Parece que eles vão aprontar mais travessuras. Aqui estão os arquivos.",
  ui_story_5071_50711601_69_dialog_content = "Deixe-os vir.",
  ui_story_5071_50711601_70_dialog_content = "Estou preparado para qualquer batalha que eles nos tragam. Não vou me esconder mais.",
  ui_story_5071_50711601_71_dialog_content = "Umbraton já não é mais tão fraco como era antes. Nossa cidade está pronta para receber convidados como eles a qualquer momento.",
  ui_story_5071_50711601_72_dialog_content = "Kleken.",
  ui_story_5071_50711601_73_dialog_content = "Sim, meu senhor?",
  ui_story_5071_50711601_74_dialog_content = "Diga a eles para começar os preparativos. Temos muito trabalho pela frente.",
  ui_story_5071_50711601_75_dialog_content = "Entendido. Vou começar a preparar o banquete—",
  ui_story_5071_50711601_76_dialog_content = "Por favor, vá com calma, Pai.",
  ui_story_5071_50711601_77_dialog_content = "Você está ferido e envenenado. Você deve descansar o máximo que puder.",
  ui_story_5071_50711601_78_dialog_content = "(Hã? Até a atitude de Bethel parece um pouco mais relaxada agora. Eles quase parecem como um pai e filha normais...)",
  ui_story_5071_50711601_79_dialog_content = "Ainda não estou tão velho, Bethel. Deixe-me continuar com meu trabalho.",
  ui_story_5071_50711601_80_dialog_content = "Desculpe, mas eu deveria ir—",
  ui_story_5071_50711601_81_dialog_content = "Tenho certeza de que vocês têm muito trabalho a fazer, então vou me retirar.",
  ui_story_5071_50711601_82_dialog_content = "Por favor, me perdoe, eu só queria jogar uma partida com você hoje.",
  ui_story_5071_50711601_83_dialog_content = "Até a próxima, meu amigo.",
  ui_story_5071_50711601_84_dialog_content = "Tchau—",
  ui_story_5071_50711601_85_dialog_content = "O que você fez com meu pai?",
  ui_story_5071_50711601_86_dialog_content = "Todos nós estamos impressionados com as mudanças nele.",
  ui_story_5071_50711601_87_dialog_content = "E-Eu não fiz nada! O Senhor das Sombras apenas chegou a algumas conclusões por conta própria, eu prometo!",
  ui_story_5071_50711601_88_dialog_content = "É mesmo?",
  ui_story_5071_50711601_89_dialog_content = "Ok. Ele parece mais sincero e agradável agora. Eu gosto muito disso.",
  ui_story_5071_50711601_90_dialog_content = "Senhora Bethel, há mais comunicações chegando e novas reuniões que você precisa organizar.",
  ui_story_5071_50711601_91_dialog_content = "Estou chegando. Obrigada, PlayerName, e até a próxima vez.",
  ui_story_5071_50711601_92_dialog_content = "Não mencione isso. Te vejo em breve!",
  ui_story_5071_50711601_93_dialog_content = "Rápido, coloque um pouco de esforço nisso! O chefe está nos esperando!",
  ui_story_5071_50711601_94_dialog_content = "Vai, vai, vai—!",
  ui_story_5071_50711601_95_dialog_content = "(Parecem estar bem cheios de energia...)",
  ui_story_5071_50711601_96_dialog_content = "Ainda não temos ideia de quem estamos procurando, mas avante!",
  ui_story_5071_50711601_97_dialog_content = "(O sol está tão brilhante hoje. Ele já foi tão brilhante assim em Umbraton?)",
  ui_story_5071_50711601_98_dialog_content = "Cuidado! Por favor, preste atenção no trânsito mesmo se estiver transportando materiais de construção escolar!",
  ui_story_5071_50711601_99_dialog_content = "(Umbraton parece linda à luz do sol—)",
  ui_story_5071_50711601_100_dialog_content = "Apresse-se e leve as coisas que os convidados querem para o veículo de entrega...",
  ui_story_5071_50711601_101_dialog_content = "Não dê às pessoas a impressão de que a Guilda Umbraton é lenta!",
  ui_story_5071_50711601_102_dialog_content = "Parece que todos querem aproveitar o bom tempo hoje.",
  ui_story_5071_50711601_103_dialog_content = "Talvez eu deva ir ver um filme com Vice? Espero que ainda haja alguns ingressos sobrando...",
  ui_story_5071_50711601_104_dialog_content = "Este livro...",
  ui_story_5071_50711601_105_dialog_content = "Sim... Isso é perfeito para ler à luz do sol.",
  ui_story_5071_50711601_106_dialog_content = "Heh, e o sol parece estar brilhando especialmente forte hoje. Nossa cidade também...",
  ui_story_5071_50711601_107_dialog_content = "Assim como sempre sonhamos—",
  ui_story_5071_50711601_108_dialog_content = "Não é mesmo, meu velho amigo?",
  ui_story_5071_50711601_109_dialog_content = "Parece que tudo foi bem resolvido. As coisas finalmente estão em ordem agora.",
  ui_story_5071_50711601_110_dialog_content = "Aprendi muito depois de todos esses anos—",
  ui_story_5071_50711601_111_dialog_content = "Parece que eu sou um bom professor.",
  ui_story_5071_50711601_112_dialog_content = "Tão lindo... Eu nunca percebi que nossa cidade natal poderia ser tão brilhante...",
  ui_story_5071_50711601_113_dialog_content = "Após hoje, nossos sonhos para Umbraton só se tornarão mais fortes, e...",
  ui_story_5071_50711601_114_dialog_content = "Eles definitivamente serão capazes de abrir as asas e voar um dia...",
  ui_story_5071_50711601_115_dialog_content = "Aguardo ansiosamente por esse dia."
}
return config
